# ---------- workspaces (GET /api/v1/workspaces, docs/web/workspace-board.md) ----------
# A few host spaces and session folders on the mock machines: what the assistant's @ menu lists (#5594). Placeholders.
def mock_workspaces():
    rows = [("server", "herdr", "persona", "/home/me/code/persona", "master"), ("macbook", "herdr", "weather-app", "/Users/me/code/weather-app", "main"),
            ("macbook", "session", "notes", "/Users/me/notes", ""), ("studio", "herdr", "site", "/Users/me/code/site", "redesign")]
    result = [{"id": f"{m}:{src}:{i}", "machine_id": m, "source": src, "source_id": str(i), "title": t, "cwd": cwd,
             **({"branch": br} if br else {}), "online": True, "available": True, "last_seen": ago()}
            for i, (m, src, t, cwd, br) in enumerate(rows)]
    if os.environ.get("MOCK_ORCA_CHILDREN"):
        result.append({"id": "orca-collection", "machine_id": "macbook", "source": "orca", "source_id": "orca:collection",
                       "title": "Workspace collection", "cwd": "/Users/me/code", "index": 1, "online": True, "available": True})
        result.append({"id": "orca-archived", "machine_id": "macbook", "source": "orca", "source_id": "orca:archived",
                       "title": "Archived workspace", "cwd": "/Users/me/code/archived", "index": 8, "parent_source_id": "orca:collection",
                       "online": True, "available": True})
        for s in SESSIONS:
            if s.get("space_kind") == "orca":
                result.append({"id": "catalog-" + s["space_id"], "machine_id": s["machine_id"], "source": "orca",
                               "source_id": s["space_id"], "title": s["space_name"], "cwd": s["cwd"],
                               "parent_source_id": s.get("parent_space_id") or "orca:collection",
                               "index": s.get("space_index", 1), "online": True, "available": True})
        for mid, rows in WORKTREES.items():
            for wid, label, path, branch in rows:
                if (mid, wid) in WORKSPACE_LINEAGE:
                    result.append({"id": "catalog-" + wid, "machine_id": mid, "source": "orca", "source_id": wid,
                                   "title": branch, "cwd": path, "index": 20, "parent_source_id": WORKSPACE_LINEAGE[mid, wid],
                                   "online": True, "available": True})
    if os.environ.get("MOCK_PASEO"):
        for wid, title, path, branch in [(w, t, PASEO_ROOT if tree is None else PASEO_TREES + tree, b)
                                         for w, t, tree, b in PASEO_WORKSPACES] + PASEO_MADE:
            # every worktree here is one Paseo made (owned): the ones Delete worktree is offered for (#6297)
            result.append({"id": "catalog-" + wid, "machine_id": "server", "source": "paseo", "source_id": wid, "title": title,
                           "cwd": path, "branch": branch, "workspace_kind": "git", "is_main": path == PASEO_ROOT,
                           **({} if path == PASEO_ROOT else {"owned": True}),
                           "project_id": PASEO_PROJECT["id"], "project_name": PASEO_PROJECT["name"], "project_path": PASEO_ROOT,
                           "online": True, "available": True, "last_seen": ago()})
    return list({(w["machine_id"], w["source"], w["source_id"]): w for w in result}.values())


# ---------- node self-check (#2429, docs/server/machines.md "Doctor: what this computer can do") ----------
# GET /api/v1/machines/{mid}/doctor and POST …/doctor/fix: the report `personad node doctor` prints, as the hub relays it.
#   MOCK_TOKENS=none (a hub without per-machine token usage: no card tokens, the usage route 404s) | empty (nothing ran)
#               | lopsided (the server ran nearly everything, the others a thousandth as much)
#   MOCK_DOCTOR=healthy (default) | stale (hooks and MCP files out of date, "Repair" puts them right) | broken (node.sock gone)
#                | mixed (stale files, the user's own PermissionRequest hook, no runtime.sock) | old (the node has no such method)
#                | error (the check fails) | slow (the check takes MOCK_DOCTOR_SECONDS, default 3)
# MOCK_DOCTOR_OLD=macbook,studio   only these machines answer like an old node, whatever MOCK_DOCTOR says.
DOCTOR_FIXED = set()
DOCTOR_NAMES = ["node.sock", "runtime.sock", "claude-settings.json", "claude-hooks", "assistant-settings.json", "assistant-hooks",
                "mcp.json", "agent-plugin", "command-paths", "claude-version", "herdr", "global-permission-hooks"]

def doctor_check(name, status="ok", state="", detail="", hint="", items=None):
    return {"name": name, "status": status, "state": state, "detail": detail, "hint": hint, "items": items or []}

def doctor_report(mid, fixed=None):
    mode = os.environ.get("MOCK_DOCTOR", "healthy")
    if mid in DOCTOR_FIXED and mode in ("stale", "mixed", "broken"): mode = "healthy" if mode != "mixed" else "mixed-fixed"
    generated = {"claude-settings.json", "claude-hooks", "assistant-settings.json", "assistant-hooks", "mcp.json", "agent-plugin"}
    checks = []
    for n in DOCTOR_NAMES:
        if n == "node.sock":
            c = doctor_check(n, detail="已应答") if mode != "broken" else doctor_check(
                n, "fail", detail="不存在", hint="没有 node 在监听：hook 和 MCP 会静默退回终端。确认 hub 已连上这台电脑；node 重启会重建")
        elif n == "runtime.sock":
            c = doctor_check(n, detail="可连接") if not mode.startswith("mixed") else doctor_check(
                n, "warn", detail="不存在", hint="没有 node 在监听：DSH、pi 这类 runtime 连不上；没用到可忽略")
        elif n in generated:
            if mode in ("stale", "mixed") and n in ("claude-settings.json", "claude-hooks", "mcp.json"):
                c = doctor_check(n, "warn", "stale", "过期：2 处不同（differs claude-settings.json）", "重启 node 会重写；或运行 personad node doctor --fix",
                                 ["differs " + n, "differs " + n.replace(".json", "") + "/hooks/hooks.json"])
            else:
                c = doctor_check(n, detail="和当前二进制会写的一致", state="current")
        elif n == "command-paths":
            c = doctor_check(n, detail="3 个命令路径都存在且可执行")
        elif n == "claude-version":
            c = doctor_check(n, detail="2.1.320，支持 --plugin-dir")
        elif n == "herdr":
            c = doctor_check(n, detail="herdr 在监听")
        else:
            c = doctor_check(n, detail="没有同步的 PermissionRequest 钩子") if not mode.startswith("mixed") else doctor_check(
                n, "warn", detail="1 个同步的 PermissionRequest 钩子（/usr/local/bin/approve-tool）",
                hint="它们和 Persona 的手机审批同时拦着权限请求，可能互相影响；Persona 不会改这个文件，需要时自己检查", items=["/usr/local/bin/approve-tool"])
        checks.append(c)
    return {"ok": not any(c["status"] == "fail" for c in checks), "dir": "~/.persona", "checks": checks, "fixed": fixed or []}

def doctor_route(h, p, method):
    parts = p.split("/")
    if not (p.startswith("/api/v1/machines/") and len(parts) in (6, 7) and parts[5] == "doctor" and (len(parts) == 6 or parts[6] == "fix")):
        return False
    fix = len(parts) == 7
    if (method == "POST") != fix: return False
    machine = next((m for m in MACHINES if m["id"] == parts[4]), None)
    if machine is None: return h.send_json({"error": "unknown machine"}, 404) or True
    if not machine.get("online"): return h.send_json({"error": "machine is offline", "code": "node_unreachable"}, 503) or True
    mode = os.environ.get("MOCK_DOCTOR", "healthy")
    if mode == "old" or machine["id"] in {x for x in os.environ.get("MOCK_DOCTOR_OLD", "").split(",") if x}:
        return h.send_json({"error": "unknown method node.doctor" + (".fix" if fix else ""), "code": "internal"}, 502) or True
    if mode == "slow": time.sleep(float(os.environ.get("MOCK_DOCTOR_SECONDS", "3")))
    if mode == "error": return h.send_json({"error": "context deadline exceeded", "code": "timeout"}, 502) or True
    if fix:
        before = doctor_report(machine["id"])
        stale = [c["name"] for c in before["checks"] if c["state"] in ("stale", "missing")]
        DOCTOR_FIXED.add(machine["id"])
        return h.send_json(doctor_report(machine["id"], stale)) or True
    return h.send_json(doctor_report(machine["id"])) or True


# ---------- machine monitoring (docs/server/machines.md) ----------
# What each machine runs, and made-up but smooth 24-hour curves: the server is busy right now (CPU and memory
# high), the Mac Studio was away for two hours this morning (a gap), the NAS has been offline for three hours.
GB = 1 << 30
SYSTEMS = {
    "server": {"os": "linux", "distro": "ubuntu", "like": "debian", "name": "Ubuntu 24.04.1 LTS", "version": "24.04",
               "kernel": "6.8.0-48-generic", "arch": "amd64", "model": "Standard PC (Q35 + ICH9, 2009)",
               "cpu": "AMD EPYC 9354 32-Core Processor", "cores": 16, "memory": 64 * GB},
    "macbook": {"os": "darwin", "distro": "macos", "name": "macOS 26.1", "version": "26.1", "build": "25B78",
                "kernel": "Darwin 25.1.0", "arch": "arm64", "model": "MacBook Pro", "cpu": "Apple M4 Pro", "cores": 14,
                "memory": 48 * GB},
    "studio": {"os": "darwin", "distro": "macos", "name": "macOS 26.0.1", "version": "26.0.1", "build": "25A362",
               "kernel": "Darwin 25.0.0", "arch": "arm64", "model": "Mac Studio", "cpu": "Apple M2 Ultra", "cores": 24,
               "memory": 192 * GB},
    "nas": {"os": "linux", "distro": "debian", "name": "Debian GNU/Linux 12 (bookworm)", "version": "12",
            "kernel": "6.1.0-26-arm64", "arch": "arm64", "model": "Raspberry Pi 5 Model B Rev 1.0", "cpu": "", "cores": 4,
            "memory": 8 * GB},
}
MACHINE_CONCERN_LEVELS = {}
if os.environ.get("MOCK_MACHINE_CONCERNS") == "1":
    from machine_concerns import install_machines
    MACHINE_CONCERN_LEVELS.update(install_machines(MACHINES, SYSTEMS))
if not os.environ.get("MOCK_MACHINES"):  # that mode has its own offline machine (MachinePagesTests counts them)
    MACHINES.append({"id": "nas", "name": "NAS", "kind": "ssh", "icon": "server", "ssh_host": "nas", "online": False,
                     "error": "ssh: connect to host nas port 22: Operation timed out", "hostname": "nas", "os": "linux",
                     "arch": "arm64", "home": "/home/me", "last_seen": ago(hours=3)})
# MOCK_LONG_OS=1: the server's OS has a long name, so its card's chips (OS, herdr, claude) do not fit on one line.
if os.environ.get("MOCK_LONG_OS"):
    SYSTEMS["server"]["name"] = "Example GNU/Linux 2 (codename)"
    MACHINES[0]["node_mismatch"] = True
# MOCK_PERF_MACHINES=<n>: additional neutral machines with full system facts and distinct synthetic metric curves.
# Unlike MOCK_MACHINES' offline edge cases, these make a genuinely scrollable monitoring grid (#5730).
for _i in range(int(os.environ.get("MOCK_PERF_MACHINES", "0"))):
    _mid = f"perf-machine-{_i + 1:03d}"
    SYSTEMS[_mid] = dict(SYSTEMS["server"])
    MACHINES.append(dict(MACHINES[0], id=_mid, name=f"示例机器 {_i + 1:03d}", hostname=f"example-node-{_i + 1:03d}"))
if RESUME_TERMINAL:  # the Mac mini (#5521)
    SYSTEMS["mini"] = dict(SYSTEMS["macbook"], model="Mac mini", cpu="Apple M4", cores=10, memory=32 * GB)
for _m in MACHINES:
    _m["system"] = dict(SYSTEMS[_m["id"]], boot_time=int((NOW - timedelta(days=3, hours=4)).timestamp()))
# Machines added later (MOCK_MACHINES) have no system and never sent a sample.
T0 = int(NOW.timestamp())


def metrics_present(mid, t):
    """Whether the machine was sending at Unix time t."""
    if mid not in SYSTEMS:
        return False
    if mid == "studio" and T0 - 7 * 3600 <= t < T0 - 5 * 3600:
        return False
    if mid == "nas" and t >= T0 - 3 * 3600:
        return False
    return True


def metric_at(mid, t):
    """A smooth made-up reading: a daily rhythm, a few slower waves and a little jitter, by machine."""
    import math
    sys_ = SYSTEMS[mid]
    template = mid if mid in ("server", "macbook", "studio", "nas") else "server"
    h = int(hashlib.md5(f"{mid}{t // 10}".encode()).hexdigest()[:6], 16) / 0xFFFFFF  # jitter 0…1
    day = math.sin(2 * math.pi * (t % 86400) / 86400)
    wave = math.sin(t / 1900) * 0.5 + math.sin(t / 530 + len(mid)) * 0.3
    base = {"server": 38, "macbook": 18, "studio": 27, "nas": 6}[template]
    cpu = base + 10 * day + 12 * wave + 8 * h
    if mid == "server" and t > T0 - 25 * 60:  # a build running since 25 minutes before the mock started
        cpu = 92 + 6 * h  # always over the 90 % "critical" line
    cpu = max(0.5, min(99.5, cpu))
    concern_level = MACHINE_CONCERN_LEVELS.get(mid)
    if concern_level == "critical":
        cpu = 95.0
    elif concern_level == "warning":
        cpu = 80.0
    mem_frac = {"server": 0.62, "macbook": 0.55, "studio": 0.31, "nas": 0.42}[template] + 0.05 * day + 0.04 * wave
    if mid == "server" and t > T0 - 25 * 60:
        mem_frac = 0.88 + 0.02 * h
    if concern_level == "critical":
        mem_frac = 0.95
    rx = max(0.0, {"server": 2.4e6, "macbook": 4.5e5, "studio": 1.2e6, "nas": 3e5}[template] * (1 + 0.6 * wave + 0.5 * h))
    tx = rx * {"server": 0.35, "macbook": 0.2, "studio": 0.6, "nas": 1.4}[template] * (0.7 + 0.6 * h)
    load = sys_["cores"] * cpu / 100 * (0.9 + 0.3 * h)
    disk_frac = {"server": 0.64, "macbook": 0.71, "studio": 0.38, "nas": 0.93}[template]
    if concern_level == "critical":
        disk_frac = 0.95
    return {"cpu": round(cpu, 1), "load": round(load, 2), "mem": round(mem_frac * sys_["memory"]),
            "swap": round({"server": 0.0, "macbook": 1.2, "studio": 0.0, "nas": 0.4}[template] * GB),
            "rx": round(rx, 1), "tx": round(tx, 1), "disk": round(disk_frac * {"nas": 4000, "studio": 2000}.get(mid, 1000) * GB)}


def metric_series(mid, span, step):
    """Like the hub: one point a step from span ago, a gap marker where the machine sent nothing for > 3 steps."""
    out, missing = [], 0
    now = int(time.time())  # live, like the hub: the charts end at now
    start = (now - span) // step * step
    for t in range(start, now + 1, step):
        if not metrics_present(mid, t):
            missing += 1
            if missing * step > 3 * step and (not out or not out[-1].get("gap")):
                out.append({"t": t - (missing - 1) * step, "gap": True})
            continue
        missing = 0
        out.append({"t": t, **metric_at(mid, t)})
    return out


def metric_latest(mid):
    now = int(time.time()) // 10 * 10
    if not metrics_present(mid, now):
        return None
    v, sys_ = metric_at(mid, now), SYSTEMS[mid]
    out = {"t": now, "cpu": v["cpu"], "load": v["load"], "mem_used": v["mem"], "mem_total": sys_["memory"],
           "swap_used": v["swap"], "swap_total": 4 * GB if v["swap"] else 0, "net_rx": v["rx"], "net_tx": v["tx"],
           "disk_used": v["disk"], "disk_total": {"nas": 4000, "studio": 2000}.get(mid, 1000) * GB}
    if mid == "server":
        out["cores"] = [round(min(100, max(1, v["cpu"] + 9 * ((i * 37) % 7 - 3))), 1) for i in range(sys_["cores"])]
    return out


def machine_metrics(mid, span, step):
    m = next(x for x in MACHINES if x["id"] == mid)
    return {"machine_id": mid, "online": m["online"], "system": m.get("system"), "latest": metric_latest(mid),
            "points": metric_series(mid, span, step)}


# Token usage by machine (docs/server/machines.md "Token usage", #4973). MOCK_TOKENS=none: a hub before it (the usage route
# answers 404, the cards have no tokens); =empty: no machine ran anything; =lopsided: the server ran nearly all of it
# (the Machines page's share bar with minimum-width parts). The studio's node is an older one (its usage
# names no launcher), the NAS is offline (its monitoring stops 3 hours ago, and so does its usage).
MOCK_TOKENS = os.environ.get("MOCK_TOKENS", "")
USAGE_MIX = {  # machine: [(model, launcher, share)]
    "server": [("claude-opus-5-5", "claude", 0.62), ("gpt-5.5", "codex", 0.3), ("claude-haiku-5-5", "claude", 0.08)],
    "macbook": [("claude-opus-5-5", "claude", 0.7), ("claude-sonnet-5-5", "sonnetcc", 0.3)],
    "studio": [("claude-opus-5-5", "", 1.0)],
    "nas": [("claude-haiku-5-5", "claude", 1.0)],
}
USAGE_SCALE = {"server": 1.0, "macbook": 0.55, "studio": 0.25, "nas": 0.05}


def usage_minute(mid, minute):
    """A made-up minute of a machine's usage, one bucket per model and launcher: quiet nights, busy afternoons."""
    import math
    if MOCK_TOKENS == "empty" or mid not in USAGE_MIX or not metrics_present(mid, minute):
        return []
    hour = (minute % 86400) / 3600  # UTC; the shape only has to look like a day
    work = max(0.02, math.sin(math.pi * (hour - 1) / 14)) if 1 <= hour <= 15 else 0.03
    h = int(hashlib.md5(f"u{mid}{minute}".encode()).hexdigest()[:6], 16) / 0xFFFFFF
    if h < 0.25 and work < 0.2:
        return []
    scale = USAGE_SCALE[mid] * (0.001 if MOCK_TOKENS == "lopsided" and mid != "server" else 1)
    w = work * (0.5 + h) * scale * (1.6 if mid == "server" and minute > T0 - 25 * 60 else 1)
    out = []
    for model, launcher, share in USAGE_MIX[mid]:
        f = w * share
        cr, cw = int(310000 * f), int(21000 * f * (0.4 + h))
        inp, o = int(2600 * f * (0.5 + h)), int(5400 * f * (0.6 + h))
        if "gpt" in model:
            cr, cw = int(cr * 0.8), 0  # Codex has no cache write
        if cr + cw + inp + o:
            out.append({"minute": minute, "model": model, "launcher": launcher, "in": inp, "cache_write": cw,
                        "cache_read": cr, "out": o, "req": max(1, int(f * 6))})
    return out


def usage_sum(rows):
    t = {"in": 0, "cache_write": 0, "cache_read": 0, "out": 0, "req": 0}
    for r in rows:
        for k in t:
            t[k] += r[k]
    return t


def machine_usage(mid, rng, model=None, launcher=None):
    """GET /api/v1/machines/{id}/usage, like the manager: the range's steps, the filters, the shares, the breaks."""
    span, step = {"1h": (3600, 60), "24h": (86400, 600), "7d": (7 * 86400, 3600)}[rng]
    now = int(time.time())
    first = (now - span) // step * step + step
    rows = []
    for minute in range(first, now // 60 * 60 + 1, 60):
        rows.extend(usage_minute(mid, minute))
    keep = lambda r, by_model=True, by_launcher=True: (not by_model or model is None or r["model"] == model) and (
        not by_launcher or launcher is None or r["launcher"] == launcher)
    points = []
    for t in range(first, now // step * step + 1, step):
        mine = [r for r in rows if t <= r["minute"] < t + step and keep(r)]
        p = {"t": t, **usage_sum(mine)}
        if not mine and not metrics_present(mid, t + step - 60):
            p["gap"] = True
        points.append(p)

    def shares(by):
        names = {}
        for r in rows:
            if keep(r, by_model=by != "model", by_launcher=by != "launcher"):
                names.setdefault(r[by], []).append(r)
        out = [{"name": n, **usage_sum(v)} for n, v in names.items()]
        return sorted(out, key=lambda x: -(x["in"] + x["cache_write"] + x["cache_read"] + x["out"]))
    m = next(x for x in MACHINES if x["id"] == mid)
    return {"machine_id": mid, "online": m["online"], "range": rng, "step": step, "points": points,
            "total": usage_sum([r for r in rows if keep(r)]), "models": shares("model"), "launchers": shares("launcher"),
            "launchers_known": mid != "studio", "stored": True}


def usage_card(mid):
    """A machine's tokens on its card (GET /api/v1/metrics's usage): today, per minute now, the last hour by minute."""
    if MOCK_TOKENS == "none" or mid not in USAGE_MIX:
        return None
    now = int(time.time())
    minute = now // 60 * 60
    today = [r for t in range(now // 86400 * 86400, minute + 1, 60) for r in usage_minute(mid, t)]
    tot = lambda rows: sum(r["in"] + r["cache_write"] + r["cache_read"] + r["out"] for r in rows)
    recent = [tot(usage_minute(mid, minute - 60 * (59 - i))) for i in range(60)]
    now_rows = [r for t in (minute - 120, minute - 60, minute) for r in usage_minute(mid, t)]
    return {"today": usage_sum(today), "per_minute": int(tot(now_rows) / ((now - (minute - 120)) / 60)), "recent": recent}


def sess(mid, sid, title, cwd, status, state, space, sidx, slot, slidx, minutes, last, agent="claude", pending=0, **kw):
    s = {"machine_id": mid, "session_id": sid, "title": title, "cwd": cwd, "status": status, "state": state,
         "agent": agent, "launcher": "claude", "model": "opus" if agent == "claude" else "gpt-5.5", "started_by_persona": True,
         "assistant": False, "space_kind": "herdr", "space_id": f"w{sidx}", "space_name": space, "space_index": sidx,
         "slot_id": f"w{sidx}:t{slidx}", "slot_name": slot, "slot_index": slidx, "pane_id": f"w{sidx}:p{slidx}",
         "tab_id": f"w{sidx}:t{slidx}", "workspace_id": f"w{sidx}", "updated_at": ago(minutes=minutes),
         "last_text": last, "pending_interactions": pending, "rev": 1000}
    if agent == "claude":
        s.update(permission_mode="default", effort="high", can_fork=True)  # "Fork to new chat" (#2137)
    s.update(kw)
    return s


