def save_task(old, new):
    """What the hub keeps of an edit: the editable fields ("" = default), a session that can only be cleared, the next run."""
    t = {**old, **{k: v for k, v in new.items() if k in TASK_FIELDS}}
    for k in ("launcher", "permission_mode", "effort"):
        if not t.get(k): t.pop(k, None)
    if not new.get("session_id"): t.pop("session_id", None)
    # "Notify after a run" (#2396): left out of an edit it stays; "asked" runs in the task's own conversation; "" is the default.
    if t.get("push") == "asked": t.pop("session_id", None)
    if not t.get("push"): t.pop("push", None)
    if not t.get("inbox"): t.pop("inbox", None)
    # End time: left out it stays, null clears it, and a one-off never has one (the hub's until).
    if t.get("repeat") == "once" or ("until" in new and not new.get("until")):
        t.pop("until", None)
    elif "until" in new:
        t["until"] = new["until"]
    if t.get("repeat") == "daily":
        t["next_run"] = next_at(t.get("time", "09:00"), t.get("weekdays") or [])
    elif t.get("repeat") == "cron":
        t.pop("at", None)
        t["next_run"] = cron_runs(t["cron"])[0] if t.get("cron") in CRON_PREVIEWS else None
    elif t.get("repeat") == "interval":
        if old.get("every_minutes") != t.get("every_minutes") or not t.get("at"):
            t["at"] = later(minutes=t.get("every_minutes") or 30)
        t["next_run"] = t["at"]
    else:
        t["next_run"] = t.get("at")
    if not t.get("enabled"): t.pop("next_run", None)
    return t


def run(rid, kind, ref, title, due, status, at=None, **more):
    return {"id": rid, "kind": kind, "ref_id": ref, "title": title, "due": due, "at": at or due, "status": status, **more}


