RETRY_TASK_STARTED = "a1f3c2d4-0000-4000-8000-0000000000a1"
RETRY_MODE = {"mode": os.environ.get("MOCK_RETRY", "")}
BRIEF_ACCEPTED = set()  # the tasks verified from a brief item's Accept button (reset with the mock hub)
BRIEF_HANDLED = set()  # the questions that can wait marked handled from a brief item (reset with the mock hub)


def retry_task(h, tid):
    """POST /api/v1/todos/{id}/retry (#1396): a task that did not start reopens at once without its error (its plan's
    too), and its agent comes up a moment later in a new session, working. MOCK_RETRY=fail: that start fails again with
    a new error; =offline: refused, the machine offline (or GET /mock/retry?mode=…, which also puts the failed task back
    as it was: scripts/test/web_task_retry_e2e.py). A task already started again answers as it is."""
    t = next((x for x in TODOS if x["id"] == tid), None)
    if not t:
        return h.send_json({"error": "todo not found"}, 404)
    mode = RETRY_MODE["mode"]
    cut = [x for x in SESSIONS if x.get("turn_error") and any(a["session_id"] == x["session_id"] for a in t.get("agents", []))]
    if cut and not t.get("done_at"):
        # "Continue" on a task the model service cut off (#1516): its agent works, and a moment later finishes.
        s0 = cut[0]
        s0.pop("turn_error", None)
        s0.update(status="working", state="working", last_text="接着整理发布说明。", updated_at=ago())
        push_machine(s0["machine_id"])

        def finished():
            time.sleep(2)
            s0.update(status="done", state="unread", updated_at=ago(),
                      last_text="整理好了：这周合并了 7 个 PR，写在 docs/release-notes.md 里。")
            push_machine(s0["machine_id"])

        threading.Thread(target=finished, daemon=True).start()
        return h.send_json({"todo": format_todo(t)})
    if not t.get("start_error"):
        if t.get("done_at") or not t.get("plan_id"):
            return h.send_json({"error": "只有助手派出、没开起来的任务能重试"}, 409)
        return h.send_json({"todo": format_todo(t)})
    if mode == "offline":
        return h.send_json({"error": "「MacBook」现在离线，等它连上再重试"}, 409)
    plan = TASK_PLANS.get(t.get("plan_id"))

    def plan_error(err):
        if not plan:
            return
        for pt in plan["tasks"]:
            if pt.get("todo_id") == tid:
                pt["error"] = err
        for send, _ in list(LIVE):
            try: send(from_default({"type": "task_plan", "plan": plan}))
            except Exception: pass

    t.update(done_at=None, start_error="", reopened_at=ago(), updated_at=ago())
    plan_error("")
    push_todos()

    def started():
        time.sleep(1.5)
        if mode == "fail":
            err = "claude did not start within 3m0s: the tab's shell had not run it yet (is the machine busy?)"
            t.update(done_at=ago(), start_error=err, updated_at=ago())
            plan_error(err)
        else:
            if not any(x["session_id"] == RETRY_TASK_STARTED for x in SESSIONS):
                SESSIONS.append(sess("macbook", RETRY_TASK_STARTED, t["title"], "/Users/me/code/weather", "working", "working",
                                     "weather", 1, "align", 9, 0, "在看设置页底部两个按钮的布局约束。"))
            t["agents"] = [{"machine_id": "macbook", "session_id": RETRY_TASK_STARTED, "linked_at": ago(), "released_at": None,
                            "title": t["title"], "cwd": "/Users/me/code/weather", "agent": "claude", "start_error": "",
                            "source": "manual", "via": ""}]
            push_machine("macbook")
        push_todos()

    threading.Thread(target=started, daemon=True).start()
    h.send_json({"todo": format_todo(t)})


def tasks_area(h, method, p, raw):
    """The unified entry's endpoints (MOCK_TASKS=1): the feed, starting / dismissing a plan, routing to a task."""
    if not MOCK_TASKS:
        return False
    if method == "GET" and p.startswith("/api/v1/assistant/conversations/") and p.endswith("/feed"):
        conv = p.split("/")[5]
        items = TASK_FEED.get(conv, [])
        plans = {i["ref"]: suggested_plan(TASK_PLANS[i["ref"]]) for i in items if i["kind"] == "plan" and i["ref"] in TASK_PLANS}
        h.send_json({"items": items, "plans": plans})
        return True
    if method == "POST" and p.startswith("/api/v1/assistant/conversations/") and p.endswith("/today"):
        conv = p.split("/")[5]
        item = next((i for i in TASK_FEED.get(conv, []) if i["kind"] == "today"), None)
        h.send_json({"item": item, "new": False} if item else {"error": "no today in the mock"}, 200 if item else 503)
        return True
    if p == "/api/v1/task-trust":
        if method == "DELETE":
            key = parse_qs(urlparse(h.path).query).get("key", [""])[0]
            TASK_TRUST[:] = [k for k in TASK_TRUST if k["key"] != key]
            h.send_json({"ok": True})
        else:
            h.send_json({"kinds": TASK_TRUST})
        return True
    if method == "GET" and p.startswith("/api/v1/task-plans/"):
        plan = TASK_PLANS.get(p.split("/")[4])
        h.send_json({"plan": suggested_plan(plan)} if plan else {"error": "plan not found"}, 200 if plan else 404)
        return True
    if method == "POST" and p.startswith("/api/v1/task-plans/") and p.endswith(("/start", "/dismiss")):
        pid = p.split("/")[4]
        plan = TASK_PLANS.get(pid)
        if not plan:
            h.send_json({"error": "plan not found"}, 404)
            return True
        if plan["state"] != "open":
            h.send_json({"error": "this plan was already started or dismissed"}, 409)
            return True
        plan["state"] = "dismissed" if p.endswith("/dismiss") else "started"
        h.send_json({"plan": plan})
        return True
    if method == "POST" and p.startswith("/api/v1/todos/") and p.endswith("/accept"):
        # Accept only the current round; a Brief's older row is already handled, while an ordinary card uses its current ask.
        tid = p.split("/")[4]
        sent = json.loads(h.last_body or b"{}")
        brief = next((row for feeds in TASK_FEED.values() for item in feeds if item.get("kind") == "brief"
                      for row in item.get("body", {}).get("accept", []) if row.get("id") == tid), None)
        current = next((t for t in sorted_todos() if t["id"] == tid), None)
        current_ask = (current or {}).get("ask")
        # With asks shown the hub accepts only the current round; MOCK_TASKS_NO_ASKS hides that state for visual tests.
        expected = current_ask.get("asked_at") if current_ask is not None else (brief or {}).get("asked_at")
        if tid in BRIEF_ACCEPTED or expected is None or sent.get("asked_at") != expected:
            h.send_json({"error": "已经处理过了"}, 409)
        elif MOCK_DECISIONS and sent.get("response") == "explain_first" and tid in TODO_ASKS:
            DECISION_KEPT[tid] = "explain_first"  # the round stays open, no longer taken by default (decision.go)
            h.send_json({"ok": True})
            push_todos()
        else:
            BRIEF_ACCEPTED.add(tid)
            h.send_json({"ok": True})
            if tid in TODO_ASKS:
                push_todos()  # its ask is gone (MOCK_TODO_ASKS), as the hub's askChanged says
        return True
    if method == "POST" and p.startswith("/api/v1/later/") and p.endswith("/handled"):
        # The Handled button of a question that can wait: the first press takes it out of the queue, a second one is 409.
        qid = p.split("/")[4]
        if qid in BRIEF_HANDLED:
            h.send_json({"error": "已经处理过了"}, 409)
        else:
            BRIEF_HANDLED.add(qid)
            h.send_json({"ok": True})
        return True
    if method == "POST" and p.startswith("/api/v1/todos/") and p.endswith("/retry"):
        retry_task(h, p.split("/")[4])
        return True
    if method == "POST" and p.startswith("/api/v1/todos/") and p.endswith(("/decision-dismiss", "/decision-undo-dismiss")):
        decision_dismissal_route(h, p.split("/")[4], p.endswith("/decision-undo-dismiss"))
        return True
    if p == "/mock/cut" and os.environ.get("MOCK_TASKS_CUT") == "1":
        SESSIONS[:] = [copy.deepcopy(CUT_SESSION) if x["session_id"] == RELEASE else x for x in SESSIONS]
        push_machine("macbook")
        h.send_json({"ok": True})
        return True
    if p == "/mock/retry":
        RETRY_MODE["mode"] = parse_qs(urlparse(h.path).query).get("mode", [""])[0]
        base = next(x for x in TODOS_INIT if x["id"] == "todo_task_align")
        TODOS[:] = [copy.deepcopy(base) if x["id"] == base["id"] else x for x in TODOS]
        for pt in TASK_PLANS["plan_mock_4"]["tasks"]:
            pt["error"] = base["start_error"]
        SESSIONS[:] = [x for x in SESSIONS if x["session_id"] != RETRY_TASK_STARTED]
        push_todos()
        h.send_json({"ok": True, "mode": RETRY_MODE["mode"]})
        return True
    if method == "POST" and p.startswith("/api/v1/assistant/conversations/") and p.endswith("/route"):
        body = json.loads(raw or b"{}")
        conv = p.split("/")[5]
        item = {"id": "feed_r%d" % len(TASK_FEED.get(conv, [])), "conversation": conv, "at": ago(), "kind": "routed",
                "ref": body.get("todo_id"), "body": {"text": body.get("text", "")}}
        TASK_FEED.setdefault(conv, []).append(item)
        h.send_json({"item": item})
        return True
    return False


# MOCK_MAIN_ACTIONS=1: the hub can compact the main conversation and start a new one (#1727, the apps' side #1762):
# the features assistant_compact / assistant_main_new; POST …/compact runs for MOCK_COMPACT_SECONDS (default 3) and
# ends done (MOCK_COMPACT_FAIL=1: failed); POST /api/v1/assistant/main/new archives the main one (409 main_changed when
# `expect` is not it); POST /api/v1/assistant/main/clear (assistant_main_clear, #5095) does the same with nothing carried
# and a turn it is on stopped. MOCK_COMPACTION=running|done|failed: the main conversation starts in that state (screenshots).
MAIN_ACTIONS = os.environ.get("MOCK_MAIN_ACTIONS") == "1"


def utc_now():
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def set_compaction(sid, state, error=""):
    for s in ASSISTANT:
        if s["session_id"] != sid:
            continue
        c = {"state": state, "started_at": (s.get("compaction") or {}).get("started_at") if state != "running" else utc_now()}
        if state != "running":
            c["finished_at"] = utc_now()
        if error:
            c["error"] = error
        s["compaction"] = c
        push_machine(s["machine_id"])


def main_actions_area(h, method, p, raw):
    if not MAIN_ACTIONS or method != "POST":
        return False
    if p.startswith("/api/v1/assistant/conversations/") and p.endswith("/compact"):
        sid = p.split("/")[5]
        s = next((x for x in ASSISTANT if x["session_id"] == sid), None)
        if s is None:
            h.send_json({"code": "gone", "error": "这段对话的记录不在了"}, 409)
            return True
        if (s.get("compaction") or {}).get("state") == "running":
            h.send_json({"code": "compacting", "error": "已经在压缩了"}, 409)
            return True
        set_compaction(sid, "running")
        fail = os.environ.get("MOCK_COMPACT_FAIL") == "1"
        threading.Timer(float(os.environ.get("MOCK_COMPACT_SECONDS", "3")), lambda: set_compaction(
            sid, "failed" if fail else "done", "Claude Code 没有写下压缩的结果" if fail else "")).start()
        h.send_json({"ok": True})
        return True
    if p == "/api/v1/assistant/main/new":
        body = json.loads(raw or b"{}")
        old = ASSISTANT_CONFIG["main"]
        if not old or body.get("expect") != old:
            h.send_json({"code": "main_changed", "error": "主对话已经在别的设备上换过了"}, 409)
            return True
        today = datetime.now()
        for s in ASSISTANT:
            if s["session_id"] == old:
                s.update(title="旧主对话 · 至 %d月%d日" % (today.month, today.day), archived=True)
                push_machine(s["machine_id"])
        ASSISTANT_CONFIG["main"] = None
        h.send_json({"ok": True, "archived": old, "carried": body.get("carry") == "summary"})
        return True
    if p == "/api/v1/assistant/main/clear":
        body = json.loads(raw or b"{}")
        old = ASSISTANT_CONFIG["main"]
        if body.get("expect") and body.get("expect") != old:
            h.send_json({"code": "main_changed", "error": "主对话已经在别的设备上换过了"}, 409)
            return True
        today = datetime.now()
        for s in ASSISTANT:
            if old and s["session_id"] == old:
                s.update(title="旧主对话 · 至 %d月%d日" % (today.month, today.day), archived=True, status="idle", state="idle")
                push_machine(s["machine_id"])
        ASSISTANT_CONFIG["main"] = None
        h.send_json({"ok": True, "archived": old or ""})
        return True
    return False


if MAIN_ACTIONS and os.environ.get("MOCK_COMPACTION") in ("running", "done", "failed"):
    _state = os.environ["MOCK_COMPACTION"]
    _c = {"state": _state, "started_at": utc_now()}
    if _state != "running":
        _c["finished_at"] = (datetime.now(timezone.utc) + timedelta(minutes=5)).isoformat().replace("+00:00", "Z")  # still recent once the app is up
    if _state == "failed":
        _c["error"] = "Claude Code 没有写下压缩的结果"
    next(x for x in ASSISTANT if x["session_id"] == ASK1)["compaction"] = _c


