# Another manager's own mutes (each manager keeps its own, docs/assistant/managers.md "Clients"), by its id; the default's are MUTES.
OTHER_MUTES = {}


def mute_item(item_id, tag, manager=None):
    """POST /api/v1/inbox/mutes: mute what the item has under tag; its source's open items that match are done. With
    `manager` (another than the default), into that manager's mutes, and only its items are done."""
    mutes = OTHER_MUTES.setdefault(manager, []) if manager else MUTES
    it = next((x for x in INBOX if x["id"] == item_id), None)
    opt = next((m for m in (it or {}).get("mutes") or [] if m["tag"] == tag), None)
    if not opt: return None, 0
    src = it["source"]
    mute = next((m for m in mutes if m["source"] == src and m["tag"] == tag and m["value"] == opt["value"]), None)
    if not mute:
        mute = {"id": "m%d" % (len(mutes) + 100), "source": src, "source_name": SOURCE_NAMES.get(src, src), "tag": tag,
                "value": opt["value"], "name": opt["name"], "created_at": ago(minutes=0)}
        mutes.append(mute)
    settled = 0
    owner = manager or MANAGERS["default"]
    for x in INBOX:
        if _stamps() and inbox_owner(x["id"]) != owner: continue
        if x["source"] == src and not x.get("done_at") and any(m["tag"] == tag and m["value"] == opt["value"] for m in x.get("mutes") or []):
            x["done_at"], x["done_by"], x["reason"] = ago(minutes=0), "read", "已静音：" + opt["name"]
            settled += 1
    return mute, settled


# The policies the user set (GET/POST/PATCH/DELETE /api/v1/inbox/policies, docs/assistant/inbox.md "Policies"); MOCK_POLICIES=1 starts with two.
POLICIES = [] if not os.environ.get("MOCK_POLICIES") else [
    {"id": "p1", "source": "lark", "source_name": "飞书", "tag": "chat", "value": "f-weekend", "name": "周末徒步群", "tier": "noise", "created_at": ago(days=2), "updated_at": ago(days=2)},
    {"id": "p2", "source": "mail", "source_name": "邮件", "tag": "sender", "value": "boss@example.com", "name": "王经理", "tier": "action", "twin": "first", "created_at": ago(hours=5), "updated_at": ago(hours=5)},
]


# Another manager's own policies (each manager keeps its own), by its id; the default's are POLICIES.
OTHER_POLICIES = {}


def set_policy(body, pid=None, manager=None):
    """POST (from an item) / PATCH (by id) a policy: one per target; neither part removes it; covered open items take its tier.
    With `manager` (another than the default), that manager's policies and items."""
    pols = OTHER_POLICIES.setdefault(manager, []) if manager else POLICIES
    owner = manager or MANAGERS["default"]
    tier, twin = body.get("tier") or "", body.get("twin") or ""
    if tier not in ("", "action", "fyi", "noise") or twin not in ("", "first", "never"): return None, 0
    if pid:
        pol = next((x for x in pols if x["id"] == pid), None)
        if not pol: return None, 0
    else:
        it = next((x for x in INBOX if x["id"] == body.get("item_id")), None)
        opt = next((m for m in (it or {}).get("mutes") or [] if m["tag"] == body.get("tag")), None)
        if not opt: return None, 0
        src = it["source"]
        pol = next((x for x in pols if x["source"] == src and x["tag"] == opt["tag"] and x["value"] == opt["value"]), None)
        if not pol:
            pol = {"id": "p%d" % (len(pols) + 100), "source": src, "source_name": SOURCE_NAMES.get(src, src), "tag": opt["tag"],
                   "value": opt["value"], "name": opt["name"], "created_at": ago(minutes=0)}
            pols.append(pol)
    pol.update({"tier": tier, "twin": twin, "updated_at": ago(minutes=0)})
    if not tier and not twin: pols[:] = [x for x in pols if x["id"] != pol["id"]]
    applied = 0
    for x in INBOX if tier else []:
        if _stamps() and inbox_owner(x["id"]) != owner: continue
        if x["source"] == pol["source"] and not x.get("done_at") and x.get("tier") and x.get("tier") != tier and \
                any(m["tag"] == pol["tag"] and m["value"] == pol["value"] for m in x.get("mutes") or []):
            x["tier"], x["reason"] = tier, "按你的规则：" + pol["name"]
            if x.get("status") in ("action", "fyi", "noise"): x["status"] = tier
            applied += 1
    return pol, applied


def inbox_version(x):
    """What the item holds now (the hub's inboxVersion): it moves when something new comes in."""
    return hashlib.sha256((x["id"] + "\0" + str(x.get("updated_at")) + str(x.get("count"))).encode()).hexdigest()[:16]


# Done items older than the list's days, for GET /api/v1/inbox/done (#2200, the inbox's Done by time #2059): made-up
# Lark chats, mail and GitHub notifications done 4 to 60 days ago, a few a day. MOCK_INBOX_HISTORY=none: a hub without
# the history (404), as before #2200; =busy: 36 a day from 3 to 60 days ago, as a busy inbox has (Done's day counts, #2969).
def _history():
    out = []
    kinds = [("lark", "dm", "飞书", "示例同事", "周报我交啦"), ("mail", "mail", "个人邮箱", "示例商城", "订单已签收"),
             ("lark", "group", "飞书", "项目群", "版本号改好了"), ("github", "review_requested", "GitHub", "Alex", "依赖升级已合并")]
    busy = os.environ.get("MOCK_INBOX_HISTORY") == "busy"
    for day in range(3, 61) if busy else list(range(4, 8)) + [9, 12, 16, 21, 27, 33, 41, 52, 60]:
        for i in range(36 if busy else 2 if day > 8 else 3):
            src, kind, name, sender, preview = kinds[(day + i) % len(kinds)]
            x = {"id": f"hist:{day}:{i}", "source": src, "kind": kind, "account": "acc1" if src == "mail" else src, "account_name": name,
                 "title": f"{sender} · {preview}", "sender": sender, "preview": preview, "count": 1, "started_at": ago(days=day, hours=3 + i % 20),
                 "updated_at": ago(days=day, hours=2 + i % 20), "tier": "fyi", "summary": preview, "done_at": ago(days=day, hours=1 + i % 20, minutes=i), "done_by": "user"}
            if src == "github":
                x["connector"] = {"thread": f"example-org/example-repo#{day}", "label": "PR", "url": "https://example.com/pr", "can_reply": False}
            out.append(x)
    return out


INBOX_HISTORY = [] if os.environ.get("MOCK_INBOX_HISTORY") == "none" else _history()


# MOCK_INBOX_HISTORY=busy also has the list's own done items of its last days, as a busy hub lists them (the list holds
# the done items of 3 days): 2 within the hour (Done's "Just now"), 5 earlier today, 6 yesterday, 4 the day before.
if os.environ.get("MOCK_INBOX_HISTORY") == "busy":
    for (_day, _n, _h0) in ((0, 2, 0), (0, 5, 2), (1, 6, 1), (2, 4, 1)):
        for _i in range(_n):
            _x = dict(INBOX_HISTORY[_i % 4], id=f"recent:{_day}:{_h0}:{_i}")
            _done = ago(days=_day, hours=_h0 + (_i % 6 if _h0 else 0), minutes=10 + _i)
            _x.update(done_at=_done, updated_at=_done, started_at=_done)
            INBOX.append(_x)


def _instant(s):
    """An RFC 3339 time as an instant: the apps send their own forms ("…Z", "….000Z", "+08:00"), so never compare text."""
    return datetime.fromisoformat(s.replace("Z", "+00:00"))


def _done_items(all_sources):
    return [x for x in INBOX + INBOX_HISTORY if x.get("done_at") and (all_sources or "connector" not in x)]


def inbox_done(query):
    """GET /api/v1/inbox/done: done items newest first, keyset-paged on (done_at, id), the list's and the history's.
    A before without before_id is a moment: the items done before it (a jump to a day, #2967)."""
    all_sources = (query.get("sources") or [""])[0] == "all"
    before, before_id = (query.get("before") or [""])[0], (query.get("before_id") or [""])[0]
    limit = max(1, min(200, int((query.get("limit") or ["50"])[0] or 50)))
    done = _done_items(all_sources)
    done.sort(key=lambda x: (_instant(x["done_at"]), x["id"]), reverse=True)
    if before:
        done = [x for x in done if (_instant(x["done_at"]), x["id"]) < (_instant(before), before_id)]
    page = done[:limit]
    body = {"items": [{k: v for k, v in x.items() if k != "context"} for x in page]}
    if len(page) == limit and len(done) > limit:
        body["next"] = {"before": page[-1]["done_at"], "before_id": page[-1]["id"]}
    return body


def inbox_done_days(query):
    """GET /api/v1/inbox/done/days?tz=: the done items per calendar day in tz, newest day first (#2967); None: a bad zone."""
    from zoneinfo import ZoneInfo
    tz = (query.get("tz") or [""])[0]
    try:
        zone = ZoneInfo(tz) if tz and tz != "Local" else None
    except Exception:
        zone = None
    if zone is None:
        return None
    counts = {}
    for x in _done_items((query.get("sources") or [""])[0] == "all"):
        day = _instant(x["done_at"]).astimezone(zone).strftime("%Y-%m-%d")
        counts[day] = counts.get(day, 0) + 1
    return {"tz": tz, "days": [{"day": d, "count": counts[d]} for d in sorted(counts, reverse=True)]}


def inbox_for(query):
    """The list as the hub gives it: connectors' items only with ?sources=all."""
    if MOCK_INBOX_SHOWCASE:
        return copy.deepcopy(INBOX)
    all_sources = (query.get("sources") or [""])[0] == "all"
    return [dict({k: v for k, v in x.items() if k != "context"}, version=inbox_version(x)) for x in INBOX if all_sources or "connector" not in x]


# New items waiting for triage (GET /api/v1/inbox `triage`, #1773; the hub's inbox_admit.go). Unset: no `triage` at all,
# as from a hub older than #1644. MOCK_INBOX_TRIAGE=<state>[:<waiting>[:<source name>[:<reason>]]]:
#   unconfigured                  3 Feishu items wait, no model set up (the apps offer "Configure")
#   behind:12:Lark,Mail            12 wait from two sources (6 each): the banner names none
#   error:2:GitHub:Model quota exhausted     the hub's own reason instead of the state's words
#   ok                            triage is fine: {"state": "ok", "waiting": 0}
# States: ok | unconfigured | paused | error | timeout | behind. Several names, comma-separated, share the waiting.
def inbox_triage_from(spec):
    """The triage block MOCK_INBOX_TRIAGE asks for; None when it is not set."""
    if not spec:
        return None
    parts = spec.split(":", 3)
    state = parts[0].strip() or "ok"
    if state == "ok":
        return {"state": "ok", "waiting": 0}
    waiting = int(parts[1]) if len(parts) > 1 and parts[1].strip() else 3
    names = [n.strip() for n in (parts[2] if len(parts) > 2 else "飞书").split(",") if n.strip()] or ["飞书"]
    reason = parts[3].strip() if len(parts) > 3 else ""
    ids = {"飞书": "lark", "邮件": "mail", "GitHub": "github", "Telegram": "telegram"}
    sources = []
    for i, name in enumerate(names):
        share = waiting // len(names) + (1 if i < waiting % len(names) else 0)
        src = {"source": ids.get(name, "source%d" % (i + 1)), "name": name, "state": state, "waiting": share}
        if reason:
            src["reason"] = reason
        sources.append(src)
    out = {"state": state, "waiting": waiting, "sources": sorted(sources, key=lambda x: x["source"])}
    if reason:
        out["reason"] = reason
    return out


INBOX_TRIAGE = inbox_triage_from(os.environ.get("MOCK_INBOX_TRIAGE", ""))


# Sources the hub could not read this round (triage.sources[].read_error / read_reason, #1849; the hub's inbox_admit.go).
# MOCK_INBOX_UNREAD=<name>[:<code>[:<reason>]],… : each name is marked not read (code timeout | rate_limited | failed,
# default timeout); with no reason the source has no read_reason (the apps' own words). Adds `triage` (ok) if unset.
def inbox_unread_into(triage, spec):
    """The triage block with MOCK_INBOX_UNREAD's sources marked not read; triage as it was when spec is empty."""
    if not spec:
        return triage
    out = copy.deepcopy(triage) if triage is not None else {"state": "ok", "waiting": 0}
    sources = out.setdefault("sources", [])
    for i, entry in enumerate(x for x in spec.split(",") if x.strip()):
        parts = entry.split(":", 2)
        name = parts[0].strip()
        code = parts[1].strip() if len(parts) > 1 and parts[1].strip() else "timeout"
        src = next((x for x in sources if x.get("name") == name), None)
        if src is None:
            src = {"source": "unread%d" % (i + 1), "name": name, "state": "ok", "waiting": 0}
            sources.append(src)
        src["read_error"] = code
        if len(parts) > 2 and parts[2].strip():
            src["read_reason"] = parts[2].strip()
    sources.sort(key=lambda x: x["source"])
    return out


INBOX_TRIAGE = inbox_unread_into(INBOX_TRIAGE, os.environ.get("MOCK_INBOX_UNREAD", ""))


def inbox_list(query):
    """GET /api/v1/inbox (and POST …/refresh): the items, with `triage` when MOCK_INBOX_TRIAGE is set."""
    body = {"items": inbox_for(query), "as_of": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")}
    if INBOX_TRIAGE is not None:
        body["triage"] = INBOX_TRIAGE
    return body


# What each bulk "Handled" / "Undo" asked for (POST /api/v1/inbox/done), kept at /mock/inbox_bulk.
INBOX_BULK = []


def inbox_bulk(body):
    """POST /api/v1/inbox/done and /bulk: files (or brings back) the items named, as the hub does: an item already in
    that state is unchanged, one whose version moved since the list is skipped. /bulk's `action` dismiss files as
    done_by=dismissed; its `filter` takes every open item (the mock has no arrivals: as_of is not compared)."""
    INBOX_BULK.append(body)
    action = body.get("action") or ("done" if body.get("done") else "reopen")
    done, out = action != "reopen", {"changed": [], "unchanged": [], "skipped": []}
    targets = list(body.get("items") or []) + [{"id": i} for i in body.get("ids") or []]
    if body.get("filter") is not None:
        targets = [{"id": x["id"]} for x in INBOX if not x.get("done_at")]
    seen = set()
    for t in targets:
        if t.get("id") in seen: continue
        seen.add(t.get("id"))
        x = next((x for x in INBOX if x["id"] == t.get("id")), None)
        if x is None:
            out["skipped"].append({"id": t.get("id"), "reason": "missing"})
        elif bool(x.get("done_at")) == done:
            out["unchanged"].append(x["id"])
        elif done and t.get("version") and t["version"] != inbox_version(x):
            out["skipped"].append({"id": x["id"], "reason": "changed"})
        else:
            if done:
                x["done_at"], x["done_by"] = ago(minutes=0), "dismissed" if action == "dismiss" else "user"
            else:
                x.pop("done_at", None), x.pop("done_by", None)
            out["changed"].append(dict({k: v for k, v in x.items() if k != "context"}, version=inbox_version(x)))
    return out


