# Merge and Add to to-dos (#6480): POST /api/v1/inbox/merge, /merge/undo, /todo, /todo/undo as the hub answers them. A merge takes the
# newest row as the survivor and hides the others (kept in MERGED for Undo); a to-do files its row as done_by=todo with a todo link.
# What each asked for is kept at /mock/inbox_actions.
INBOX_ACTIONS = []
MERGED = {}


def inbox_merge(body):
    INBOX_ACTIONS.append(dict(body, route="merge"))
    ids = [t.get("id") for t in body.get("items") or []]
    rows = [x for x in INBOX if x["id"] in ids and not x.get("done_at")]
    if len(ids) < 2: return {"error": "请至少选两行再合并", "code": "bad_request"}, 400
    if len(rows) < 2: return {"error": "没有可合并的内容", "code": "merge_none"}, 409
    rows.sort(key=lambda x: x.get("updated_at") or "", reverse=True)
    top, rest = rows[0], rows[1:]
    top["merged_from"] = [{"id": x["id"], "source": x["source"], "account_name": x.get("account_name"), "title": x.get("title")} for x in rest]
    top["count"] = sum(x.get("count", 1) for x in rows)
    MERGED[top["id"]] = rest
    for x in rest: INBOX.remove(x)
    _chain_add(top, "merged", "由 %d 行合并" % len(rows))
    return {"item": dict({k: v for k, v in top.items() if k != "context"}, version=inbox_version(top)), "members": [x["id"] for x in rest], "undo": {"id": top["id"]}}, 200


def inbox_unmerge(body):
    INBOX_ACTIONS.append(dict(body, route="merge/undo"))
    top = next((x for x in INBOX if x["id"] == body.get("id")), None)
    if top is None or top["id"] not in MERGED: return {"error": "没有可拆开的合并", "code": "bad_request"}, 400
    rest = MERGED.pop(top["id"])
    INBOX.extend(rest)
    top.pop("merged_from", None)
    top["count"] = max(1, top.get("count", 1) - sum(x.get("count", 1) for x in rest))
    return {"changed": [top] + rest}, 200


def inbox_todo(body):
    INBOX_ACTIONS.append(dict(body, route="todo"))
    out = {"changed": [], "unchanged": [], "skipped": [], "failed": [], "todos": [], "undo": {"items": []}}
    for t in body.get("items") or []:
        x = next((x for x in INBOX if x["id"] == t.get("id")), None)
        if x is None: out["skipped"].append({"id": t.get("id"), "reason": "missing"}); continue
        if x.get("done_at"): out["unchanged"].append(x["id"]); continue
        if t.get("version") and t["version"] != inbox_version(x): out["skipped"].append({"id": x["id"], "reason": "changed"}); continue
        todo_id = "todo-%s-%d" % (x["id"], len(INBOX_ACTIONS))
        x["done_at"], x["done_by"] = ago(minutes=0), "todo"
        _chain_add(x, "done", "已转成待办", link={"type": "todo", "id": todo_id})
        out["changed"].append(dict({k: v for k, v in x.items() if k != "context"}, version=inbox_version(x)))
        out["todos"].append({"item": {"id": x["id"]}, "todo": {"id": todo_id, "title": t.get("title") or x.get("title")}})
        out["undo"]["items"].append({"id": x["id"], "todo_id": todo_id})
    return out, 200


def inbox_todo_undo(body):
    INBOX_ACTIONS.append(dict(body, route="todo/undo"))
    changed = []
    for t in body.get("items") or []:
        x = next((x for x in INBOX if x["id"] == t.get("id")), None)
        if x is not None and x.get("done_by") == "todo":
            x.pop("done_at", None), x.pop("done_by", None)
            changed.append(x)
    return {"changed": changed}, 200


def _chain_add(x, kind, text, **more):
    x.setdefault("chain", []).append(dict({"id": "c%d" % (len(x["chain"]) + 1), "at": ago(), "kind": kind, "text": text}, **more))


def inbox_suggestion(iid, body):
    """POST /api/v1/inbox/{id}/suggestion (MOCK_INBOX_EVENTS): confirm / reject / instruct the current suggestion."""
    x = next((x for x in INBOX if x["id"] == iid), None)
    if x is None: return {"error": "收件箱里没有这一条", "code": "not_found"}, 404
    if x.get("done_at"): return {"error": "这件事已经处理了", "code": "inbox_item_done"}, 409
    s, action = x.get("suggestion"), body.get("action")
    if action not in ("confirm", "reject", "instruct"): return {"error": "action 不对", "code": "bad_request"}, 400
    if not s or body.get("version") != s.get("version"):
        return {"error": "建议已更新", "code": "suggestion_stale", "item": x}, 409
    if action == "instruct" and not (body.get("text") or "").strip(): return {"error": "要说一句话", "code": "bad_request"}, 400
    SENT.append(dict(body, inbox=iid))
    x.pop("suggestion", None)
    x.pop("agent", None)
    # a hand-off conversation's suggestion leaves the item's processing state alone (assistant/inbox_handoff.go)
    h = {} if s.get("conversation") else x.setdefault("handling", {"owner": "manager"})
    if action == "reject":
        _chain_add(x, "rejected", "你驳回了")
        h.update(state="looking", since=ago()); x["status"] = "working"
    elif action == "instruct":
        _chain_add(x, "instructed", "你说：" + body["text"], detail=body["text"])
        h.update(state="looking", since=ago()); x["status"] = "working"
    elif s.get("handback"):
        _chain_add(x, "confirmed", "你确认了", detail=s["text"])
        h.update(state="looking", since=ago()); x["status"] = "working"
    else:
        text = body.get("text") or s["text"]
        edited = text != s["text"]
        _chain_add(x, "confirmed", "你确认了（改过文字）" if edited else "你确认了", detail=text, **({"edited": True} if edited else {}))
        if s["kind"] == "reply" and s.get("conversation"):
            # a hand-off conversation's reply (#5932): sent and filed as replied; nobody follows the other side's answer
            _chain_add(x, "sent", "发了邮件" if x.get("mail") else "发了飞书消息", link={"type": "source"})
            x.pop("status", None)
            x["done_at"], x["done_by"] = ago(), "replied"
        elif s["kind"] == "reply":
            _chain_add(x, "sent", "发了邮件" if x.get("mail") else "发了飞书消息", link={"type": "source"})
            h.update(state="waiting", since=ago()); x["status"] = "working"
        elif s["kind"] == "agent":
            _chain_add(x, "agent", "开了子会话：" + text[:40], link={"type": "session", "machine_id": "m1", "session_id": "s-mock-agent"})
            h.update(state="agent", since=ago()); x["status"] = "working"
        elif s["kind"] == "todo":  # Add to to-dos (#6480): the row is filed with a link to the to-do
            INBOX_ACTIONS.append({"route": "suggestion", "text": body.get("text"), "due": body.get("due")})
            _chain_add(x, "done", "已转成待办", link={"type": "todo", "id": "todo-" + x["id"]})
            x["done_at"], x["done_by"] = ago(), "todo"
        else:  # a conclusion: Got it files it (the chain says so)
            _chain_add(x, "done", "你标了已处理")
            x["done_at"], x["done_by"] = ago(), "user"
    x["updated_at"] = ago()
    return x, 200


def inbox_suggestion_bump(iid):
    """GET /mock/inbox_events/bump?id=: the manager wrote a new suggestion meanwhile (the open card's version is stale)."""
    x = next((x for x in INBOX if x["id"] == iid), None)
    if not x or not x.get("suggestion"): return {"error": "no suggestion"}, 404
    s = x["suggestion"]
    s.update(version=s["version"] + 1, text=s["text"] + "（已按新消息更新）", at=ago())
    return x, 200


# Hand to AI's main-chat target (POST /api/v1/inbox/{id}/handoff, docs/assistant/inbox.md "Item actions", #1194): the text
# goes after a block naming the item to the main conversation (started with it when there is none), once per client_id,
# and lands in its transcript MOCK_ASSISTANT_TRANSCRIPT_SECONDS later (default 1) under that id, as the hub's
# session.send_once does; under none when it started the conversation (the hub's start takes no message id). The item keeps the hand-off and its chain gets one entry per conversation. What went is in
# /mock/sent and /mock/sent_to. MOCK_HANDOFF=old: a hub from before the route (404).
HANDOFFS = {}  # client_id -> the answer given
# Another manager's main conversation a hand-off started (X-Persona-Manager names it): its assistant runs on its own
# computer (MANAGED_MACHINES; 工作's MacBook), so the conversation is there, not on the default's.
MANAGER_MAINS = {}


def inbox_handoff(iid, body, manager=""):
    if os.environ.get("MOCK_HANDOFF") == "old": return {"error": "404 page not found"}, 404
    x = next((x for x in INBOX if x["id"] == iid), None)
    if x is None: return {"error": "收件箱里没有这一条", "code": "not_found"}, 404
    text, cid = (body.get("text") or "").strip(), (body.get("client_id") or "").lower()
    if not text: return {"error": "text is required"}, 400
    if cid in HANDOFFS: return HANDOFFS[cid], 200
    own = next((m for m, owner in MANAGED_MACHINES.items() if owner == manager), "") if manager and manager != MANAGERS["default"] and _stamps() else ""
    if own:
        mid, started = own, manager not in MANAGER_MAINS
        if started:
            session = assistant_sess(str(uuid.uuid4()), "", 0, "")
            session.update(machine_id=mid, status="working", state="working")
            MANAGER_MAINS[manager] = session["session_id"]
            ASSISTANT.append(session)
            push_machine(mid)
        sid = MANAGER_MAINS[manager]
    else:
        mid, started = ASSISTANT_CONFIG["machine_id"], not ASSISTANT_CONFIG["main"]
    if not own and started:
        sid = str(uuid.uuid4())
        session = assistant_sess(sid, "", 0, "")
        session.update(status="working", state="working", main=True)
        ASSISTANT_CONFIG["main"] = sid
        ASSISTANT.append(session)
        push_machine(mid)
    if not own:
        sid = ASSISTANT_CONFIG["main"]
    head = '<persona-context kind="context" title="收件箱事件 · %s" url="">\n用户从收件箱把这件事交给你（事件 id：%s）。\n</persona-context>\n' % (
        x["title"].replace('"', "'"), iid)
    sent = {"text": head + text} if started else {"text": head + text, "client_msg_id": cid}
    echo_sent(["", "api", "v1", "sessions", mid, sid, "messages"], sent, float(os.environ.get("MOCK_ASSISTANT_TRANSCRIPT_SECONDS", "1")))
    SENT.append(dict(sent, inbox=iid))
    SENT_TO.append({"machine_id": mid, "session_id": sid, "client_msg_id": sent.get("client_msg_id"), "text": sent["text"]})
    x.setdefault("handoffs", []).append({"machine_id": mid, "session_id": sid, "at": ago()})
    if not any(e.get("kind") == "handling" and (e.get("link") or {}).get("session_id") == sid for e in x.get("chain") or []):
        _chain_add(x, "handling", "交给了 Persona 主对话", link={"type": "session", "machine_id": mid, "session_id": sid})
    HANDOFFS[cid] = {"item": x, "session": {"machine_id": mid, "session_id": sid}}
    return HANDOFFS[cid], 200


# MOCK_INBOX_LINE=1: a "Thread" (#2128): the design review grew out of the chat with the sample contact (continues), which hangs under a todo; the
# the weekend hiking group item grew out of the design review. GET /api/v1/inbox/tree/{kind}/{id} answers from the items' parents.
if os.environ.get("MOCK_INBOX_LINE") == "1":
    for x in INBOX:
        if x["id"] == "lark:f1:100": x["parent"] = {"kind": "todo", "id": "todo-1", "by": "user"}
        if x["id"] == "lark:f2:200": x["parent"] = {"kind": "inbox", "id": "lark:f1:100", "by": "continues"}
        if x["id"] == "lark:f3:300": x["parent"] = {"kind": "inbox", "id": "lark:f2:200", "by": "user"}


def inbox_tree(kind, nid):
    """GET /api/v1/inbox/tree/{kind}/{id}: the node's ancestors (nearest first) and the items right under it."""
    by_id = {x["id"]: x for x in INBOX}
    out = {"node": {"kind": kind, "id": nid}, "ancestors": [], "children": []}
    if kind == "inbox":
        if nid not in by_id: return None
        out["item"] = by_id[nid]
        p, n = by_id[nid].get("parent"), 0
        while p and n < 9:
            up = dict(p)
            nxt = None
            if p["kind"] == "inbox" and p["id"] in by_id:
                up["item"], nxt = by_id[p["id"]], by_id[p["id"]].get("parent")
            out["ancestors"].append(up)
            p, n = nxt, n + 1
    out["children"] = [x for x in INBOX if (x.get("parent") or {}).get("kind") == kind and x["parent"]["id"] == nid]
    return out

