    _loads = [0]  # how many times the page itself was asked for: a reopen or "Refresh" loads it again (PortForwardTests)

    class _Dev(BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path.split("?")[0] == "/":
                _loads[0] += 1
            b = _page.replace("{n}", str(_loads[0])).encode()
            self.send_response(200); self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(b))); self.end_headers(); self.wfile.write(b)

        def log_message(self, *a): pass

    _dev = ThreadingHTTPServer(("127.0.0.1", 0), _Dev)
    threading.Thread(target=_dev.serve_forever, daemon=True).start()
