# MOCK_SCREEN_BG=black|white|gray|terminal (#3075): the mock Mac is 1920×1080 as a real one is, one plain color (a
# terminal: near black with lines of light-gray text), and like macOS's its Screen Sharing sends no pointer (the app
# draws its own); MOCK_SCREEN_CURSOR=1 sends macOS's arrow when asked, as other servers do (the Cursor pseudo-encoding:
# its 1× pixels, black with a white outline, and its mask). GET /mock/screen-password?bg=… changes the background on
# the screens connected (the pointer's look over each, VNCTests.testThePointerReads).
FAKE_BG = {"kind": os.environ.get("MOCK_SCREEN_BG", "")}
FAKE_BG_COLORS = {"black": (0, 0, 0), "white": (255, 255, 255), "gray": (128, 128, 128), "terminal": (30, 30, 32)}
FAKE_TEXT = (204, 204, 204)
if FAKE_BG["kind"]:
    FAKE_W, FAKE_H = 1920, 1080
# macOS's arrow at 1× as its Screen Sharing sends it ("#" black, "o" white), its hot spot at its tip.
FAKE_ARROW = ["oo........", "o#o.......", "o##o......", "o###o.....", "o####o....", "o#####o...", "o######o..", "o#######o.",
              "o########o", "o########o", "o#####oooo", "o##o##+o..", "o+ooo##o..", ".o+.o##+o.", "....o+##o.", ".....o++o.",
              "......oo.."]
FAKE_ARROW_HOT = (1, 1)


def fake_cursor_rect():
    """The Cursor pseudo-encoding of FAKE_ARROW: x, y the hot spot; its pixels in the client's format (B G R and a
    byte of padding); then its mask, a bit a pixel, rows padded to a byte."""
    w, h = len(FAKE_ARROW[0]), len(FAKE_ARROW)
    shade = {"#": 0, "o": 255, "+": 128}
    px, mask = b"", b""
    for row in FAKE_ARROW:
        bits = 0
        for i, ch in enumerate(row):
            v = shade.get(ch, 0)
            px += bytes([v, v, v, 0])
            if ch in shade: bits |= 1 << (((w + 7) // 8) * 8 - 1 - i)
        mask += bits.to_bytes((w + 7) // 8, "big")
    return struct.pack(">HHHHi", FAKE_ARROW_HOT[0], FAKE_ARROW_HOT[1], w, h, -239) + px + mask


def fake_text(x, y):
    """1 where a terminal's text is: lines 36 pixels apart, characters 16 wide, of lengths that vary, with spaces."""
    if not (40 <= x < 1400 and 40 <= y < 760): return 0
    line, ly = divmod(y - 40, 36)
    col, lx = divmod(x - 40, 16)
    return 1 if ly < 18 and lx < 11 and col < (line * 37) % 70 + 8 and (col * 7 + line) % 11 else 0


def fake_bg_rect(z):
    """The whole of a plain background in ZRLE: solid tiles, and two-color ones where a terminal has text."""
    base = FAKE_BG_COLORS.get(FAKE_BG["kind"], (0, 0, 0))
    cp = lambda c: bytes([c[2], c[1], c[0]])
    out = bytearray()
    for ty in range(0, FAKE_H, 64):
        for tx in range(0, FAKE_W, 64):
            tw, th = min(64, FAKE_W - tx), min(64, FAKE_H - ty)
            if FAKE_BG["kind"] != "terminal" or not (tx < 1400 and ty < 760 and tx + tw > 40 and ty + th > 40):
                out += b"\x01" + cp(base)
                continue
            out += bytes([2]) + cp(base) + cp(FAKE_TEXT)
            for j in range(th):
                acc = n = 0
                for i in range(tw):
                    acc = acc << 1 | fake_text(tx + i, ty + j); n += 1
                    if n == 8: out.append(acc); acc = n = 0
                if n: out.append(acc << (8 - n))
    comp = z.compress(bytes(out)) + z.flush(zlib.Z_SYNC_FLUSH)
    return struct.pack(">HHHHi", 0, 0, FAKE_W, FAKE_H, 16) + struct.pack(">I", len(comp)) + comp


# The displays' numbers, 3×5 cells each, drawn 12 pixels a cell.
FAKE_DIGITS = {1: [".#.", "##.", ".#.", ".#.", "###"], 2: ["###", "..#", "###", "#..", "###"],
               3: ["###", "..#", "###", "..#", "###"], 4: ["#.#", "#.#", "###", "..#", "..#"]}


# MOCK_SCREEN_SCROLL=1 (#6196): the first window holds lines of made-up text that the Mac's wheel scrolls, a notch
# FAKE_SCROLL_STEP pixels (up: what is above), so a screen recording shows a two-finger scroll reaching the Mac.
FAKE_SCROLL = {"on": os.environ.get("MOCK_SCREEN_SCROLL") == "1", "y": 0}
FAKE_SCROLL_STEP = 6


def fake_text_line(lx, y):
    """Inside the first window's body, scrolled: a gray bar every 12 pixels, its length from its line number."""
    row = y - 74 + FAKE_SCROLL["y"]
    line, dy = divmod(row, 12)
    if not 3 <= dy < 9 or not 76 <= lx: return False
    if line % 10 == 0: return lx < 76 + 160 and dy >= 2  # a heading every ten lines
    return lx < 76 + 120 + (line * 37) % 200


def fake_frame(t=0):
    """The mock Mac's desktop as rows of (r, g, b): a gradient, a window, and a box that moves with t (animated). With
    several displays, each its own gradient and window with its number; the box stays on the first."""
    px = []
    bx, by = 80 + (t * 7) % 300, 120 + (t * 3) % 120
    for y in range(FAKE_H):
        for x in range(FAKE_W):
            d, lx = divmod(x, 480)
            if bx <= x < bx + 40 and by <= y < by + 40 and not FAKE_SCROLL["on"]: px.append((255, 159, 10))
            elif 60 <= lx < 420 and 50 <= y < 250:
                digit = FAKE_DIGITS.get(d + 1) if FAKE_DISPLAYS > 1 else None
                cx, cy = (lx - 222) // 12, (y - 120) // 12
                if digit and 222 <= lx and 120 <= y and cx < 3 and cy < 5 and digit[cy][cx] == "#": px.append((60, 60, 67))
                elif FAKE_SCROLL["on"] and d == 0 and y >= 74 and fake_text_line(lx, y): px.append((120, 120, 128))
                else: px.append((236, 236, 238) if y < 74 else (250, 250, 252))
            elif d == 0: px.append((40 + y // 6, 90 + y // 8, 160))
            else: px.append((40 + y // 8, 150 + y // 6 % 60, 90))
    return px


def zrle_rect(px, W, x, y, w, h, z):
    """ZRLE for (x, y, w, h) of px (rows of W): solid, packed palette or raw tiles, through the connection's zlib z."""
    out = b""
    for ty in range(y, y + h, 64):
        for tx in range(x, x + w, 64):
            tw, th = min(64, x + w - tx), min(64, y + h - ty)
            tile = [px[(ty + j) * W + tx + i] for j in range(th) for i in range(tw)]
            cols = list(dict.fromkeys(tile))
            cp = lambda c: bytes([c[2], c[1], c[0]])
            if len(cols) == 1:
                out += b"\x01" + cp(cols[0])
            elif len(cols) <= 16:
                bits = 1 if len(cols) == 2 else 2 if len(cols) <= 4 else 4
                out += bytes([len(cols)]) + b"".join(cp(c) for c in cols)
                for j in range(th):
                    acc = n = 0; row = b""
                    for i in range(tw):
                        acc = acc << bits | cols.index(tile[j * tw + i]); n += bits
                        if n == 8: row += bytes([acc]); acc = n = 0
                    if n: row += bytes([acc << (8 - n)])
                    out += row
            else:
                out += b"\x00" + b"".join(cp(c) for c in tile)
    comp = z.compress(out) + z.flush(zlib.Z_SYNC_FLUSH)
    return struct.pack(">I", len(comp)) + comp


# MOCK_SCREEN_VIDEO=1|missing|denied (#3954): MacBook's node offers the live screen's video channel (`screen_video`;
# =missing: Screen Recording isn't granted for Persona Screen and macOS hasn't asked yet; =denied: not granted, asked
# once already, so Persona Screen is in System Settings' list), and …/screen/video/connect?pair=… plays
# scripts/mock/screen_video/fixture.bin (HEVC) or fixture-h264.bin (a made-up desktop; make_fixture.sh makes them again),
# picked as the helper picks its codec: the first of the `start`'s codecs there is a fixture for, else H.264 (#6558: a
# browser without HEVC offers only H.264), round and round at 30 fps:
# `hello`, `format`, then its frames, numbered on and stamped with this clock. Only for a pair a 5900 connection carried
# (else 403, as the node's not_signed_in). GET /mock/screen-video says what the phone sent (`start`s, report count) and
# how many streams are open; …?drop=1 closes them all, ?refuse=1 refuses new ones (503, ?refuse=0 back), ?pause=locked
# sends `paused` with that reason (no frames and no heartbeats, as the helper), ?resume=1 sends `resumed` and starts over
# with `hello`, `format` and the keyframe. Once a second while frames go out it sends `timing` as the helper does: capture
# 0 and encode 4.8 ms (made up: nothing is encoded here), the network as half the real round trip from a frame going out
# to the phone's report on it. MOCK_SCREEN_VIDEO_TIERS=1: the hello says the helper has quality tiers (`features`,
# #6396) on a 14-inch MacBook Pro's display (`points`, `pixels`; the fixture plays at its own size whatever the tier);
# GET /mock/screen-video also lists the `update`s the client sent (#6558: a new data budget, the tier it picked).
SCREEN_VIDEO = {"mode": os.environ.get("MOCK_SCREEN_VIDEO", ""), "pairs": set(), "streams": [], "starts": [], "reports": 0,
                "updates": [], "refuse": False, "tiers": os.environ.get("MOCK_SCREEN_VIDEO_TIERS") == "1"}
_SCREEN_VIDEO_FIXTURE = {}
_SCREEN_VIDEO_FILES = {"hevc": "fixture.bin", "h264": "fixture-h264.bin"}


def screen_video_codec(offered):
    """The codec the helper would pick (CapturePlan.codec): the first offered one with a fixture, else H.264."""
    return next((c.lower() for c in offered or [] if c.lower() in _SCREEN_VIDEO_FILES), "h264")


def screen_video_fixture(codec="hevc"):
    """The fixture's messages for `codec` as (type, body), read once."""
    if codec not in _SCREEN_VIDEO_FIXTURE:
        name = _SCREEN_VIDEO_FILES[codec]
        data = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "screen_video", name), "rb").read()
        msgs, i = [], 0
        while i < len(data):
            n = struct.unpack(">I", data[i:i + 4])[0]
            msgs.append((data[i + 4], data[i + 5:i + 4 + n]))
            i += 4 + n
        _SCREEN_VIDEO_FIXTURE[codec] = msgs
    return _SCREEN_VIDEO_FIXTURE[codec]


def screen_video_control(h, q):
    if q.get("drop", ["0"])[0] == "1":
        for st in list(SCREEN_VIDEO["streams"]): st["open"] = False
    if "refuse" in q: SCREEN_VIDEO["refuse"] = q["refuse"][0] == "1"
    if "pause" in q:
        for st in SCREEN_VIDEO["streams"]: st["pause"] = q["pause"][0]
    if q.get("resume", ["0"])[0] == "1":
        for st in SCREEN_VIDEO["streams"]: st["resume"] = True
    h.send_json({"open": sum(1 for st in SCREEN_VIDEO["streams"] if st["open"]), "starts": SCREEN_VIDEO["starts"],
                 "reports": SCREEN_VIDEO["reports"], "updates": SCREEN_VIDEO["updates"], "refuse": SCREEN_VIDEO["refuse"]})


def screen_video_connect(h, mid):
    """…/screen/video/connect?pair=…: the helper's side of the video channel, from the fixture (see MOCK_SCREEN_VIDEO)."""
    pair = parse_qs(urlparse(h.path).query).get("pair", [""])[0]
    if not pair: return h.send_json({"error": "a pair is required"}, 400)
    if pair not in SCREEN_VIDEO["pairs"]:
        return h.send_json({"error": "the paired screen-sharing stream has not signed in"}, 403)
    if SCREEN_VIDEO["refuse"] or SCREEN_VIDEO["mode"] in ("missing", "denied"):
        return h.send_json({"error": "no live-screen video helper on this node"}, 503)
    key = h.headers.get("Sec-WebSocket-Key", "")
    accept = base64.b64encode(hashlib.sha1((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").encode()).digest()).decode()
    h.send_response(101, "Switching Protocols")
    h.send_header("Upgrade", "websocket"); h.send_header("Connection", "Upgrade")
    h.send_header("Sec-WebSocket-Accept", accept); h.end_headers(); h.wfile.flush()
    st = {"open": True, "pause": None, "resume": False, "started": threading.Event(), "sent": {}, "rtts": []}
    SCREEN_VIDEO["streams"].append(st)
    lock = threading.Lock()

    def ws(op, data):
        n = len(data)
        hdr = bytes([0x80 | op]) + (bytes([n]) if n < 126 else bytes([126]) + struct.pack(">H", n) if n < 65536 else bytes([127]) + struct.pack(">Q", n))
        with lock:
            h.wfile.write(hdr + data); h.wfile.flush()

    def msg(t, body):
        ws(0x2, struct.pack(">IB", len(body) + 1, t) + body)

    def play():
        if not st["started"].wait(10): st["open"] = False; return
        msgs = screen_video_fixture(screen_video_codec(st.get("codecs")))
        hello, fmt, frames = msgs[0], msgs[1], msgs[2:]
        if SCREEN_VIDEO["tiers"]:  # as the helper says it: the display's points and pixels (a 14-inch MacBook Pro's) for the tiers
            hello = (hello[0], json.dumps({**json.loads(hello[1]), "features": ["tiers"], "points": [1512, 982], "pixels": [3024, 1964]}).encode())
        number, i, restart = 0, 0, True
        second, count, size = time.monotonic(), 0, 0
        try:
            while st["open"]:
                if st["pause"]:
                    msg(5, json.dumps({"reason": st["pause"]}).encode())
                    st["pause"] = None
                    while st["open"] and not st["resume"]: time.sleep(0.1)
                if st["resume"]:
                    st["resume"] = False
                    msg(6, b"{}")
                    restart = True
                if restart: msg(*hello); msg(*fmt); i, restart = 0, False
                body = frames[i][1]
                number += 1
                st["sent"][number] = time.monotonic()
                st["sent"].pop(number - 256, None)
                msg(3, struct.pack(">IQ", number, int(time.monotonic() * 1e6)) + body[12:])
                count, size = count + 1, size + len(body)
                i = (i + 1) % len(frames)
                if time.monotonic() - second >= 1:
                    took, rtts = time.monotonic() - second, sorted(st["rtts"])
                    st["rtts"] = []
                    network = round(rtts[len(rtts) // 2] / 2 * 1000, 1) if rtts else None
                    msg(7, json.dumps({"capture_ms": 0.0, "encode_ms": 4.8, "network_ms": network,
                                       "kbps": round(size * 8 / 1000 / took), "fps": round(count / took)}).encode())
                    second, count, size = time.monotonic(), 0, 0
                time.sleep(1 / 30)
        except OSError:
            pass
        try: ws(0x8, struct.pack(">H", 1000))
        except OSError: pass
        st["open"] = False

    threading.Thread(target=play, daemon=True).start()
    buf, r = b"", h.rfile
    try:
        while st["open"]:
            hd = r.read(2)
            if len(hd) < 2: break
            op = hd[0] & 0x0F; n = hd[1] & 0x7F
            if n == 126: n = struct.unpack(">H", r.read(2))[0]
            elif n == 127: n = struct.unpack(">Q", r.read(8))[0]
            mask = r.read(4) if hd[1] & 0x80 else b"\0\0\0\0"
            payload = bytes(b ^ mask[k % 4] for k, b in enumerate(r.read(n)))
            if op == 8: break
            if op == 9: ws(0xA, payload); continue
            buf += payload
            while len(buf) >= 4 and len(buf) >= 4 + struct.unpack(">I", buf[:4])[0]:
                n = struct.unpack(">I", buf[:4])[0]
                t, body, buf = buf[4], buf[5:4 + n], buf[4 + n:]
                if t == 16:
                    start = json.loads(body or b"{}")
                    SCREEN_VIDEO["starts"].append(start)
                    st["codecs"] = start.get("codecs")
                    st["started"].set()
                elif t == 19:
                    SCREEN_VIDEO["updates"].append(json.loads(body or b"{}"))
                elif t == 17:
                    SCREEN_VIDEO["reports"] += 1
                    sent = st["sent"].pop(struct.unpack(">I", body[:4])[0], None) if len(body) >= 4 else None
                    if sent is not None: st["rtts"].append(time.monotonic() - sent)
    except OSError:
        pass
    st["open"] = False
    h.close_connection = True


def fake_screen_sharing():
    """Listens on 127.0.0.1 and serves RFB 3.8 as macOS's Screen Sharing offers it: Apple Remote Desktop's sign-in (30;
    the AES through openssl) and VeNCrypt Plain; ZRLE when asked for, else Raw. Its port is FAKE_SCREEN["port"]."""
    import socket, shutil, subprocess, random as _r

    ard = bool(shutil.which("openssl"))

    def exact(c, n):
        b = b""
        while len(b) < n:
            got = c.recv(n - len(b))
            if not got: raise OSError("closed")
            b += got
        return b

    def signed_in(c, user, pw):
        ok = user == FAKE_SCREEN["account"] and pw == FAKE_SCREEN["password"]
        FAKE_SCREEN["signins"].append({"account": user, "ok": ok})  # never the password
        if not ok:
            why = b"Authentication failed"
            c.sendall(struct.pack(">I", 1) + struct.pack(">I", len(why)) + why)
        return ok

    def serve(c):
        lock = threading.Lock()
        conn = {"sock": c, "lock": lock}
        if FAKE_SCREEN["down"]: return c.close()
        time.sleep(FAKE_SCREEN["slow"])
        try:
            c.sendall(b"RFB 003.889\n"); exact(c, 12)
            types = [30, 19] if ard else [19]
            c.sendall(bytes([len(types)] + types))
            kind = exact(c, 1)[0]
            if kind == 30:  # ARD: Diffie-Hellman, then the account and password sealed with AES-128 by its MD5
                p = _r.getrandbits(1024) | (1 << 1023) | 1
                y = _r.getrandbits(1000)
                c.sendall(b"\x00\x02" + struct.pack(">H", 128) + p.to_bytes(128, "big") + pow(2, y, p).to_bytes(128, "big"))
                sealed, theirs = exact(c, 128), exact(c, 128)
                key = hashlib.md5(pow(int.from_bytes(theirs, "big"), y, p).to_bytes(128, "big")).digest()
                block = subprocess.run(["openssl", "enc", "-d", "-aes-128-ecb", "-nopad", "-K", key.hex()],
                                       input=sealed, capture_output=True).stdout
                user, pw = block[:64].split(b"\0")[0].decode(errors="replace"), block[64:].split(b"\0")[0].decode(errors="replace")
            elif kind == 19:  # VeNCrypt 0.2, Plain
                c.sendall(bytes([0, 2])); exact(c, 2); c.sendall(bytes([0]))
                c.sendall(bytes([1]) + struct.pack(">I", 256)); exact(c, 4)
                ulen, plen = struct.unpack(">II", exact(c, 8))
                user, pw = exact(c, ulen).decode(), exact(c, plen).decode()
            else:
                return
            if not signed_in(c, user, pw): return
            c.sendall(struct.pack(">I", 0)); exact(c, 1)  # SecurityResult ok; ClientInit
            fmt = struct.pack(">BBBBHHHBBB3x", 32, 24, 0, 1, 255, 255, 255, 16, 8, 0)
            name = b"Mock Mac"
            c.sendall(struct.pack(">HH", FAKE_W, FAKE_H) + fmt + struct.pack(">I", len(name)) + name)
            FAKE_SCREEN["conns"].append(conn)
            encodings, z, t, sent = [], zlib.compressobj(6), 0, False
            frame = [] if FAKE_BG["kind"] else fake_frame()

            def redraw():  # a plain background again (?bg=…), on the update request the client left waiting
                if 16 not in encodings: return
                with lock:
                    c.sendall(struct.pack(">BxH", 0, 1) + fake_bg_rect(z))
                FAKE_SCREEN["frames"] += 1
            conn["redraw"] = redraw

            def update(rects, extended=False):
                if FAKE_BG["kind"]:
                    cursor = -239 in encodings and os.environ.get("MOCK_SCREEN_CURSOR") == "1"
                    with lock:
                        c.sendall(struct.pack(">BxH", 0, 1 + cursor) + (fake_cursor_rect() if cursor else b"") + fake_bg_rect(z))
                    FAKE_SCREEN["frames"] += 1
                    return
                body = b""
                if extended:  # ExtendedDesktopSize: reason 0, status 0, the framebuffer's size, then each display
                    body += struct.pack(">HHHHi", 0, 0, FAKE_W, FAKE_H, -308) + struct.pack(">B3x", FAKE_DISPLAYS)
                    body += b"".join(struct.pack(">IHHHHI", i + 1, 480 * i, 0, 480, FAKE_H, 0) for i in range(FAKE_DISPLAYS))
                for (x, y, w, h) in rects:
                    if 16 in encodings:
                        body += struct.pack(">HHHHi", x, y, w, h, 16) + zrle_rect(frame, FAKE_W, x, y, w, h, z)
                    else:
                        body += struct.pack(">HHHHi", x, y, w, h, 0) + b"".join(
                            bytes([*frame[(y + j) * FAKE_W + x + i][::-1], 0]) for j in range(h) for i in range(w))
                with lock:
                    c.sendall(struct.pack(">BxH", 0, len(rects) + (1 if extended else 0)) + body)
                FAKE_SCREEN["frames"] += 1

            while True:  # SetPixelFormat 20, SetEncodings 4 + 4n, FramebufferUpdateRequest 10, key 8, pointer 6, cut 8 + n
                kind = exact(c, 1)[0]
                if kind == 0: exact(c, 19)
                elif kind == 2:
                    exact(c, 1); n = struct.unpack(">H", exact(c, 2))[0]
                    encodings = list(struct.unpack(">%di" % n, exact(c, 4 * n)))
                elif kind == 3:
                    exact(c, 9)
                    conn["waiting"] = sent
                    if conn.pop("scrolled", False):  # MOCK_SCREEN_SCROLL: the window's lines moved since the last update
                        conn["waiting"] = False
                        frame = fake_frame(t)
                        update([(60, 74, 360, 176)])
                    elif not sent:
                        sent = True
                        update([(0, 0, FAKE_W, FAKE_H)], extended=FAKE_EXTENDED and -308 in encodings)
                    elif os.environ.get("MOCK_SCREEN_ANIMATE") == "1" and not FAKE_BG["kind"]:  # a box moving at ~30 frames a second
                        time.sleep(1 / 30)
                        old = (80 + (t * 7) % 300, 120 + (t * 3) % 120)
                        t += 1
                        frame = fake_frame(t)
                        ms = int(time.time() * 1000) & 0xffffff  # when it was sent, for the app to measure (RFBFrameSink)
                        frame[0], frame[1] = (255, 0, 255), (ms >> 16, (ms >> 8) & 255, ms & 255)
                        new = (80 + (t * 7) % 300, 120 + (t * 3) % 120)
                        x0, y0 = min(old[0], new[0]), min(old[1], new[1])
                        update([(0, 0, 2, 1), (x0, y0, min(FAKE_W - x0, abs(new[0] - old[0]) + 40), min(FAKE_H - y0, abs(new[1] - old[1]) + 40))])
                elif kind == 4:  # a key: what is typed on the lock screen ("Unlock", #1507 a-2), Return as \n
                    down, _, key = struct.unpack(">BHI", exact(c, 7))
                    FAKE_SCREEN["events"].append({"key": key, "down": bool(down)})
                    if down and key == 0xff0d: FAKE_SCREEN["typed"] += "\n"
                    elif down and (0x20 <= key <= 0xff): FAKE_SCREEN["typed"] += chr(key)
                    elif down and key >= 0x01000000: FAKE_SCREEN["typed"] += chr(key - 0x01000000)
                    if FAKE_SCREEN["typed"].endswith(FAKE_SCREEN["password"] + "\n"):  # the right password: unlocked
                        for m in MACHINES:
                            if m.get("computer", {}).get("desktop") == "locked":
                                m["computer"] = {**COMPUTER_STATES["ready"], "enabled": True}
                elif kind == 5:  # the pointer, and where it went down and up
                    mask, x, y = struct.unpack(">BHH", exact(c, 5))
                    last = FAKE_SCREEN["pointer"] or (0, 0, 0)
                    if (last[2] & 1) != (mask & 1): FAKE_SCREEN["clicks"].append({"down": bool(mask & 1), "x": x, "y": y})
                    if mask & 4 and not last[2] & 4: FAKE_SCREEN["clicks"].append({"right": True, "x": x, "y": y})
                    if mask & 24: FAKE_SCREEN["clicks"].append({"scroll": "up" if mask & 8 else "down", "x": x, "y": y})
                    if FAKE_SCROLL["on"] and mask & 24 and not last[2] & 24:  # a notch: the lines move, drawn now or on the next request
                        FAKE_SCROLL["y"] = max(0, FAKE_SCROLL["y"] + (-FAKE_SCROLL_STEP if mask & 8 else FAKE_SCROLL_STEP))
                        if conn.pop("waiting", False):
                            frame = fake_frame(t)
                            update([(60, 74, 360, 176)])
                        else:
                            conn["scrolled"] = True
                    FAKE_SCREEN["pointer"] = (x, y, mask)
                elif kind == 6:  # the client's clipboard
                    exact(c, 3); n = struct.unpack(">I", exact(c, 4))[0]
                    FAKE_SCREEN["clipboard"] = exact(c, n).decode("latin-1")
                    FAKE_SCREEN["events"].append({"clipboard": FAKE_SCREEN["clipboard"], "via": "rfb"})
                else: return
        except OSError:
            pass
        finally:
            if conn in FAKE_SCREEN["conns"]: FAKE_SCREEN["conns"].remove(conn)
            c.close()

    srv = socket.socket(); srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind(("127.0.0.1", 0)); srv.listen(8)
    FAKE_SCREEN["port"] = srv.getsockname()[1]

    def accept():
        while True:
            c, _ = srv.accept()
            threading.Thread(target=serve, args=(c,), daemon=True).start()
    threading.Thread(target=accept, daemon=True).start()


def fake_screen_clip(text):
    """The mock Mac copies text: its clipboard goes to the connected clients (ServerCutText)."""
    b = text.encode("latin-1", "replace")
    for conn in list(FAKE_SCREEN["conns"]):
        try:
            with conn["lock"]: conn["sock"].sendall(bytes([3, 0, 0, 0]) + struct.pack(">I", len(b)) + b)
        except OSError: pass


if os.environ.get("MOCK_SCREEN") == "fake":
    fake_screen_sharing()


def calculator_png(w=230, h=408):
    """A made-up Calculator window showing 42, drawn here (stdlib only): the screenshot computer_state brings back."""
    import zlib
    px = bytearray(bytes((28, 28, 30)) * w * h)

    def fill(x0, y0, x1, y1, c):
        x0, x1 = max(0, int(x0)), min(w, int(x1))
        for y in range(max(0, int(y0)), min(h, int(y1))):
            if x1 > x0: px[(y * w + x0) * 3:(y * w + x1) * 3] = bytes(c) * (x1 - x0)

    def disc(cx, cy, r, c):
        for y in range(cy - r, cy + r + 1):
            dx = int((r * r - (y - cy) ** 2) ** 0.5)
            fill(cx - dx, y, cx + dx + 1, y + 1, c)

    def digit(x, y, segs, dw=34, dh=56, t=7):  # seven segments: a top, b c right, d bottom, e f left, g middle
        white = (255, 255, 255)
        parts = {"a": (x + t, y, x + dw - t, y + t), "b": (x + dw - t, y + t, x + dw, y + dh // 2),
                 "c": (x + dw - t, y + dh // 2, x + dw, y + dh - t), "d": (x + t, y + dh - t, x + dw - t, y + dh),
                 "e": (x, y + dh // 2, x + t, y + dh - t), "f": (x, y + t, x + t, y + dh // 2),
                 "g": (x + t, y + dh // 2 - t // 2, x + dw - t, y + dh // 2 + t // 2 + 1)}
        for k in segs: fill(*parts[k], white)

    for i, c in enumerate([(255, 95, 87), (254, 188, 46), (40, 200, 64)]):  # the window's three buttons
        disc(18 + i * 20, 16, 6, c)
    digit(134, 78, "fgbc")   # 4
    digit(178, 78, "abged")  # 2
    d, gap, top = 44, 8, 150
    for row in range(5):
        for col in range(4):
            c = (255, 159, 10) if col == 3 else (165, 165, 165) if row == 0 else (51, 51, 51)
            cx, cy = 12 + col * (d + gap) + d // 2, top + row * (d + gap) + d // 2
            if row == 4 and col == 0:  # 0 is twice as wide
                disc(cx, cy, d // 2, c); disc(cx + d + gap, cy, d // 2, c); fill(cx, cy - d // 2, cx + d + gap, cy + d // 2 + 1, c)
            elif not (row == 4 and col == 1):
                disc(cx, cy, d // 2, c)
    raw = b"".join(b"\0" + bytes(px[y * w * 3:(y + 1) * w * 3]) for y in range(h))
    def chunk(t, d): return struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b""))


def churn(rounds, ms, steps=1, final=False, inbox=False, waiting=False, real=False, rows=0):
    """`rows` > 0: only that many working agents change a round, taking turns (a real hub changes a row or two a
    second, #3759); 0: every working agent every round."""
    import time
    flips = [s for s in SESSIONS if s["state"] == "working"][-1:] if real else []
    for k in range(rounds):
        time.sleep(ms / 1000)
        now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
        if inbox and INBOX:
            if not CHURN_INBOX: CHURN_INBOX.extend(copy.deepcopy(INBOX))
            first = INBOX[0]
            first.update(preview="第 %d 条新消息：下午的会改到四点了" % (k + 1), updated_at=now, count=first.get("count", 1) + 1,
                         tier="action" if k % 2 else "fyi")
        if real:  # the agent that finishes and starts again: its space changes rank, now and then, as on the real hub
            for s in flips:
                if k % 3 == 1: s.update(state="unread", status="done", state_since=now)
                elif k % 3 == 2: s.update(state="working", status="working", state_since=now)
        working = [s for s in SESSIONS if s["state"] == "working"]
        changing = [working[(k * rows + j) % len(working)] for j in range(min(rows, len(working)))] if rows else working
        for s in changing:
            text = "第 %d 轮更新：还在跑，刚看完一处。" % (k + 1)
            if real and k % 2:  # a longer last line: the row grows to its two lines, then shrinks back
                text += "接下来把剩下的几个模块的测试都跑一遍，看看还有没有别的地方用到了这个旧接口，顺手把文档也改了。"
            s.update(updated_at=now, last_text=text)
        if len(working) >= 2 and k % 2 == 1 and not rows:  # the busiest space is now a different one
            working[0]["updated_at"] = ago(minutes=30)
        for m in MACHINES:
            m["last_seen"] = now
        churn_removed = []
        churn_added = None
        if waiting:  # Resolved identities never become a different question on the real hub.
            churn_removed = [x["id"] for x in INTERACTIONS if x["id"].startswith("ix_churn")]
            INTERACTIONS[:] = [x for x in INTERACTIONS if x["id"] not in churn_removed]
            if k % 2 == 0 and INTERACTIONS:
                churn_added = "ix_churn_" + uuid.uuid4().hex
                INTERACTIONS.append(dict(INTERACTIONS[0], id=churn_added, created_at=now))
        by = {}
        for s in out_by_machine(all_sessions()): by.setdefault(s["machine_id"], []).append(s)
        for send, subscribed in list(LIVE):
            try:
                send({"type": "machines", "machines": out_machines()})
                for m, ss in by.items(): send({"type": "sessions", "machine_id": m, "sessions": ss})
                pending = out_by_machine(mock_interactions())  # what GET /api/v1/interactions serves: answered ones are gone
                if inbox:
                    send({"type": "inbox"})
                    for ix in pending: send({"type": "interaction", "interaction": ix})
                if waiting:  # another agent starts waiting, then is answered elsewhere
                    for retired in churn_removed:
                        send({"type": "interaction_resolved", "id": retired})
                    if churn_added:
                        added = next((ix for ix in pending if ix["id"] == churn_added), None)
                        if added:
                            send({"type": "interaction", "interaction": added})
                for sid in list(subscribed):
                    items = ITEMS.get(sid)
                    if not items: continue
                    CHURN_ITEMS.setdefault(sid, list(items))
                    before = items[-1]["seq"]
                    new = [x for j in range(steps) for x in tool("Read", {"file_path": "/Users/me/code/weather/Step%d_%d.swift" % (k, j)},
                                                                   "struct Step%d {}" % k, 0)]
                    if k % 4 == 3:  # a word between the steps: it folds into the work line, the turn goes on
                        new = [it("assistant", "text", 0, text="第 %d 处看完了，接着看下一处。" % (k + 1))] + new
                    ITEMS[sid] = items + new
                    mid = next((x["machine_id"] for x in all_sessions() if x["session_id"] == sid), "macbook")
                    send({"type": "items", "machine_id": mid, "session_id": sid, "items": new, **span(new, before)})
            except Exception:
                pass
        CHURN["rounds"] = k + 1
    if final:  # the turn ends: a last reply, and the agents that were working are done
        time.sleep(ms / 1000)
        for s in SESSIONS:
            if s["state"] == "working":
                s.update(state="unread", status="done", last_text="都看完了，改动已经提交。")
        by = {}
        for s in out_by_machine(all_sessions()): by.setdefault(s["machine_id"], []).append(s)
        for send, subscribed in list(LIVE):
            try:
                for sid in list(subscribed):
                    items = ITEMS.get(sid)
                    if not items: continue
                    before = items[-1]["seq"]
                    new = [it("assistant", "text", 0, text="都看完了，改动已经提交。")]
                    ITEMS[sid] = items + new
                    mid = next((x["machine_id"] for x in all_sessions() if x["session_id"] == sid), "macbook")
                    send({"type": "items", "machine_id": mid, "session_id": sid, "items": new, **span(new, before)})
                for m, ss in by.items(): send({"type": "sessions", "machine_id": m, "sessions": ss})
            except Exception:
                pass
        CHURN["rounds"] += 1


# ---------- truth and single changes (ScreenTruthTests, RenderBudgetTests; docs/apple/ios-state.md) ----------
# GET /mock/truth: what the hub holds now, shaped like the app's probe.agents-list (`states` and `last` by
# "<machine>/<session>", `asks` the questions about agents): the tests compare the screen with it.
# GET /mock/bump?what=rev|last|needs|ask|resolve: one change, pushed like the real hub (the machine's whole session list,
# or one interaction): `rev` a working agent's transcript grew (rev, updated_at: most real pushes), `last` its last line, `needs` a working agent starts needing the user, `ask` a
# question comes for an agent, `resolve` it is answered. Returns what changed. /mock/reset undoes them.
BUMPED = {"asks": [], "n": 0}


def truth():
    agents = [s for s in out_by_machine(all_sessions()) if not s.get("assistant")]
    keys = {s["session_id"]: s["machine_id"] + "/" + s["session_id"] for s in agents}
    return {"states": {keys[s["session_id"]]: s["state"] for s in agents},
            "last": {keys[s["session_id"]]: s.get("last_text") or "" for s in agents},
            # What GET /api/v1/interactions serves (the expanded inbox too), not only INTERACTIONS: the app shows those.
            "asks": sorted(ix["id"] for ix in mock_interactions() if ix["session_id"] in keys),
            "titles": {keys[s["session_id"]]: s.get("title") or "" for s in agents}}


# ---------- a chat as the shared sync cases see it (#1073, spec/fixtures/sync) ----------
# POST /mock/sync/card {"session": "<id>"}: a permission card in that session (an assistant conversation too), sent as
# the hub sends one; answering it tells every app it ended, as the hub does (interaction_resolved).
# GET /mock/sync/truth?session=<id>: what the chat should show: each turn's user message and its answer (the agent's
# last words in it), the session's pending cards and its state.
SYNC_CARDS = {"n": 0}
# MOCK_SYNC_REVS=1: a transcript that grows (a reply, an echoed send) moves its session's updated_at and rev and the list
# says so, as the hub's does: what tells a page that missed the items push to catch up (#3139). Off, the list stays.
MOCK_SYNC_REVS = os.environ.get("MOCK_SYNC_REVS") == "1"


def sync_moved(sid):
    if not MOCK_SYNC_REVS:
        return
    row = next((x for x in SESSIONS + ASSISTANT if x["session_id"] == sid), None)
    if row is not None:
        row.update(updated_at=datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"), rev=(row.get("rev") or 0) + 1)
        push_machine(row["machine_id"])


def sync_card(body):
    sid = (body or {}).get("session")
    s = next((x for x in SESSIONS + ASSISTANT if x["session_id"] == sid), None)
    if s is None:
        raise ValueError("no session %r" % sid)
    SYNC_CARDS["n"] += 1
    n = SYNC_CARDS["n"]
    now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    ix = {"id": "ix_sync_%d" % n, "machine_id": s["machine_id"], "session_id": sid, "session_title": s.get("title") or "",
          "cwd": s.get("cwd") or "", "kind": "permission", "created_at": now, "expires_at": later(hours=1), "tool_name": "Bash",
          "tool_use_id": "call_sync_%d" % n, "tool_input": {"command": "ls step-%d" % n}, "summary": "List step %d" % n}
    with REQUEST_LOCK:
        INTERACTIONS.append(ix)
    for out, _ in list(LIVE):
        try: out({"type": "interaction", "interaction": ix})
        except Exception: pass
    return {"id": ix["id"]}


def sync_resolved(request_id):
    """A card from /mock/sync/card was answered: every app hears it ended."""
    if not request_id.startswith("ix_sync_"):
        return
    for out, _ in list(LIVE):
        try: out({"type": "interaction_resolved", "id": request_id})
        except Exception: pass


def sync_truth(sid):
    messages, answer = [], None
    for x in ITEMS.get(sid, []):
        if x.get("role") == "user" and x.get("kind") == "text" and not x.get("injected") and not x.get("from"):
            messages.append({"from": "user", "text": x.get("text") or "", "state": "shown"})
            answer = None
        elif x.get("role") == "assistant" and x.get("kind") == "text":
            if answer is None:
                messages.append({"from": "agent", "text": x.get("text") or ""})
                answer = len(messages) - 1
            else:
                messages[answer] = {"from": "agent", "text": x.get("text") or ""}
    s = next((x for x in SESSIONS + ASSISTANT if x["session_id"] == sid), None)
    return {"messages": messages, "cards": sorted(ix["id"] for ix in mock_interactions() if ix.get("session_id") == sid),
            "state": (s or {}).get("state")}


def push_machine(mid):
    if not kept(mid): return
    ss = out_by_machine([s for s in all_sessions() if s["machine_id"] == mid])
    for send, _ in list(LIVE):
        try: send({"type": "sessions", "machine_id": mid, "sessions": ss})
        except Exception: pass


def set_session_state(query):
    """A targeted state change, delivered through the same sessions push as the real hub."""
    if set(query) != {"mid", "sid", "state"} or any(len(values) != 1 or not values[0].strip() for values in query.values()):
        return {"error": "Provide exactly one mid, sid and state"}, 400
    mid, sid, state = (query[key][0] for key in ("mid", "sid", "state"))
    if state not in STATUS_OF_STATE:
        return {"error": "state is one of " + ", ".join(STATUS_OF_STATE)}, 400
    session = next((s for s in SESSIONS + ASSISTANT if s["machine_id"] == mid and s["session_id"] == sid), None)
    if session is None:
        return {"error": "Session not found"}, 404
    now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    session.update(state=state, status=STATUS_OF_STATE[state], updated_at=now, state_since=now,
                   rev=(session.get("rev") or 0) + 1)
    push_machine(mid)
    return {"session": stamp_row(with_fold(decorated_session(session)))}, 200


def incoming_message(query):
    """A new reply in any real fixture conversation, even when no chat is subscribed."""
    if set(query) != {"mid", "sid", "text"} or any(len(values) != 1 or not values[0].strip() for values in query.values()):
        return {"error": "Provide exactly one mid, sid and text"}, 400
    mid, sid, text = (query[key][0] for key in ("mid", "sid", "text"))
    session = next((s for s in SESSIONS + ASSISTANT if s["machine_id"] == mid and s["session_id"] == sid), None)
    if session is None:
        return {"error": "Session not found"}, 404
    CHURN_ITEMS.setdefault(sid, list(ITEMS.get(sid, [])))
    now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    item = it("assistant", "text", 0, text=text)
    item["ts"] = now
    previous = ITEMS.get(sid, [])
    before = previous[-1]["seq"] if previous else 0
    ITEMS[sid] = previous + [item]
    session.update(state="unread", status="done", updated_at=now, state_since=now,
                   last_text=text, rev=max((session.get("rev") or 0) + 1, item["seq"]))
    push_machine(mid)
    for send, subscribed in list(LIVE):
        if sid in subscribed:
            try: send({"type": "items", "machine_id": mid, "session_id": sid, "items": [item], **span([item], before)})
            except OSError: pass
    return {"session": stamp_row(with_fold(decorated_session(session))), "item": item}, 200


def quiet_capsule():
    """Remove fixture activity before proving an inactive capsule wakes for an incoming reply."""
    pending = mock_interactions()
    with REQUEST_LOCK:
        INTERACTIONS.clear()
        MOCK_INTERACTIONS.clear()
    now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    for session in SESSIONS + ASSISTANT:
        session.update(state="idle", status="idle", seen_at=now)
    inbox_bulk({"done": True, "items": [{"id": item["id"]} for item in INBOX]})
    for send, _ in list(LIVE):
        try:
            for interaction in pending:
                send({"type": "interaction_resolved", "id": interaction["id"]})
            send({"type": "inbox"})
        except OSError: pass
    for mid in {s["machine_id"] for s in SESSIONS + ASSISTANT}:
        push_machine(mid)
    return {"ok": True}


def bump(what, session=None):
    now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    BUMPED["n"] += 1
    n = BUMPED["n"]
    working = [s for s in SESSIONS if s["state"] == "working" and not s.get("assistant")]
    if what in ("last", "needs", "rev") and working:
        s = working[0] if what != "needs" else working[-1]
        if what == "rev":  # what most of the real hub's pushes are: the transcript grew, nothing shown changed
            s.update(rev=(s.get("rev") or 1000) + 517, updated_at=now)
        elif what == "last":
            s.update(last_text="第 %d 次更新：刚改完一处。" % n, updated_at=now)
        else:
            s.update(state="needs_you", status="blocked", state_since=now, updated_at=now)
        push_machine(s["machine_id"])
        return {"key": s["machine_id"] + "/" + s["session_id"], "state": s["state"], "last": s.get("last_text") or ""}
    if what == "ask":
        s = working[0] if working else SESSIONS[0]
        ix = dict(INTERACTIONS[0], id="ix_bump_%d" % n, machine_id=s["machine_id"], session_id=s["session_id"], created_at=now)
        INTERACTIONS.append(ix)
        BUMPED["asks"].append(ix["id"])
        for send, _ in list(LIVE):
            if not kept(ix["machine_id"]): break  # a machine not served (MOCK_MACHINES_KEEP): nothing pushed
            try: send({"type": "interaction", "interaction": ix})
            except Exception: pass
        return {"ask": ix["id"]}
    if what == "screen":  # a dialog read off a terminal (#751), as the hub sends it: the card, then the agent blocked
        s = next((x for x in SESSIONS if x["session_id"] == session), None) or (working[0] if working else SESSIONS[0])
        question = "你更喜欢哪个颜色？（第 %d 次）" % n
        ix = {"id": "ix_bump_scr_%d" % n, "machine_id": s["machine_id"], "session_id": s["session_id"],
              "session_title": s.get("title") or "", "cwd": s.get("cwd") or "", "kind": "screen", "created_at": now,
              "expires_at": later(hours=24), "screen": " %s\n ❯ 1. 红色\n   2. 蓝色\n" % question,
              "dialog": {"question": question, "rev": "bump%d" % n, "options": [
                  {"key": "1", "label": "红色", "keys": ["1"]}, {"key": "2", "label": "蓝色", "keys": ["2"]}]}}
        INTERACTIONS.append(ix)
        BUMPED["asks"].append(ix["id"])
        BUMPED.setdefault("blocked", {})[ix["id"]] = (s, s["state"], s.get("status"))
        s.update(state="needs_you", status="blocked", state_since=now, updated_at=now)
        for send, _ in list(LIVE):
            try: send({"type": "interaction", "interaction": ix})
            except Exception: pass
        push_machine(s["machine_id"])
        return {"ask": ix["id"], "question": question, "key": s["machine_id"] + "/" + s["session_id"]}
    if what == "resolve" and BUMPED["asks"]:
        ix_id = BUMPED["asks"].pop()
        INTERACTIONS[:] = [x for x in INTERACTIONS if x["id"] != ix_id]
        for send, _ in list(LIVE):
            try: send({"type": "interaction_resolved", "id": ix_id})
            except Exception: pass
        if ix_id in BUMPED.get("blocked", {}):  # answered on the computer: the agent works again
            s, state, status = BUMPED["blocked"].pop(ix_id)
            s.update(state=state, status=status, state_since=now, updated_at=now)
            push_machine(s["machine_id"])
        return {"resolved": ix_id}
    return {"error": "nothing to bump"}


