# MOCK_EXTENSION_PACK=1 (with MOCK_EXTENSIONS): extension packs (#4072, #4122). Example 合集 is installed from the first
# market with four members: Example Notes, Example 助手 and example-gateway installed, example-mail not (it keeps its id).
# Uninstalling it with its members answers 409 partial_uninstall (one member uninstalled, one not, with the hub's reason,
# one not tried) and changes nothing, so a run can repeat; the real hub tries every member, so its "not tried" is
# rarely more than the failed ones. Example 套件 isn't installed: its preview names Example Notes as installed and installs
# Example 日历 together with it.
if PLUGINS_MODE and os.environ.get("MOCK_EXTENSION_PACK") == "1":
    PLUGINS["example-pack"] = {
        "id": "example-pack", "name": "Example 合集", "kind": "extension_pack", "status": "running", "version": "1.0.0",
        "source": "installed", "enabled": True, "description": "Example 的几个扩展，一起装。", "contributes": {}, "publisher": "example",
        "origin": "market:%s/example-pack" % _MARKET_A, "form": {"fields": []}, "config": {}, "secrets": [], "permissions": [],
        "extension_pack": [{"id": "example-notes", "version": ">=1.0.0"}, {"id": "example-helper", "market": "github:example/team-plugins"},
                           {"id": "example-gateway"}, {"id": "example-mail", "version": ">=0.3.0"}]}
    CATALOG += [
        {"market": _MARKET_A, "id": "example-pack", "name": "Example 合集", "version": "1.0.0", "description": "Example 的几个扩展，一起装。",
         "publisher": "example", "tags": ["合集"], "contributes": {}, "permissions": [], "extension_pack": PLUGINS["example-pack"]["extension_pack"]},
        {"market": _MARKET_A, "id": "example-suite", "name": "Example 套件", "version": "1.0.0", "description": "笔记和日历，一起装。",
         "publisher": "example", "tags": ["合集"], "contributes": {}, "permissions": [],
         "extension_pack": [{"id": "example-notes", "version": ">=1.0.0"}, {"id": "example-calendar", "market": MARKETS[_MARKET_A]["spec"]}]},
    ]
_PREVIEWS = {}
_PREVIEW_BODIES = {}


def _ext_predecessor(c):
    """The installed extension catalog item c takes over under its new ID (a rename: its `replaces`, from this market)."""
    old = PLUGINS.get(c.get("replaces", ""))
    return old if old and old.get("origin") == "market:%s/%s" % (c["market"], old["id"]) else None


def _ext_make_preview(c):
    """A preview of catalog item c as the hub answers it (an upgrade's when it is installed); kept for the install."""
    pid = "pv%06d" % (len(_PREVIEWS) + len(_PREVIEW_BODIES) + 1) + uuid.uuid4().hex[:4]
    renamed = None if c["id"] in PLUGINS else _ext_predecessor(c)
    cur = PLUGINS.get(c["id"]) or renamed
    pv = {"preview_id": pid, "manifest": {"id": c["id"], "name": c["name"], "version": c["version"], "description": c["description"]},
          "permissions": c["permissions"], "permissions_digest": "d-" + c["id"], "expires_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() + 600)), "market": c["market"]}
    if cur and cur["source"] == "installed":
        added = [x for x in c["permissions"] if x not in cur.get("permissions", [])]
        pv.update({"upgrade": True, "from": cur.get("version"), "more_permissions": bool(added)})
        if added: pv["added_permissions"] = added
        if renamed:  # the hub's notice leads the warnings (extension.Preview.In)
            pv["rename_from"] = renamed["id"]
            pv["warnings"] = ["此次更新会将扩展 ID 从 %s 更改为 %s，需要明确确认。设置和数据仍属于同一个安装。" % (renamed["id"], c["id"])]  # i18n-ignore: the hub's words
    if c.get("extension_pack"):  # a pack: its members, and the ones not installed yet installed together (the bundle)
        pv["manifest"]["extension_pack"] = c["extension_pack"]
        ids = {m["id"] for m in c["extension_pack"]}
        pv["bundle"] = [{"preview_id": "%s-%s" % (pid, b["id"]), "permissions_digest": "d-" + b["id"], "market": b["market"],
                         "manifest": {"id": b["id"], "name": b["name"], "version": b["version"]}, "permissions": b["permissions"]}
                        for b in CATALOG if b["id"] in ids and b["id"] not in PLUGINS]
    _PREVIEWS[pid] = c
    _PREVIEW_BODIES[pid] = pv
    return pv


def _ext_install(c):
    """Catalog item c installed (or upgraded) from its market; a rename moves the installed one to the new ID."""
    old = None if c["id"] in PLUGINS else _ext_predecessor(c)
    if old:
        PLUGINS[c["id"]] = PLUGINS.pop(old["id"]) | {"id": c["id"]}
    pl = PLUGINS.get(c["id"]) or {"id": c["id"], "source": "installed", "enabled": True, "form": {"fields": []}, "config": {}, "secrets": []}
    pl.update({"name": c["name"], "version": c["version"], "description": c["description"], "status": "running", "kind": next(iter(c["contributes"]), ""),
               "contributes": c["contributes"], "permissions": c["permissions"], "origin": "market:%s/%s" % (c["market"], c["id"]), "publisher": c.get("publisher")})
    pl.pop("upgrade", None); pl.pop("upgrade_note", None)  # the user upgraded it
    PLUGINS[c["id"]] = pl
    return pl


def _catalog_item(c):
    it = dict(c, market_name=MARKETS.get(c["market"], {}).get("name", ""))
    pl = PLUGINS.get(c["id"])
    if not pl and (pl := _ext_predecessor(c)):
        it["rename_from"] = pl["id"]  # the hub checked it came from this market
    if pl:
        it["installed"], it["installed_source"] = pl.get("version", ""), pl["source"]
        it["from_this_market"] = pl.get("origin", "") == "market:%s/%s" % (c["market"], pl["id"])
        it["upgradable"] = pl["source"] == "installed" and pl.get("version", "") < c["version"]
    return {k: v for k, v in it.items() if v not in (None, "", False)} | {"tags": c.get("tags", [])}


# Auto-upgrade (docs/extensions/extensions.md "Auto-upgrade"): example-gateway, from a market at 1.0.0, has 1.1.0 there asking for one more
# host. MOCK_PLUGIN_UPGRADE picks how it stands: needs_permission (default), waiting_idle, skipped, upgraded (the last
# one went in by itself), disabled (switched off: auto-upgrade paused, its own switch kept), rolled_back_by_user (the
# user rolled back from 1.1.0 by hand: skipped as the user's, #1826), renamed (the market lists 1.1.0 under a new ID,
# example-gateway-next, that `replaces` it: waits for the owner to confirm the ID change, #2511), none.
AUTO_UPGRADE = {"auto": True}
# A market plugin's upgrade while it is on, put back when it is switched on again (_auto_upgrade_paused).
_UPGRADE_WHILE_ON = {}


def _auto_upgrade_paused(pl):
    """A market plugin is not upgraded while switched off or once its market is removed, as the hub says (#1895): the
    market it upgrades from, auto_upgrade_paused, and its newer version "off" while switched off or none while the market
    is gone (its own switch stays); switched on again, or the market added back, both are as before."""
    if pl.get("auto_upgrade") is None:
        return
    m = re.match(r"market:([^/]+)/", pl.get("origin", ""))
    pl["market"] = m.group(1) if m else None
    removed = bool(pl["market"]) and pl["market"] not in MARKETS
    pl["auto_upgrade_paused"] = "market_removed" if removed else None if pl["enabled"] else "disabled"
    up = pl.get("upgrade")
    if up and pl["id"] not in _UPGRADE_WHILE_ON and (removed or not pl["enabled"]):
        _UPGRADE_WHILE_ON[pl["id"]] = up
    kept = _UPGRADE_WHILE_ON.get(pl["id"])
    if removed:  # nothing is offered from a market the hub no longer reads
        pl["upgrade"] = None
    elif not pl["enabled"]:
        if kept:
            pl["upgrade"] = {k: v for k, v in kept.items() if k != "added_permissions"} | {
                "state": "off", "detail": "扩展已关闭，自动升级暂停；重新打开后恢复你原来的设置"}  # i18n-ignore: the hub's words
    elif kept:
        pl["upgrade"] = _UPGRADE_WHILE_ON.pop(pl["id"])


def _gateway_upgrade(state):
    pl = PLUGINS["example-gateway"]
    pl["auto_upgrade"] = True
    up = {"id": "example-gateway", "name": pl["name"], "market": _MARKET_A, "from": "1.0.0", "to": "1.1.0", "state": state}
    at = lambda hours: time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() - hours * 3600))
    if state == "needs_permission":
        up["added_permissions"] = [{"key": "network", "title": "访问更多网络", "detail": "status.example.com"}]  # as the hub's plugin.Added
        pl["upgrade_note"] = {"kind": "needs_permission", "from": "1.0.0", "to": "1.1.0", "detail": "要多一项权限：访问更多网络（status.example.com）", "at": at(2)}
    elif state == "waiting_idle":
        up["detail"] = "插件正在用"
    elif state == "skipped":
        pl["upgrade_note"] = {"kind": "rolled_back", "from": "1.0.0", "to": "1.1.0", "detail": "exited with status 3", "at": at(5)}
    elif state == "renamed":
        nxt = next(c for c in CATALOG if c["id"] == "example-gateway")
        nxt.update({"id": "example-gateway-next", "replaces": "example-gateway", "permissions": pl["permissions"]})
        up.update({"state": "needs_permission", "rename_from": "example-gateway", "rename_to": nxt["id"],
                   "detail": "此次更新会将扩展 ID 从 example-gateway 更改为 example-gateway-next，需要明确确认。设置和数据仍属于同一个安装。"})  # i18n-ignore: the hub's words
    elif state == "rolled_back_by_user":  # no note: the version it was upgraded to is not installed any more
        up["state"], up["skipped_by"] = "skipped", "user"
        up["detail"] = "你从这个版本回滚过，所以不会自动装它；要装就手动更新"  # i18n-ignore: the hub's words
    if state in ("needs_permission", "waiting_idle", "skipped", "disabled", "rolled_back_by_user", "renamed"):
        pl["upgrade"] = up
    elif state == "upgraded":
        pl["upgrade_note"] = {"kind": "upgraded", "from": "0.9.0", "to": "1.0.0", "at": at(3)}
    if state == "disabled":
        up["state"] = "available"
        pl["enabled"], pl["status"] = False, "disabled"
    _auto_upgrade_paused(pl)


_gateway_upgrade(os.environ.get("MOCK_PLUGIN_UPGRADE", "needs_permission"))
# As it starts, for /mock/reset: a test that installs the update (ExtensionMarketTests, #2988) leaves the next one 1.0.0.
_GATEWAY_START = copy.deepcopy(PLUGINS["example-gateway"])


def upgrades_route(handler, p, req):
    """The auto-upgrade's switches and list (GET/PUT /api/v1/plugins/-/upgrades, PUT …/{id}/-/auto-upgrade)."""
    method, parts = handler.command, p.split("/")
    if p == "/api/v1/plugins/-/upgrades" and method in ("GET", "PUT"):
        if method == "PUT":
            AUTO_UPGRADE["auto"] = bool(req.get("auto"))
        handler.send_json({"auto": AUTO_UPGRADE["auto"], "upgrades": [pl["upgrade"] for pl in PLUGINS.values() if pl.get("upgrade")],
                           "off": [pl["id"] for pl in PLUGINS.values() if pl.get("auto_upgrade") is False],
                           "last": {pl["id"]: pl["upgrade_note"] for pl in PLUGINS.values() if pl.get("upgrade_note")}})
        return True
    if method == "PUT" and len(parts) == 7 and parts[3] == "plugins" and parts[5] == "-" and parts[6] == "auto-upgrade" and parts[4] in PLUGINS:
        pl = PLUGINS[parts[4]]
        if not pl.get("origin", "").startswith("market:"):
            handler.send_json({"error": "只有从插件市场装的插件会自动升级", "code": "not_from_market"}, 400); return True
        pl["auto_upgrade"] = bool(req.get("auto"))
        up = pl.get("upgrade")
        if up and up["state"] in ("available", "waiting_idle", "off"):
            up["state"] = "waiting_idle" if pl["auto_upgrade"] else "off"
            up.pop("detail", None)
        handler.send_json({k: v for k, v in _plugin_needs(pl).items() if v is not None}); return True
    return False


# ---------- MOCK_EXTENSIONS: places outside the app (docs/extensions/extensions.md "System-level placements") ----------
# example-gateway draws a widget "today" (small / medium / Lock Screen and watch face complications) that opens its
# nav_page "usage", and has two shortcuts. The hub's new paths only (these came after the rename). A sample of an
# extension's notification with buttons is scripts/mock/apns/extension-notification.apns:
#   xcrun simctl push <udid> <bundle id> scripts/mock/apns/extension-notification.apns
_WIDGETS = [{"extension": "example-gateway", "extension_name": "Example 网关面板", "id": "today", "title": "今天的用量",
             "families": ["small", "medium", "accessory_circular", "accessory_rectangular", "accessory_inline"], "refresh_minutes": 30, "opens": "usage"}]
_SHORTCUTS = [{"extension": "example-gateway", "extension_name": "Example 网关面板", "id": "usage_today", "title": "今天用了多少",
               "description": "说出今天的用量", "ui": "usage"},
              {"extension": "example-gateway", "extension_name": "Example 网关面板", "id": "set_budget", "title": "设预算", "params": [
                  {"name": "amount", "title": "金额", "kind": "number", "required": True},
                  {"name": "period", "title": "周期", "kind": "choice", "choices": [{"value": "day", "title": "每天"}, {"value": "month", "title": "每月"}]}]}]
DEVICE_WIDGETS = {}


def _widget_view(family):
    """The widget "today" at a family, as the hub holds it to what the family draws."""
    if family == "accessory_inline":
        return {"sections": [{"items": [{"type": "text", "text": "今天 1.2M tokens"}]}]}
    if family in ("accessory_circular", "accessory_rectangular"):
        return {"sections": [{"items": [{"type": "progress", "label": "今天的预算", "ratio": 0.62, "detail": "¥3.10 / ¥5", "tone": "caution"}]}]}
    stats = [{"label": "费用", "value": "¥3.10"}, {"label": "7 天", "value": "8.4M"}]
    items = [{"type": "metric", "label": "今天", "value": "1.2M", "detail": "+12% 比昨天", "tone": "caution"},
             {"type": "stat_grid", "stats": stats if family == "medium" else stats[:1]}]
    if family == "medium":
        items.append({"type": "chart", "kind": "bar", "unit": "tokens", "series": [{"points": [
            {"label": d, "value": v} for d, v in [("11-01", 0.9e6), ("11-02", 1.4e6), ("11-03", 0.7e6), ("11-04", 1.1e6), ("11-05", 1.2e6)]]}]})
    return {"sections": [{"items": items}]}


def system_route(handler, p, req):
    """MOCK_EXTENSIONS: widgets and shortcuts under /api/v1/extensions/…, and the widgets each device has. False otherwise."""
    method = handler.command
    on = "example-gateway" in PLUGINS and PLUGINS["example-gateway"]["enabled"]
    parts = p.split("/")
    if p == "/api/v1/extensions/-/widgets" and method == "GET":
        handler.send_json({"widgets": _WIDGETS if on else []}); return True
    if p == "/api/v1/extensions/-/shortcuts" and method == "GET":
        handler.send_json({"shortcuts": _SHORTCUTS if on else []}); return True
    if len(parts) == 8 and parts[3] == "extensions" and parts[5] == "-" and parts[6] == "widget" and method == "POST":
        family = (req.get("context") or {}).get("size", "")
        if not on or parts[4] != "example-gateway" or parts[7] != "today":
            handler.send_json({"error": "no such extension", "code": "not_found"}, 404); return True
        if family not in _WIDGETS[0]["families"]:
            handler.send_json({"error": "这个小组件不画这个尺寸", "code": "bad_request"}, 400); return True
        expires = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() + 30 * 60))
        handler.send_json({"view": _widget_view(family), "expires_at": expires}); return True
    if len(parts) == 8 and parts[3] == "extensions" and parts[5] == "-" and parts[6] == "shortcut" and method == "POST":
        sc = next((s for s in _SHORTCUTS if s["id"] == parts[7]), None) if on and parts[4] == "example-gateway" else None
        if not sc:
            handler.send_json({"error": "这个扩展没有这个快捷指令", "code": "not_found"}, 404); return True
        values = req.get("values") or {}
        if sc["id"] == "set_budget":
            if not values.get("amount"):
                handler.send_json({"error": "快捷指令的参数不对：缺 金额", "code": "bad_request"}, 400); return True
            period = {"day": "每天", "month": "每月"}.get(values.get("period", "day"), "每天")
            handler.send_json({"text": "预算设好了：%s ¥%s。" % (period, values["amount"])}); return True
        handler.send_json({"text": "今天用了 1.2M tokens，约 ¥3.10。",
                           "view": {"sections": [{"items": [{"type": "metric", "label": "今天", "value": "1.2M", "detail": "约 ¥3.10"}]}]}}); return True
    if len(parts) == 6 and parts[3] == "devices" and parts[5] == "widgets" and method == "PUT":
        DEVICE_WIDGETS[parts[4]] = req.get("widgets") or []
        handler.send_json({"widgets": DEVICE_WIDGETS[parts[4]]}); return True
    return False


# ---------- MOCK_EXTENSION_OPS: installs in steps (docs/protocol/protocol.md "Extension install, upgrade and uninstall progress", #3277, #3307) ----------
# MOCK_EXTENSION_OPS=1 (with MOCK_EXTENSIONS): the hub says extension_operations. A preview asked for with async answers
# 202 {"operation"} at once and goes through download (in four parts) → verify → unpack → check, then waits at consent
# (needs_consent, GET …/-/operations/{id} carries the preview); the install or upgrade agreed to with async goes on with
# the same operation (install → start; nodes skipped). A removal, async or not, is recorded as an operation too.
# =fail: the first install or upgrade of each extension stops at start (retryable: …/retry starts a new operation, its
# download from the cache and the consent already given, so it goes on by itself); the first removal stops at remove.
# =stall (#3692): the first preview of each extension stops half-way through its download, three steps later, with
# download_stalled (retryable: …/retry downloads it again and waits for consent).
# MOCK_EXTENSION_OPS_STEP=<seconds> per step (default 0.6).
EXT_OPS = os.environ.get("MOCK_EXTENSION_OPS", "") if os.environ.get("MOCK_EXTENSIONS") else ""
EXT_OPS_STEP = float(os.environ.get("MOCK_EXTENSION_OPS_STEP", "0.6"))
EXT_OPERATIONS = {}
EXT_OP_JOBS = {}  # what each operation does: {"retry": fn, "preview": id, "consented": digest}
_EXT_FAILED = set()  # (kind, extension) that failed once (MOCK_EXTENSION_OPS=fail)
_EXT_OPS_LOCK = threading.RLock()
_INSTALL_STEPS = ["download", "verify", "unpack", "check", "consent", "install", "start", "nodes"]
_UNINSTALL_STEPS = ["stop", "remove", "nodes"]
_PACKAGE_BYTES = 4 * 1024 * 1024
# MOCK_EXTENSION_INSTALL_DELAY=<seconds>: a hub without operations takes that long to answer an install or a removal.
EXT_INSTALL_DELAY = float(os.environ.get("MOCK_EXTENSION_INSTALL_DELAY", "0"))
# MOCK_EXTENSION_PREVIEW_DELAY=<seconds>: a synchronous preview takes that long to answer (a slow download, #3692).
EXT_PREVIEW_DELAY = float(os.environ.get("MOCK_EXTENSION_PREVIEW_DELAY", "0"))


def _ext_now():
    return time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime()) + ".%03dZ" % (int(time.time() * 1000) % 1000)


def _ext_op_view(op):
    return {k: v for k, v in copy.deepcopy(op).items() if v is not None}


def _ext_op_push(op):
    msg = {"type": "extension_operation", "operation": _ext_op_view(op)}
    for send, _ in list(LIVE):
        try: send(msg)
        except Exception: pass


def _ext_op_new(kind, ext, name, version=None, frm=None, market=None):
    steps = _UNINSTALL_STEPS if kind == "uninstall" else _INSTALL_STEPS
    op = {"id": "op_%s" % uuid.uuid4().hex[:10], "kind": kind, "extension": ext, "name": name, "actor": "iPhone",
          "state": "running", "step": steps[0], "steps": [{"id": i, "state": "pending"} for i in steps],
          "retryable": False, "started_at": _ext_now(), "updated_at": _ext_now(), "version": version, "from": frm, "market": market}
    with _EXT_OPS_LOCK:
        EXT_OPERATIONS[op["id"]] = op
        EXT_OP_JOBS[op["id"]] = {}
    _ext_op_push(op)
    return op


def _ext_step(op, sid, state, **extra):
    with _EXT_OPS_LOCK:
        for st in op["steps"]:
            if st["id"] == sid:
                st["state"] = state
                st.update(extra)
        if state == "running": op["step"] = sid
        op["updated_at"] = _ext_now()
    _ext_op_push(op)


def _ext_fails(op, sid):
    """MOCK_EXTENSION_OPS=fail: the first install / upgrade fails at start, the first removal at remove."""
    want = "remove" if op["kind"] == "uninstall" else "start"
    key = (op["kind"], op["extension"])
    if EXT_OPS != "fail" or sid != want or key in _EXT_FAILED: return False
    _EXT_FAILED.add(key)
    return True


def _ext_fail(op, sid, retry):
    why, code = ("扩展启动后 5 秒内没有起来（exit status 1）", "start_failed") if sid == "start" else ("删不掉扩展目录：目录被占用（resource busy）", "uninstall_failed")
    with _EXT_OPS_LOCK:
        for st in op["steps"]:
            if st["id"] == sid: st["state"] = "failed"
        op.update(state="failed", step=sid, error=why, error_code=code, retryable=True, updated_at=_ext_now(), ended_at=_ext_now())
        EXT_OP_JOBS[op["id"]]["retry"] = retry
    _ext_op_push(op)


def _ext_preview_run(op, c, cached=False):
    """download → verify → unpack → check, then waits for consent (or goes on, the same permissions agreed to)."""
    if cached:
        _ext_step(op, "download", "done", cached=True)
    else:
        _ext_step(op, "download", "running", bytes=0, total=_PACKAGE_BYTES)
        for part in range(1, 5):
            time.sleep(EXT_OPS_STEP)
            if op["state"] == "canceled": return
            _ext_step(op, "download", "running", bytes=_PACKAGE_BYTES * part // 4, total=_PACKAGE_BYTES)
            if part == 2 and EXT_OPS == "stall" and ("preview", c["id"]) not in _EXT_FAILED:
                _EXT_FAILED.add(("preview", c["id"]))
                time.sleep(EXT_OPS_STEP * 3)
                with _EXT_OPS_LOCK:
                    for st in op["steps"]:
                        if st["id"] == "download": st["state"] = "failed"
                    op.update(state="failed", step="download", error="包下载停滞，请重试。", error_code="download_stalled",  # i18n-ignore: the hub's words
                              retryable=True, updated_at=_ext_now(), ended_at=_ext_now())

                    def retry(c=c, was=op):
                        nxt = _ext_op_new(was["kind"], c["id"], c["name"], version=c["version"], frm=was.get("from"), market=c["market"])
                        threading.Thread(target=_ext_preview_run, args=(nxt, c), daemon=True).start()
                        return nxt
                    EXT_OP_JOBS[op["id"]]["retry"] = retry
                _ext_op_push(op)
                return
        _ext_step(op, "download", "done")
    for sid in ("verify", "unpack", "check"):
        _ext_step(op, sid, "running"); time.sleep(EXT_OPS_STEP); _ext_step(op, sid, "done")
    if op["state"] == "canceled": return
    pv = _ext_make_preview(c)
    with _EXT_OPS_LOCK:
        EXT_OP_JOBS[op["id"]]["preview"] = pv["preview_id"]
        consented = EXT_OP_JOBS[op["id"]].get("consented")
    if consented == pv["permissions_digest"]:
        _ext_step(op, "consent", "done")
        _ext_install_run(op, c)
        return
    with _EXT_OPS_LOCK:
        op.update(state="needs_consent", preview_id=pv["preview_id"])
    _ext_step(op, "consent", "running")


def _ext_install_run(op, c):
    """install → start (nodes skipped): what was agreed to goes in."""
    with _EXT_OPS_LOCK:
        op.update(state="running"); op.pop("preview_id", None)
        EXT_OP_JOBS[op["id"]]["consented"] = "d-" + c["id"]
    _ext_step(op, "consent", "done")
    for sid in ("install", "start"):
        _ext_step(op, sid, "running"); time.sleep(EXT_OPS_STEP)
        if _ext_fails(op, sid):
            def retry(c=c, was=op):
                nxt = _ext_op_new(was["kind"], c["id"], c["name"], version=c["version"], frm=was.get("from"), market=c["market"])
                EXT_OP_JOBS[nxt["id"]]["consented"] = EXT_OP_JOBS[was["id"]].get("consented")
                threading.Thread(target=_ext_preview_run, args=(nxt, c, True), daemon=True).start()
                return nxt
            _ext_fail(op, sid, retry)
            return
        if sid == "install": _ext_install(c)
        _ext_step(op, sid, "done")
    _ext_step(op, "nodes", "skipped")
    with _EXT_OPS_LOCK:
        op.update(state="succeeded", step=None, updated_at=_ext_now(), ended_at=_ext_now())
    _ext_op_push(op)


def _ext_uninstall_run(op, ext):
    """stop → remove (nodes skipped). True: removed."""
    _ext_step(op, "stop", "running"); time.sleep(EXT_OPS_STEP); _ext_step(op, "stop", "done")
    _ext_step(op, "remove", "running"); time.sleep(EXT_OPS_STEP)
    if _ext_fails(op, "remove"):
        def retry(ext=ext, name=op["name"]):
            nxt = _ext_op_new("uninstall", ext, name)
            threading.Thread(target=_ext_uninstall_run, args=(nxt, ext), daemon=True).start()
            return nxt
        _ext_fail(op, "remove", retry)
        return False
    PLUGINS.pop(ext, None)
    _ext_step(op, "remove", "done")
    _ext_step(op, "nodes", "skipped")
    with _EXT_OPS_LOCK:
        op.update(state="succeeded", step=None, updated_at=_ext_now(), ended_at=_ext_now())
    _ext_op_push(op)
    return True


def _ext_ops_route(handler, p, method):
    """GET …/-/operations, GET / DELETE …/-/operations/{id}, POST …/-/operations/{id}/retry."""
    if not EXT_OPS or not p.startswith("/api/v1/plugins/-/operations"): return False
    parts = [x for x in p.split("/")[6:] if x]  # after /api/v1/plugins/-/operations
    with _EXT_OPS_LOCK:
        if not parts and method == "GET":
            ops = sorted(EXT_OPERATIONS.values(), key=lambda o: o["started_at"], reverse=True)
            handler.send_json({"operations": [_ext_op_view(o) for o in ops]}); return True
        op = EXT_OPERATIONS.get(parts[0]) if parts else None
        if not op:
            handler.send_json({"error": "没有这次操作，或者已经过期了", "code": "not_found"}, 404); return True
        if len(parts) == 1 and method == "GET":
            v = _ext_op_view(op)
            if op["state"] == "needs_consent" and op.get("preview_id") in _PREVIEW_BODIES:
                v["preview"] = _PREVIEW_BODIES[op["preview_id"]]
            handler.send_json(v); return True
        if len(parts) == 1 and method == "DELETE":
            consent = next((st for st in op["steps"] if st["id"] == "consent"), None)
            if op["state"] == "needs_consent" or (op["state"] == "running" and consent and consent["state"] == "pending"):
                _PREVIEWS.pop(op.pop("preview_id", "") or "", None)
                op.update(state="canceled", updated_at=_ext_now(), ended_at=_ext_now())
                _ext_op_push(op)
            elif op["state"] == "running":
                handler.send_json({"error": "已经开始安装了，不能取消", "code": "cannot_cancel"}, 409); return True
            else:
                EXT_OPERATIONS.pop(op["id"], None)
            handler.send_response(204); handler.end_headers(); return True
        if parts[1:] == ["retry"] and method == "POST":
            if op["state"] != "failed":
                handler.send_json({"error": "这次操作没有失败", "code": "not_failed"}, 409); return True
            retry = EXT_OP_JOBS.get(op["id"], {}).get("retry")
            if not retry:
                handler.send_json({"error": "这次操作不能重试", "code": "not_retryable"}, 409); return True
    nxt = retry()
    handler.send_json({"operation": _ext_op_view(nxt)}, 202); return True


def markets_route(handler, p, body):
    """MOCK_EXTENSIONS: the markets, the catalog, installing from it, and the plugins' declarative UI. False otherwise."""
    if not PLUGINS_MODE: return False
    method = handler.command
    q = {k: v[0] for k, v in parse_qs(urlparse(handler.path).query).items()}
    req = json.loads(body or b"{}") if body else {}
    if upgrades_route(handler, p, req): return True
    if _ext_ops_route(handler, p, method): return True
    if p == "/api/v1/plugins/-/markets" and method == "GET":
        handler.send_json({"markets": list(MARKETS.values())}); return True
    if p == "/api/v1/plugins/-/markets" and method == "POST":
        spec = (req.get("spec") or "").strip()
        if not spec.startswith(("https://", "github:", "git:", "git@")):
            handler.send_json({"error": "市场的地址是 https://…、github:owner/repo 或 git:<地址>", "code": "market_failed"}, 400); return True
        if "private" in spec and not req.get("token"):
            handler.send_json({"error": "读不到 %s：找不到（404）：地址不对，或者是私有的，要填 token" % spec, "code": "market_failed"}, 400); return True
        # The same address gives the same id, as the hub's id is a hash of it: a removed market added again is back (#1895).
        back = _REMOVED_MARKETS.pop(spec, None)
        mid = back["id"] if back else "%010x" % (abs(hash(spec)) % (16 ** 10))
        MARKETS[mid] = back or {"id": mid, "spec": spec, "name": spec.split("/")[-1] or spec, "has_token": bool(req.get("token")), "plugins": 0,
                                "warnings": [], "fetched_at": "2026-11-04T07:00:00Z", "added_at": "2026-11-04T07:00:00Z"}
        for pl in PLUGINS.values():
            _auto_upgrade_paused(pl)
        handler.send_json(MARKETS[mid]); return True
    parts = p.split("/")
    if p.startswith("/api/v1/plugins/-/markets/") and len(parts) >= 7 and parts[6] in MARKETS:
        mid = parts[6]
        if method == "DELETE" and len(parts) == 7:
            gone = MARKETS.pop(mid)
            _REMOVED_MARKETS[gone["spec"]] = gone
            for pl in PLUGINS.values():
                _auto_upgrade_paused(pl)
            handler.send_json({"ok": True}); return True
        if method == "POST" and parts[7:] == ["refresh"]:
            MARKETS[mid]["fetched_at"] = "2026-11-04T07:05:00Z"; handler.send_json(MARKETS[mid]); return True
        if method == "PUT" and parts[7:] == ["token"]:
            MARKETS[mid]["has_token"] = bool(req.get("token")); handler.send_json(MARKETS[mid]); return True
    if p == "/api/v1/plugins/-/catalog" and method == "GET":
        words, market = q.get("q", "").lower(), q.get("market", "")
        items = [_catalog_item(c) for c in CATALOG if c["market"] in MARKETS and (not market or c["market"] == market)
                 and (not words or words in "\n".join([c["id"], c["name"], c["description"], c.get("publisher", "")] + c.get("tags", [])).lower())]
        handler.send_json({"markets": list(MARKETS.values()), "plugins": items, "platform": "linux-amd64"}); return True
    if p == "/api/v1/plugins/-/catalog/preview" and method == "POST":
        same = [c for c in CATALOG if c["market"] == req.get("market")]
        # An installed extension's old ID previews its successor, as the hub does (#2511).
        c = next((c for c in same if c["id"] == req.get("plugin")), None) or next((c for c in same if c.get("replaces") == req.get("plugin")), None)
        if not c or c.get("problem"):
            handler.send_json({"error": (c or {}).get("problem") or "这个市场里没有插件 %s" % req.get("plugin"), "code": "invalid_plugin"}, 400); return True
        pv = _ext_make_preview(c)
        pid = pv["preview_id"]
        _PREVIEWS[pid] = c
        _PREVIEW_BODIES[pid] = pv
        if EXT_OPS and req.get("async"):
            cur = PLUGINS.get(c["id"])
            upgrade = bool(cur and cur["source"] == "installed")
            op = _ext_op_new("upgrade" if upgrade else "install", c["id"], c["name"], version=c["version"],
                             frm=cur.get("version") if upgrade else None, market=c["market"])
            _PREVIEWS.pop(pid, None); _PREVIEW_BODIES.pop(pid, None)  # the operation makes its own
            threading.Thread(target=_ext_preview_run, args=(op, c), daemon=True).start()
            handler.send_json({"operation": _ext_op_view(op)}, 202); return True
        time.sleep(EXT_PREVIEW_DELAY)
        handler.send_json(pv); return True
    if p in ("/api/v1/plugins/-/install",) or (p.startswith("/api/v1/plugins/") and p.endswith("/-/upgrade")):
        c = _PREVIEWS.pop(req.get("preview_id", ""), None)
        if not c:
            handler.send_json({"error": "预览过期了，重新预览一次", "code": "install_failed"}, 400); return True
        if EXT_OPS:
            # The operation the preview came from goes on (an older client's synchronous install is recorded too).
            op = next((o for o in EXT_OPERATIONS.values() if EXT_OP_JOBS.get(o["id"], {}).get("preview") == req.get("preview_id")), None)
            if op and op["state"] == "needs_consent":
                if req.get("async"):
                    threading.Thread(target=_ext_install_run, args=(op, c), daemon=True).start()
                    handler.send_json({"operation": _ext_op_view(op)}, 202); return True
                _ext_install_run(op, c)
                if op["state"] == "failed":
                    handler.send_json({"error": op["error"], "code": op["error_code"]}, 500); return True
                handler.send_json({k: v for k, v in _plugin_needs(PLUGINS[c["id"]]).items() if v is not None} | {"operation_id": op["id"]}); return True
        time.sleep(EXT_INSTALL_DELAY)
        handler.send_json({k: v for k, v in _plugin_needs(_ext_install(c)).items() if v is not None}); return True
    if method == "DELETE" and len(parts) >= 6 and parts[3] == "plugins" and parts[5] == "-" and parts[6:] in ([], [""]) and parts[4] in PLUGINS:
        if not PLUGINS[parts[4]].get("origin", "").startswith("market:"):
            handler.send_json({"error": "这个扩展只能在 hub 机器上（personad extension …）或 hub 的管理界面里装、升级和卸载；手机上只能装扩展市场里的",
                               "code": "this_machine_only"}, 403); return True
        if parts[4] == "example-pack" and q.get("members") == "1":  # MOCK_EXTENSION_PACK: stopped part way, nothing changed
            handler.send_json({"ok": False, "code": "partial_uninstall", "error": "卸载未完成。已卸载成员：example-notes；未卸载：example-helper。合集仍保留，可以重试。",  # i18n-ignore: the hub's words
                               "removed_members": ["example-notes"], "failed_members": [{"id": "example-helper", "error": "扩展还在运行，停不下来"}],  # i18n-ignore: the hub's words
                               "remaining_members": ["example-helper", "example-gateway"]}, 409); return True
        if EXT_OPS:
            # Recorded as an operation either way; async answers at once, else when it is done (as the hub does).
            ext = parts[4]
            op = _ext_op_new("uninstall", ext, PLUGINS[ext].get("name", ext))
            if q.get("async"):
                threading.Thread(target=_ext_uninstall_run, args=(op, ext), daemon=True).start()
                handler.send_json({"operation": _ext_op_view(op)}, 202); return True
            if not _ext_uninstall_run(op, ext):
                handler.send_json({"error": op["error"], "code": op["error_code"]}, 500); return True
            handler.send_json({"ok": True}); return True
        time.sleep(EXT_INSTALL_DELAY)
        PLUGINS.pop(parts[4]); handler.send_json({"ok": True}); return True
    if p == "/api/v1/plugins/-/ui" and method == "GET":
        placement = q.get("placement", "")
        ui = []
        if "example-gateway" in PLUGINS and PLUGINS["example-gateway"]["enabled"]:
            if placement == "capsule_card":
                ui = [{"plugin": "example-gateway", "plugin_name": "Example 网关面板", "id": "capsule", "title": "胶囊扩展",
                       "placement": "capsule_card", "size": "compact", "opens": "usage"}]
            elif placement != "launcher_section":
                ui = [u for u in PLUGINS["example-gateway"]["ui"] + _SLOT_UI if placement in ("", u["placement"])]
            elif q.get("launcher"):
                # "elsewhere" has no hosts (listed on every launcher) and always says the launcher is not its gateway:
                # clients hide it (docs/extensions/extensions.md "Declarative UI", #1339)
                ui = [{"plugin": "example-gateway", "id": "panel", "title": "Example 网关", "placement": "launcher_section"},
                      {"plugin": "example-gateway", "id": "elsewhere", "title": "别家网关", "placement": "launcher_section"}]
        ui += [u for u in INBOX_ITEM_UI if placement in ("", u["placement"])]
        if os.environ.get("MOCK_EXTENSION_SHOWCASE") == "1" and placement in ("", "nav_page"):
            from pathlib import Path
            snapshots = Path(__file__).resolve().parents[2] / "schema/extension/examples/showcase"
            ui += [{"plugin": "showcase", "plugin_name": "Component showcase", "id": file.stem,
                    "title": file.stem, "placement": "nav_page", "size": "full", "icon": "list"}
                   for file in sorted(snapshots.glob("*.json"))]
        handler.send_json({"ui": ui}); return True
    if len(parts) == 8 and parts[4] == "example-chat" and parts[5:7] == ["-", "ui"] and method == "POST" and INBOX_ITEM_UI:
        code, out = inbox_item_ui(parts[7], req)
        handler.send_json(out, code); return True
    if len(parts) == 8 and parts[3] == "plugins" and parts[5] == "-" and parts[6] == "ui" and method == "POST":
        if parts[4] != "example-gateway" or "example-gateway" not in PLUGINS:
            handler.send_json({"error": "no such plugin", "code": "not_found"}, 404); return True
        launcher = (req.get("context") or {}).get("launcher", "")
        if parts[7] == "elsewhere":
            handler.send_json({"error": "this launcher's gateway is not the plugin's", "code": "unsupported"}, 404); return True
        ctx = req.get("context") or {}
        if parts[7] == "capsule":
            action = req.get("action")
            if action and action != "capsule:refresh":
                handler.send_json({"error": "no such capsule action", "code": "not_found"}, 404); return True
            if action:
                _UI_STATE["capsule_refreshed"] += 1
            handler.send_json({"view": _capsule_view(), **({"toast": "摘要已刷新"} if action else {})}); return True
        if parts[7] in ("usage", "today", "gpu"):
            if parts[7] == "gpu" and not ctx.get("machine"):
                handler.send_json({"error": "没有这台机器", "code": "not_found"}, 404); return True
            machine = next((m for m in MACHINES if ctx.get("machine") in (m["id"], m.get("name"))), {"name": ctx.get("machine")})
            state = req.get("state") or "range=7d"
            if (req.get("action") or "").startswith("range:"):
                state = "range=" + req["action"].split(":", 1)[1]
            elif req.get("action") == "range" and (req.get("values") or {}).get("range"):
                state = "range=" + req["values"]["range"]  # the segmented (UI version 2)
            view = _slot_view(parts[7], state.split("=", 1)[1], machine)
            if parts[7] == "usage" and (ctx.get("ui_version") or 1) >= 2:
                # an app that draws UI version 2 gets the segmented instead of a row of buttons
                rng = state.split("=", 1)[1]
                view["sections"][0] = {"items": [{"type": "segmented", "name": "range", "value": rng, "action": {"id": "range"},
                                                  "choices": [{"value": r, "title": t} for r, t in [("1d", "今天"), ("7d", "7 天"), ("30d", "30 天"), ("90d", "90 天")]]}]}
            if (ctx.get("ui_version") or 1) < 2:
                view = _fit_v1(view)
            handler.send_json({"view": view}); return True
        if parts[7] == "notes":
            v3 = ctx.get("ui_version") or 1
            out = _notes_action(req.get("state", ""), req["action"], req.get("values")) if req.get("action") else {"view": _notes_view(req.get("state", ""))}
            if v3 < 3:
                out.pop("pop", None); out.pop("push", None)
                if out.get("view"): out["view"] = _fit_v3(out["view"], v3)
            handler.send_json(out); return True
        if req.get("action"):
            handler.send_json(_ui_action(parts[7], req["action"], req.get("values"))); return True
        handler.send_json({"view": _ui_view(parts[7], launcher)}); return True
    return False

# MOCK_FILE_OPS=1 (#4883, the hub / node side is #4858): uploads into a folder (dest=dir) and rename / move / trash /
# restore, as #4858's interface says: only home is writable, not ~/.persona, ~/.persona, ~/Library; a name already
# there is 409 `exists` unless conflict=replace|keep; the trash keeps what it took to put it back.
FILE_OPS = bool(os.environ.get("MOCK_FILE_OPS"))
FILE_TRASH = {}  # trash id -> (tree key, {key: value} of everything moved)
FILE_OPS_LOG = []  # what the browser asked (a test reads it from the module)
FILE_OPERATIONS = {}  # operation id -> synthetic copy / zip progress for the transfer bars
FILE_OPERATION_DELAY = float(os.environ.get("MOCK_FILE_OP_DELAY", "0"))
_features_without_file_ops = features


def features():
    return (_features_without_file_ops() + (["upload_dir", "file_edit"] if FILE_OPS else [])
            + (["file_info"] if os.environ.get("MOCK_FILE_LINKS") else [])
            + (["file_mkdir", "file_write", "file_zip", "file_copy", "file_chmod", "pane_cwd"] if FILE_OPS else []))


def file_ops_key(mid, path, cwd):
    """(home, tree key without the trailing /, error (json, status) or None) of a path to change."""
    home, ab = mock_abs(mid, path, cwd)
    if ab != home and not ab.startswith(home + "/"):
        return home, None, ({"error": "只有个人文件夹以内可以写", "code": "read_only"}, 409)
    rel = ab[len(home) + 1:] if ab != home else ""
    if rel.split("/")[0] in (".persona", "Library") or rel == "":
        return home, None, ({"error": "这个位置不能写", "code": "read_only"}, 409)
    return home, rel, None


def file_ops_free(dir_rel, name, conflict, reserved=()):
    """The name `name` takes in folder `dir_rel` (a tree key ending in / or ""): itself, or "name 2.extension" to keep both;
    None when it is taken and nothing was said."""
    taken = lambda n: dir_rel + n in MOCK_TREE or dir_rel + n + "/" in MOCK_TREE or dir_rel + n in reserved or dir_rel + n + "/" in reserved
    if not taken(name) or conflict == "replace": return name
    if conflict != "keep": return None
    stem, dot, ext = name.rpartition(".")
    if not stem: stem, dot, ext = ext, "", ""
    for i in range(2, 1000):
        n = "%s %d%s%s" % (stem, i, dot, ext)
        if not taken(n): return n
    return None


def file_operation_start(req, kind):
    """Register a synthetic remote operation; even a quick one can be read after its POST answers."""
    oid = req.get("operation_id")
    if not oid: return None
    total = max(1, len(req.get("paths", [])))
    op = {"id": oid, "kind": kind, "state": "running", "files_done": 0, "files_total": total,
          "bytes_done": 0, "bytes_total": total * 100}
    FILE_OPERATIONS[oid] = op
    return op


def file_operation_disconnected(h):
    """The original POST's client went away, as a cancelled hub request disconnects the node."""
    import select, socket
    try:
        if not select.select([h.connection], [], [], 0)[0]: return False
        return h.connection.recv(1, socket.MSG_PEEK | socket.MSG_DONTWAIT) == b""
    except (ValueError, TypeError, BlockingIOError):
        return False  # an SSLSocket cannot peek with these flags
    except OSError:
        return True


def file_operation_wait(h, op):
    """Hold a synthetic operation open while its GET route reports progress; false after Cancel."""
    if op is None: return True
    if not FILE_OPERATION_DELAY:
        op.update(state="done", files_done=op["files_total"], bytes_done=op["bytes_total"])
        return True
    started = time.monotonic()
    while True:
        if file_operation_disconnected(h):
            op["state"] = "cancelled"
            return False
        elapsed = time.monotonic() - started
        fraction = min(1.0, elapsed / FILE_OPERATION_DELAY)
        op["files_done"] = min(op["files_total"], int(op["files_total"] * fraction))
        op["bytes_done"] = min(op["bytes_total"], int(op["bytes_total"] * fraction))
        if fraction >= 1:
            op.update(state="done", files_done=op["files_total"], bytes_done=op["bytes_total"])
            return True
        time.sleep(0.05)


def file_operation_route(h, p):
    """GET a remote operation, or the synthetic states used by UI acceptance."""
    if p == "/mock/file-operations" and FILE_OPS:
        h.send_json({"operations": list(FILE_OPERATIONS.values())})
        return True
    m = re.fullmatch(r"/api/v1/machines/([^/]+)/files/operations/([^/]+)", p)
    if not (FILE_OPS and m): return False
    op = FILE_OPERATIONS.get(m.group(2))
    if op is None:
        h.send_json({"error": "file operation not found", "code": "not_found"}, 404)
    else:
        h.send_json(op)
    return True


def file_ops_dir(mid, d, cwd):
    """(home, tree key of folder d ending in /, error or None)."""
    home, ab = mock_abs(mid, d, cwd)
    rel = mock_rel(home, ab)
    if rel is None or not (rel == "" or rel.endswith("/")):
        return home, None, ({"error": "not a directory: %s" % ab, "code": "internal"}, 502)
    if rel.split("/")[0] in (".persona", "Library") or (ab != home and not ab.startswith(home + "/")):
        return home, None, ({"error": "这个位置不能写", "code": "read_only"}, 409)
    return home, rel, None


def file_ops_upload(h, q, n):
    """POST …/files?dest=dir&dir=…: the body read slowly (MOCK_UPLOAD_KBPS), then the file put in the tree."""
    arg = lambda k: (q.get(k) or [""])[0]
    mid = urlparse(h.path).path.split("/")[4]
    if not arg("dir"):
        h.body()
        return h.send_json({"error": "dir is required"}, 400)
    home, rel, err = file_ops_dir(mid, arg("dir"), arg("cwd"))
    name = re.sub(r"[/\\\x00-\x1f]", "_", arg("name") or "file")
    if err:
        h.body()
        return h.send_json(*err)
    final = file_ops_free(rel, name, arg("conflict"))
    if final is None:
        h.body()
        return h.send_json({"error": "「%s」已经有了" % name, "code": "exists", "name": name}, 409)
    kbps, left, got = int(os.environ.get("MOCK_UPLOAD_KBPS", "2048")), n, []
    while left > 0:
        chunk = h.rfile.read(min(left, 64 << 10))
        if not chunk: return  # the browser cancelled: nothing is kept
        left -= len(chunk)
        got.append(chunk)
        time.sleep(len(chunk) / 1024 / kbps)
    data = b"".join(got)
    try: MOCK_TREE[rel + final] = data.decode()
    except UnicodeDecodeError: MOCK_TREE[rel + final] = ("application/octet-stream", base64.b64encode(data).decode())
    FILE_OPS_LOG.append({"op": "upload", "dir": arg("dir"), "name": final, "size": n})
    fs_changed(mid, [(home + "/" + rel).rstrip("/")], True)
    return h.send_json({"path": arg("dir").rstrip("/") + "/" + final, "name": final, "size": n})


def file_ops_take(rel):
    """Every tree key at or under rel (a file's key, or a folder's without its /), removed from the tree."""
    keys = [k for k in MOCK_TREE if k == rel or k.startswith(rel + "/")]
    return {k: MOCK_TREE.pop(k) for k in keys}


def file_ops_route(h, p, body):
    """POST /api/v1/machines/{mid}/files/{rename,move,trash,restore} under MOCK_FILE_OPS."""
    m = re.fullmatch(r"/api/v1/machines/([^/]+)/files/(rename|move|trash|restore)", p)
    if not (FILE_OPS and m): return False
    mid, op = m.groups()
    req = json.loads(body or b"{}")
    FILE_OPS_LOG.append({"op": op, **req})
    if os.environ.get("MOCK_FILE_OPS_OLD_NODE"):
        return h.send_json({"error": "这台电脑上的 personad 太旧", "code": "node_outdated"}, 409) or True
    cwd, changed = req.get("cwd", ""), set()
    def gone(key): return key not in MOCK_TREE and key + "/" not in MOCK_TREE
    if op == "rename":
        home, rel, err = file_ops_key(mid, req.get("path", ""), cwd)
        if err: return h.send_json(*err) or True
        if gone(rel): return h.send_json({"error": "不存在", "code": "not_found"}, 404) or True
        parent = rel.rpartition("/")[0]
        dest = (parent + "/" if parent else "") + req.get("name", "")
        if not gone(dest): return h.send_json({"error": "已经有了", "code": "exists", "name": req.get("name", "")}, 409) or True
        for k, v in file_ops_take(rel).items(): MOCK_TREE[dest + k[len(rel):]] = v
        fs_changed(mid, [(home + "/" + parent).rstrip("/")], True)
        return h.send_json({"path": req["path"].rpartition("/")[0] + "/" + req["name"]}) or True
    if op == "move":
        home, drel, err = file_ops_dir(mid, req.get("dir", ""), cwd)
        if err: return h.send_json(*err) or True
        moved = []
        for path in req.get("paths", []):
            _, rel, err = file_ops_key(mid, path, cwd)
            if err: return h.send_json(*err) or True
            if gone(rel): return h.send_json({"error": "不存在", "code": "not_found"}, 404) or True
            name = rel.rpartition("/")[2]
            final = file_ops_free(drel, name, req.get("conflict"))
            if final is None: return h.send_json({"error": "已经有了", "code": "exists", "name": name}, 409) or True
            if req.get("conflict") == "replace":  # the node moves the one there to the trash (#315), never deletes it
                FILE_TRASH["t%d" % (len(FILE_TRASH) + 1)] = (req["dir"].rstrip("/") + "/" + final, file_ops_take(drel + final))
            for k, v in file_ops_take(rel).items(): MOCK_TREE[drel + final + k[len(rel):]] = v
            changed.update({(home + "/" + rel.rpartition("/")[0]).rstrip("/"), (home + "/" + drel).rstrip("/")})
            moved.append({"from": path, "to": req["dir"].rstrip("/") + "/" + final})
        fs_changed(mid, sorted(changed), True)
        return h.send_json({"moved": moved}) or True
    if op == "trash":
        trashed = []
        for path in req.get("paths", []):
            home, rel, err = file_ops_key(mid, path, cwd)
            if err: return h.send_json(*err) or True
            if gone(rel): return h.send_json({"error": "不存在", "code": "not_found"}, 404) or True
            tid = "t%d" % (len(FILE_TRASH) + 1)
            FILE_TRASH[tid] = (path, file_ops_take(rel))
            changed.add((home + "/" + rel.rpartition("/")[0]).rstrip("/"))
            trashed.append({"path": path, "trash_id": tid})
        fs_changed(mid, sorted(changed), True)
        return h.send_json({"trashed": trashed}) or True
    restored = []
    for tid in req.get("trash_ids", []):
        if tid not in FILE_TRASH: return h.send_json({"error": "不在废纸篓里了", "code": "not_found"}, 404) or True
        path, keys = FILE_TRASH.pop(tid)
        MOCK_TREE.update(keys)
        home, _ = mock_abs(mid, path, cwd)
        changed.add(path.rpartition("/")[0] if path.startswith("/") else home)
        restored.append({"path": path})
    fs_changed(mid, sorted(changed), True)
    return h.send_json({"restored": restored}) or True


def file_make_route(h, p, body):
    """POST /api/v1/machines/{mid}/files/{mkdir,write,zip} under MOCK_FILE_OPS (#5828): a folder in the tree, a text file
    made or replaced, a real zip of tree entries kept in FILES at a temporary path for …/file/download."""
    m = re.fullmatch(r"/api/v1/machines/([^/]+)/files/(mkdir|write|zip|copy|chmod)", p)
    if not (FILE_OPS and m): return False
    mid, op = m.groups()
    req = json.loads(body or b"{}")
    FILE_OPS_LOG.append({"op": op, **{k: v for k, v in req.items() if k != "text"}})
    cwd = req.get("cwd", "")
    taken = lambda key: key in MOCK_TREE or key + "/" in MOCK_TREE
    if op == "mkdir":
        home, drel, err = file_ops_dir(mid, req.get("dir", ""), cwd)
        if err: return h.send_json(*err) or True
        name = req.get("name", "")
        if taken(drel + name): return h.send_json({"error": "已经有了", "code": "exists", "name": name}, 409) or True
        MOCK_TREE[drel + name + "/"] = None
        fs_changed(mid, [(home + "/" + drel).rstrip("/")], True)
        return h.send_json({"path": (home + "/" + drel + name)}) or True
    if op == "write":
        home, rel, err = file_ops_key(mid, req.get("path", ""), cwd)
        if err: return h.send_json(*err) or True
        text = req.get("text", "")
        if req.get("create"):
            if taken(rel): return h.send_json({"error": "已经有了", "code": "exists", "name": rel.rpartition("/")[2]}, 409) or True
        elif rel not in MOCK_TREE:
            return h.send_json({"error": "不存在", "code": "not_found"}, 404) or True
        elif not req.get("force") and isinstance(MOCK_TREE[rel], str) and req.get("revision") != mock_text_revision(MOCK_TREE[rel]):
            # changed since it was opened (GET /mock/touch?path=): nothing written, as the node answers
            return h.send_json({"error": "the file changed on the computer since it was opened", "code": "file_changed",
                                "revision": mock_text_revision(MOCK_TREE[rel]), "mtime": ago()}, 409) or True
        MOCK_TREE[rel] = text
        fs_changed(mid, [(home + "/" + rel.rpartition("/")[0]).rstrip("/")], True)
        return h.send_json({"path": home + "/" + rel, "size": len(text.encode()), "revision": mock_text_revision(text), "mtime": ago()}) or True
    if op == "chmod":  # #5831: the bits kept for the Info sheet's answer
        home, rel, err = file_ops_key(mid, req.get("path", ""), cwd)
        if err: return h.send_json(*err) or True
        if not taken(rel): return h.send_json({"error": "不存在", "code": "not_found"}, 404) or True
        MOCK_MODES[rel.rstrip("/")] = int(req.get("mode", 0o644)) & 0o777
        return h.send_json({"path": req["path"], "mode": MOCK_MODES[rel.rstrip("/")]}) or True
    if op == "copy":  # #5830: the tree entries copied into dir, named as a move names them
        home, drel, err = file_ops_dir(mid, req.get("dir", ""), cwd)
        if err: return h.send_json(*err) or True
        planned = []
        reserved = set()
        for path in req.get("paths", []):
            _, rel, err = file_ops_key(mid, path, cwd)
            if err: return h.send_json(*err) or True
            if not taken(rel): return h.send_json({"error": "不存在", "code": "not_found"}, 404) or True
            name = rel.rpartition("/")[2]
            final = file_ops_free(drel, name, req.get("conflict"), reserved)
            if final is None: return h.send_json({"error": "已经有了", "code": "exists", "name": name}, 409) or True
            reserved.add(drel + final)
            planned.append((path, rel, final))
        operation = file_operation_start(req, op)
        if not file_operation_wait(h, operation): return True  # Cancel disconnected the POST before anything was copied.
        copied = []
        for path, rel, final in planned:
            for k, v in list(MOCK_TREE.items()):
                if k == rel or k == rel + "/" or k.startswith(rel + "/"): MOCK_TREE[drel + final + k[len(rel):]] = v
            copied.append({"from": path, "to": req["dir"].rstrip("/") + "/" + final})
        fs_changed(mid, [(home + "/" + drel).rstrip("/")], True)
        return h.send_json({"copied": copied}) or True
    import io, zipfile
    out, n = io.BytesIO(), 0
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
        for path in req.get("paths", []):
            home, ab = mock_abs(mid, path, cwd)
            rel = mock_rel(home, ab)
            if rel is None: return h.send_json({"error": "不存在", "code": "not_found"}, 404) or True
            base = rel.rstrip("/").rpartition("/")[0]
            for k, v in MOCK_TREE.items():
                if k == rel or k.startswith(rel if rel.endswith("/") else rel + "/"):
                    name = k[len(base) + 1:] if base else k
                    data = b"" if v is None else base64.b64decode(v[1]) if isinstance(v, tuple) else v.encode()
                    z.writestr(name, data)
                    n += 1
    name = req.get("name") or "Archive.zip"
    if not name.lower().endswith(".zip"): name += ".zip"
    home, drel, final = None, None, None
    if req.get("dir"):
        home, drel, err = file_ops_dir(mid, req["dir"], cwd)
        if err: return h.send_json(*err) or True
        final = file_ops_free(drel, name, "keep")
    operation = file_operation_start(req, op)
    if not file_operation_wait(h, operation): return True  # Cancel: no archive or temporary download is left behind.
    if req.get("dir"):
        MOCK_TREE[drel + final] = ("application/zip", base64.b64encode(out.getvalue()).decode())
        fs_changed(mid, [(home + "/" + drel).rstrip("/")], True)
        return h.send_json({"path": home + "/" + drel + final, "name": final, "size": len(out.getvalue()), "files": n}) or True
    temp = "/tmp/persona-zips/z-%d/%s" % (len(FILE_OPS_LOG), name)
    FILES[temp] = out.getvalue()
    return h.send_json({"path": temp, "name": name, "size": len(out.getvalue()), "files": n}) or True


_features_without_plugins = features


def features():
    return _features_without_plugins() + (["plugins", "plugin_manager", "plugin_ui_slots", "plugin_auto_upgrade", "extension_ui_v3",
                                           "extension_widgets", "extension_shortcuts", "extension_notify_actions"] if PLUGINS_MODE else []) + (
                                           ["extension_operations"] if EXT_OPS else []) + (
                                           ["plugin_secret_references"] if PLUGINS_MODE and SECRET_HANDOFF else [])


def _plugin_needs(pl):
    missing = ["密钥「%s」" % s["title"] for s in pl.get("secrets", []) if s.get("required") and not s.get("set")]
    if pl["enabled"] and pl["status"] in ("needs_setup", "running") and pl["source"] == "installed":
        pl["status"] = "needs_setup" if missing else "running"
    pl["needs_setup"] = missing or (["没有设置「信息」：在 设置 › 扩展 › 信息 选一台 Mac"]
                                      if pl["id"] == "imessage" and pl["enabled"] and not pl["config"].get("machines") else None)
    if pl["id"] == "imessage" and pl["enabled"]:
        pl["status"] = "needs_setup" if pl["needs_setup"] else "running"
    return pl


def plugins_route(handler, p, body):
    """MOCK_EXTENSIONS: GET /api/v1/plugins, a plugin's page and its switch, settings and secrets. False otherwise."""
    if not PLUGINS_MODE: return False
    if (p.startswith("/api/v1/extensions/") or p.startswith("/api/v1/devices/") and p.endswith("/widgets")) and \
            system_route(handler, p, json.loads(body or b"{}") if body else {}): return True
    if not p.startswith("/api/v1/plugins"): return False
    if markets_route(handler, p, body): return True
    if p == "/api/v1/plugins":
        handler.send_json({"plugins": [{k: v for k, v in _plugin_needs(pl).items() if k in _PLUGIN_VIEW and v is not None}
                                       for pl in sorted(PLUGINS.values(), key=lambda x: x["id"])], "can_install": True, "markets": True})
        return True
    parts = p.split("/")  # ['', 'api', 'v1', 'plugins', id, '-', ...]
    if len(parts) < 6 or parts[5] != "-" or parts[4] not in PLUGINS:
        handler.send_json({"error": "no such plugin", "code": "not_found"}, 404)
        return True
    pl, rest, method = PLUGINS[parts[4]], parts[6:], handler.command
    req = json.loads(body or b"{}") if body else {}
    if rest in ([], [""]) and method == "GET":
        pass
    elif rest == ["enabled"] and method == "PUT":
        pl["enabled"] = bool(req.get("enabled"))
        pl["status"] = "disabled" if not pl["enabled"] else ("needs_setup" if pl["source"] == "installed" else "running")
        _auto_upgrade_paused(pl)
    elif rest == ["config"] and method == "PUT":
        cfg = req.get("config") or {}
        if pl["id"] == "example-gateway-quota":
            url = (cfg.get("gateway_url") or "").strip()
            if url and not url.startswith("https://"):
                msg = "要是一个 https 网址"
                handler.send_json({"error": "gateway_url: " + msg, "code": "invalid_config", "field": "gateway_url", "message": msg}, 400)
                return True
            key_set = any(x["name"] == "gateway_key" and x["set"] for x in pl["secrets"])
            why = gateway_check(cfg, "") if key_set else None
            if why:
                handler.send_json({"error": why, "code": "check_failed"}, 400)
                return True
            host = urlparse(url).netloc if url else ""
            for line in pl["permissions"]:
                if line["key"] == "network_config":
                    line["detail"] = "设置「网关地址」里填的地址（当前：%s），只连这一个主机和端口，只用 https" % (host + ("" if ":" in host or not host else ":443") or "未填")
        if pl["id"] == "imessage" and len(cfg.get("machines") or []) > 1:  # one Mac only, the one on named (the hub's imessageOneMac)
            on = next((m for m in (cfg.get("machines") or []) if m in (pl["config"].get("machines") or [])), cfg["machines"][0])
            name = next((m["name"] for m in MACHINES if m["id"] == on), on)
            msg = "只能读一台 Mac，先关掉「" + name + "」"
            handler.send_json({"error": msg, "code": "invalid_config", "field": "machines", "message": msg}, 400)
            return True
        url = cfg.get("base_url", "https://x")
        if not str(url).startswith(("http://", "https://")):
            handler.send_json({"error": "base_url: 要是一个网址", "code": "invalid_config", "field": "base_url", "message": "要是一个网址"}, 400)
            return True
        pl["config"] = cfg
        if pl["id"] == "ego":  # the same for ego lite
            for m in MACHINES:
                if "browser" in m:
                    m["browser"] = {**m["browser"], "enabled": m["id"] in (cfg.get("machines") or [])}
            for send, _ in list(LIVE):
                try: send({"type": "machines", "machines": out_machines()})
                except Exception: pass
        if pl["id"] == "cua":  # the Macs it is on for follow, and the machine list goes out again
            for m in MACHINES:
                if "computer" in m:
                    m["computer"] = {**computer_of(m["id"], m["id"] in (cfg.get("machines") or [])),
                                     "no_auto_lock": m["id"] in (cfg.get("no_auto_lock") or [])}  # #1507 b2
            for send, _ in list(LIVE):
                try: send({"type": "machines", "machines": out_machines()})
                except Exception: pass
    elif len(rest) == 2 and rest[0] == "handoff-rules" and method == "DELETE":
        rules = pl.get("handoff_rules") or []
        if not any(r["id"] == rest[1] for r in rules):
            handler.send_json({"error": "no such rule", "code": "no_rule"}, 404)
            return True
        pl["handoff_rules"] = [r for r in rules if r["id"] != rest[1]]
    elif len(rest) == 2 and rest[0] == "secrets" and method == "PUT" and req.get("reference"):
        for s in pl.get("secrets", []):
            if s["name"] == rest[1]:
                s["set"] = True
                s.pop("hint", None)
                s["reference"] = {"provider": "example-vault", "provider_name": "Example Vault", "reference": req["reference"],
                                  "title": req["reference"].rsplit("/", 2)[-2] if req["reference"].count("/") >= 3 else req["reference"]}
    elif len(rest) == 2 and rest[0] == "secrets" and method in ("PUT", "DELETE"):
        value = req.get("value") or ""
        if pl["id"] == "example-gateway-quota" and method == "PUT":
            why = gateway_check(pl["config"], value)
            if why:
                handler.send_json({"error": why, "code": "check_failed"}, 400)
                return True
        for s in pl.get("secrets", []):
            if s["name"] == rest[1]:
                s["set"] = method == "PUT"
                s.pop("hint", None)
                s.pop("reference", None)
                if pl["id"] == "example-gateway-quota" and method == "PUT" and len(value) >= 12: s["hint"] = value[-4:]
    else:
        handler.send_json({"error": "not found"}, 404)
        return True
    if pl["id"] == "cua": cua_config(pl)
    if pl["id"] == "ego":
        machines = [m["id"] for m in MACHINES if m.get("browser", {}).get("enabled")]
        pl["config"] = {**{k: v for k, v in pl["config"].items() if k != "machines"}, **({"machines": machines} if machines else {})}
    handler.send_json({k: v for k, v in _plugin_needs(pl).items() if v is not None})
    return True


