# ---------- HTTP ----------
class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def bad_network(self):
        """True when the hub is "down" (the connection is closed without an answer); otherwise waits out the delay."""
        if time.time() < NET["down_until"]:
            self.close_connection = True
            return True
        if NET["delay"] > 0:
            time.sleep(NET["delay"])
        return False

    def log_message(self, fmt, *a):
        LOG.write("%s %s\n" % (self.command, self.path)); LOG.flush()

    def send_json(self, obj, status=200, headers=None, add_error_code=True):
        global LOST_RECEIPT
        if self.command == "GET" and 200 <= status < 300:
            obj = stamp_managers(urlparse(self.path).path, obj)
        if 200 <= status < 300 and self.command in ("POST", "PUT", "PATCH", "DELETE") and self.path.startswith("/api/v1/"):
            with FAULT_LOCK:
                if LOST_RECEIPT:
                    LOST_RECEIPT = False
                    status, obj = 502, {"error": "操作回执丢失，请核对执行结果", "code": "lost_receipt",
                                        "delivered": "unknown", "retryable": False}
        if status >= 400 and isinstance(obj, dict) and add_error_code:
            obj = dict(obj)
            obj.setdefault("code", {400: "invalid", 401: "unauthorized", 403: "forbidden", 404: "not_found",
                                    405: "method_not_allowed", 409: "conflict", 502: "upstream_error",
                                    503: "node_offline"}.get(status, "internal"))
        body = json.dumps(obj, ensure_ascii=False).encode()
        if self.command == "GET" and urlparse(self.path).path == "/api/v1/sessions":
            sessions_read(self, len(body), status)
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    def body(self):
        n = int(self.headers.get("Content-Length") or 0)
        return self.rfile.read(n) if n else b""

    def send_error(self, code, message=None, explain=None):
        self.close_connection = True
        self.send_json({"error": message or self.responses.get(code, ("请求失败",))[0]}, code)

    def token_refused(self):
        """MOCK_DEVICE_TOKEN=<token>: /api/ takes only that token, in Authorization or ?token=, and answers anything else
        401 invalid token as the hub does (#1498: the live screen's page got the app's token encoded twice).
        MOCK_PAIR_TOKEN=<jp_…>: a temporary pairing code as `personad hub pair` makes (docs/protocol/protocol.md "Temporary pairing"):
        it opens everything until traded once on POST /api/v1/auth/tokens, then for MOCK_PAIR_GRACE seconds (default 10,
        the hub's 2 minutes made short); the device tokens it was traded for keep working (#2766)."""
        u = urlparse(self.path)
        if NET["reject_until"] > time.time() and u.path.startswith("/api/"):
            self.send_json({"error": "invalid token"}, 401)
            return True
        if MOCK_CF_ACCESS and u.path.startswith("/api/"):
            got = (self.headers.get("CF-Access-Client-Id", ""), self.headers.get("CF-Access-Client-Secret", ""))
            if got != MOCK_CF_ACCESS:
                print("mock: Cloudflare Access refused %s %s (%s)" % (self.command, u.path, "wrong token" if any(got) else "no token"), flush=True)
                self.close_connection = True
                if any(got):  # a token Access refuses: its own HTML page
                    page = b'<html><body>Forbidden. <a href="/cdn-cgi/access/logout">Sign out</a></body></html>'
                    self.send_response(403)
                    self.send_header("Content-Type", "text/html; charset=utf-8")
                    self.send_header("Content-Length", str(len(page)))
                    self.end_headers()
                    self.wfile.write(page)
                else:  # none: a redirect to its login
                    self.send_response(302)
                    self.send_header("Location", "https://example-team.cloudflareaccess.com/cdn-cgi/access/login/hub.invalid?redirect_url=" + u.path)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                return True
        if MOCK_PAIR_TOKEN and u.path.startswith("/api/") and u.path != "/api/v1/health":
            got = self.headers.get("Authorization", "").removeprefix("Bearer ").strip() or (parse_qs(u.query).get("token") or [""])[0]
            ok = got in PAIR_DEVICE_TOKENS or (got == MOCK_PAIR_TOKEN and (PAIR_TRADED[0] is None or time.time() < PAIR_TRADED[0] + MOCK_PAIR_GRACE))
            if ok: return False
            print("mock: 401 %s %s (%s)" % (self.command, u.path, "pairing token" if got == MOCK_PAIR_TOKEN else "unknown token"), flush=True)
            self.send_json({"error": "invalid token"}, 401)
            return True
        want = os.environ.get("MOCK_DEVICE_TOKEN")
        if not want or not u.path.startswith("/api/"): return False
        got = self.headers.get("Authorization", "").removeprefix("Bearer ").strip() or (parse_qs(u.query).get("token") or [""])[0]
        if got == want: return False
        self.send_json({"error": "invalid token"}, 401)
        return True

    def do_GET(self):
        u = urlparse(self.path); p = u.path; q = parse_qs(u.query)
        HITS["GET " + p] = HITS.get("GET " + p, 0) + 1
        audio = re.fullmatch(r"/api/v1/recordings/([^/]+)/audio", p)
        if audio and meeting_transcription_on():
            transcription_socket(self, audio[1].lower())
            return
        if self.token_refused(): return
        if CASE and case_route(self, "GET", p, q, b""): return
        if preview_route and preview_route(self, "GET", p, q): return
        if p == "/api/v1/assistant/conversations/" + ASK1 + "/always":
            return self.send_json({"grants": ALWAYS_GRANTS})
        if p == "/api/v1/subscriptions/-/graph": return self.send_json(SOURCES_GRAPH)
        if recordings_route(self, "GET", p): return
        if custom_models_route(self, "GET", p, q): return
        if managers_route(self, "GET", p): return
        if file_operation_route(self, p): return
        if _sent and _sent.route(self, "GET", p, q): return
        if _web_push and _web_push.route(self, "GET", p): return
        if providers_route(self, "GET", p, q, b""): return
        if MOCK_MESSAGING and p.startswith("/api/v1/messaging") and lark_messaging.route(self, "GET", p, q, b""): return
        if net_control(p, q): return self.send_json({"ok": True, **NET})
        if p == "/mock/fs-watch" and FS_LIVE:  # what the browsers asked to watch now
            with FAULT_LOCK:
                sets = [{k: v for k, v in m.items() if k != "_send"} for ws in FS_WATCHES.values() for m in ws.values()]
            return self.send_json({"watches": sets})
        if p == "/mock/fs-change" and FS_LIVE:  # dir (under the machine's home) gains the file `add`; git=1: the Git status moves
            mid = (q.get("machine") or ["macbook"])[0]
            home, path = mock_abs(mid, (q.get("dir") or [""])[0], "")
            add = (q.get("add") or [""])[0]
            if add:
                MOCK_TREE[mock_rel(home, path).rstrip("/") + "/" + add] = "added by the mock\n"
            git = (q.get("git") or [""])[0] == "1"
            if git: FS_STATE["dirty"] += 1
            return self.send_json({"ok": True, "sent": fs_changed(mid, [path] if add else [], git), "path": path})
        if p == "/mock/review" and GIT_REVIEW:
            return self.send_json(mock_review.control(q))
        if p == "/mock/git-write" and os.environ.get("MOCK_GIT_WRITE"):
            global GIT_W
            if q.get("reset"): GIT_W = git_write_fresh()
            if q.get("fail"): GIT_W["fail"] = (q["fail"][0], [f for f in (q.get("files") or [""])[0].split(",") if f])
            if q.get("pr"):
                kind = q["pr"][0]
                if kind != "none": GIT_W.update(upstream="origin/" + GIT_W["branch"], ahead=0)
                GIT_W["pr"] = None if kind == "none" else git_pr_make(kind, GIT_W["branch"])
            if "pr_fail" in q: GIT_W["pr_fail"] = q["pr_fail"][0] or None
            if q.get("gone"): GIT_W.update(upstream="origin/" + GIT_W["branch"], ahead=0, gone=True)
            return self.send_json({"branch": GIT_W["branch"], "ahead": GIT_W["ahead"], "files": len(GIT_W["files"])})
        if p == "/mock/git-read" and os.environ.get("MOCK_GIT_READ_FAIL"):
            if q.get("reset"): GIT_READ_FAIL["reads"] = 0
            return self.send_json(GIT_READ_FAIL)
        if p == "/mock/git-pull" and os.environ.get("MOCK_GIT_PULL"):
            if "mode" in q:
                GIT_PULL_STATE.update(behind=28, mode=q["mode"][0], pulls=0)
            return self.send_json(GIT_PULL_STATE)
        if p == "/mock/screen-password":  # MOCK_SCREEN=fake: the Mac's password changed; who signed in how; what was typed
            if "p" in q: FAKE_SCREEN["password"] = q["p"][0]
            if "clear" in q: FAKE_SCREEN.update(typed="", clicks=[], clipboard="", events=[], wheel_in=[])
            if "clip" in q: fake_screen_clip(q["clip"][0])  # the Mac copied this
            if "bg" in q and q["bg"][0] in FAKE_BG_COLORS and FAKE_BG["kind"]:  # another background (MOCK_SCREEN_BG)
                FAKE_BG["kind"] = q["bg"][0]
                for conn in list(FAKE_SCREEN["conns"]):
                    if conn.pop("waiting", False):
                        try: conn["redraw"]()
                        except OSError: pass
            if "slow" in q: FAKE_SCREEN["slow"] = float(q["slow"][0])
            if "down" in q:
                FAKE_SCREEN["down"] = q["down"][0] == "1"
                for conn in list(FAKE_SCREEN["conns"]) if FAKE_SCREEN["down"] else []:
                    try: conn["sock"].shutdown(socket.SHUT_RDWR)
                    except OSError: pass
            return self.send_json({"signins": FAKE_SCREEN["signins"], "typed": FAKE_SCREEN["typed"], "clicks": FAKE_SCREEN["clicks"],
                                   "pointer": FAKE_SCREEN["pointer"], "clipboard": FAKE_SCREEN["clipboard"], "frames": FAKE_SCREEN["frames"],
                                   "events": FAKE_SCREEN["events"][-200:], "wheel_in": FAKE_SCREEN["wheel_in"]})
        if p == "/mock/churn":
            CHURN["rounds"] = 0
            threading.Thread(target=churn, args=(int(q.get("n", ["20"])[0]), int(q.get("ms", ["300"])[0]),
                                                 int(q.get("steps", ["1"])[0]), q.get("final", ["0"])[0] == "1",
                                                 q.get("inbox", ["0"])[0] == "1", q.get("waiting", ["0"])[0] == "1",
                                                 q.get("real", ["0"])[0] == "1", int(q.get("rows", ["0"])[0] or 0)), daemon=True).start()
            return self.send_json({"ok": True})
        if p == "/mock/churned": return self.send_json(CHURN)
        if p == "/mock/sessions_reads": return self.send_json(sessions_reads(q.get("reset", ["0"])[0] == "1"))
        if p == "/mock/send-fail":
            SEND_FAIL["on"] = q.get("on", ["1"])[0] == "1"
            return self.send_json(SEND_FAIL)
        if p == "/mock/frames_label":
            FRAMES["label"] = q.get("name", [""])[0]
            return self.send_json({"ok": True})
        if p == "/mock/frames_glide_context":
            if "run_id" in q:
                FRAME_GLIDE_CONTEXT.clear()
                FRAME_GLIDE_CONTEXT.update(name=q.get("name", [""])[0], run_id=q["run_id"][0],
                                           warm_up=q.get("warm_up", ["0"])[0] == "1", action="glide",
                                           expected_iterations=int(q.get("expected_iterations", ["5"])[0]))
            return self.send_json(dict(FRAME_GLIDE_CONTEXT))
        if p == "/mock/frames":
            name = q.get("name", [None])[0]
            return self.send_json({"runs": [r for r in FRAMES["runs"] if name is None or r.get("test") == name]})
        if p == "/mock/persona-tier":
            set_persona_tier(q.get("tier", [""])[0])
            return self.send_json({"ok": True, "tier": PERSONA_TIER["tier"]})
        if p == "/mock/lark_churn":
            LARK_CHURN["rounds"] = 0
            threading.Thread(target=lark_churn, args=(q.get("feed", ["f3"])[0], int(q.get("n", ["16"])[0]), int(q.get("ms", ["500"])[0]),
                                                      q.get("new", ["0"])[0] == "1", q.get("inbox", ["0"])[0] == "1"), daemon=True).start()
            return self.send_json({"ok": True})
        if p == "/mock/lark_churned": return self.send_json(LARK_CHURN)
        if p == "/mock/truth": return self.send_json(truth())
