# ---------- area: commenting in the Feishu document reader (#1290) ----------
# MOCK_DOC_COMMENTS=1: the plugin says `lark_doc_comments`; GET /api/v1/lark/raw/documents/comments has three made-up
# threads for every document (a passage, the whole document, a resolved one), and the plugin's write routes change
# them: POST /api/v1/lark/documents/comments (the whole document, or a passage with `quote`), …/comments/{thread}/replies,
# …/comments/{thread}/resolve, GET /api/v1/lark/documents/people?q= for @. GET /mock/doc-comments lists what was written.
# MOCK_DOC_COMMENTS=read: a plugin without the writes (no lark_doc_comments, no write routes): the threads only.
DOC_COMMENTS = os.environ.get("MOCK_DOC_COMMENTS") in ("1", "read")
DOC_COMMENT_WRITES = os.environ.get("MOCK_DOC_COMMENTS") == "1"
DOC_WRITES = []


def _doc_reply(rid, name, text, minutes, mention=None, mentions=()):
    """A reply as the Lark gateway gives it: text, with each @ a mention segment of its own."""
    content = [{"kind": "text", "text": text}]
    if mention:
        content = [{"kind": "mention", "text": "@" + mention}, {"kind": "text", "text": " " + text}]
    for m in mentions:  # what was written: the text holds `@name` for each one mentioned
        token, out = "@" + m.get("name", ""), []
        for seg in content:
            parts = seg["text"].split(token) if seg["kind"] == "text" and token != "@" else [seg["text"]]
            for i, part in enumerate(parts):
                if i: out.append({"kind": "mention", "text": token})
                if part or len(parts) == 1: out.append(dict(seg, text=part))
        content = out
    return {"id": rid, "author": {"id": "u-" + rid, "name": name}, "content": content, "createdAt": ago(minutes=minutes)}


DOC_THREADS = [
    {"id": "c1", "whole": False, "resolved": False, "quote": "这一版统一了圆角和描边", "anchorBlockId": "b2", "createdAt": ago(hours=5),
     "replies": [_doc_reply("r1", "韩梅梅", "圆角统一成 12 还是 14？两种都试过吗", 300),
                 _doc_reply("r2", "李雷", "试过，14 在小尺寸下太圆了", 280, mention="韩梅梅")]},
    {"id": "c2", "whole": True, "resolved": False, "quote": "", "createdAt": ago(hours=3),
     "replies": [_doc_reply("r3", "王五", "深色模式的截图能补一张吗", 180)]},
    {"id": "c3", "whole": False, "resolved": True, "quote": "待确认", "anchorBlockId": "b3", "createdAt": ago(days=1),
     "replies": [_doc_reply("r4", "赵六", "图标导出尺寸已经确认", 1500)]},
]
DOC_PEOPLE = [{"user_id": "ou_mock_hmm", "name": "韩梅梅"}, {"user_id": "ou_mock_ll", "name": "李雷"},
              {"user_id": "ou_mock_ww", "name": "王五"}, {"user_id": "ou_mock_zl", "name": "赵六"}]

if DOC_COMMENTS:
    _features_before_doc_comments = features

    def features():
        return _features_before_doc_comments() + (["lark_doc_comments"] if DOC_COMMENT_WRITES else [])

    _get_before_doc_comments, _post_before_doc_comments = H.do_GET, H.do_POST

    def _doc_get(handler):
        u = urlparse(handler.path)
        q = parse_qs(u.query)
        if u.path == "/api/v1/lark/raw/documents/comments":
            return handler.send_json({"threads": DOC_THREADS})
        if u.path == "/api/v1/lark/raw/documents/read" and (q.get("format") or [""])[0] == "markdown":
            # The reader asks for Markdown first: the made-up document as the Lark gateway exports it.
            return handler.send_json({"type": "docx", "token": "AbC123", "title": LARK_DOCUMENT["title"], "url": (q.get("url") or [""])[0],
                                      "authority": {"copy": True, "print": True, "export": True},
                                      "markdown": "# 新版图标评审\n\n这一版统一了圆角和描边，深色模式单独调了对比度。\n\n## 待确认\n\n- 圆角统一成 12 还是 14\n- 小尺寸下描边是否加粗\n"})
        if u.path == "/api/v1/lark/documents/people":
            want = (q.get("q") or [""])[0]
            return handler.send_json({"members": [p for p in DOC_PEOPLE if want in p["name"]]})
        if u.path == "/mock/doc-comments":
            return handler.send_json({"writes": DOC_WRITES})
        return _get_before_doc_comments(handler)

    def _doc_post(handler):
        p = urlparse(handler.path).path
        if not DOC_COMMENT_WRITES or not p.startswith("/api/v1/lark/documents/comments"):
            return _post_before_doc_comments(handler)
        try:
            b = json.loads(handler.body() or b"{}")
        except ValueError:
            return handler.send_json({"error": "bad json"}, 400)
        parts = p.split("/")
        DOC_WRITES.append({"path": p, "body": b})
        text = (b.get("content") or "").strip()
        if p == "/api/v1/lark/documents/comments":
            if not text:
                return handler.send_json({"error": "content is required"}, 400)
            t = {"id": "c%d" % (len(DOC_THREADS) + 1), "whole": not b.get("quote"), "resolved": False, "quote": b.get("quote") or "",
                 "anchorBlockId": b.get("block_id"), "createdAt": ago(),
                 "replies": [_doc_reply("n%d" % len(DOC_WRITES), "我", text, 0, mentions=b.get("mentions") or [])]}
            DOC_THREADS.insert(0, t)
            return handler.send_json({"ok": True, "threads": DOC_THREADS, **({"anchored": True} if b.get("quote") else {})})
        thread = next((t for t in DOC_THREADS if len(parts) > 6 and t["id"] == unquote(parts[6])), None)
        if thread is None:
            return handler.send_json({"error": "no such comment"}, 404)
        if p.endswith("/replies"):
            if not text:
                return handler.send_json({"error": "content is required"}, 400)
            thread["replies"].append(_doc_reply("n%d" % len(DOC_WRITES), "我", text, 0, mentions=b.get("mentions") or []))
            return handler.send_json({"ok": True, "threads": DOC_THREADS})
        if p.endswith("/resolve"):
            thread["resolved"] = bool(b.get("resolved"))
            return handler.send_json({"ok": True, "threads": DOC_THREADS})
        return handler.send_json({"error": "not found"}, 404)

    H.do_GET = _doc_get
    H.do_POST = _doc_post
    # The web's reader opens from a link in a chat: the widget session ends with the made-up document's.
    ITEMS[WIDGET].append(it("assistant", "text", 0, text="评审文档在这里：[新版图标评审](https://example.feishu.cn/docx/AbC123)，评论里还有两条没解决。"))
# ---------- area: hub restarts the app does not notice (docs/operations/hub-restart.md, #1634) ----------
# MOCK_RESTART=1: hello carries event_stream / event_seq / resumed and the numbered broadcasts are kept, like the hub's
# event log; GET /mock/restart?gap_ms=1500&missed=todos,inbox says hub_restarting and closes every socket with 1001,
# connections in the next gap_ms wait (the socket's backlog), the `missed` broadcasts are numbered while nobody is
# connected and replayed after a resumed hello; &drop_post=1: the next write with an op id is done but its answer
# lost (the old process went). Writes with X-Persona-Op-Id are done once: a repeat gets the first answer.
# GET /mock/restart (no gap_ms): what happened (restarts, connects and whether they resumed, op ids, GET hits).
RESTART_MODE = os.environ.get("MOCK_RESTART") == "1"
RESTART = {"stream": "mock-" + uuid.uuid4().hex[:8], "seq": 0, "log": [], "gap_until": 0.0, "drop_post": False,
           "restarts": 0, "connects": [], "ops": {}, "op_posts": []}
RESTART_LOCK = threading.Lock()


def restart_backlog():
    if not RESTART_MODE: return
    wait = RESTART["gap_until"] - time.time()
    if wait > 0: time.sleep(wait)


def restart_hello(path):
    if not RESTART_MODE: return {}
    q = parse_qs(urlparse(path).query)
    stream, seq = q.get("event_stream", [""])[0], q.get("event_seq", [""])[0]
    with RESTART_LOCK:
        resumed = stream == RESTART["stream"] and seq.isdigit() and int(seq) <= RESTART["seq"]
        RESTART["connects"].append({"at": time.time(), "asked": bool(stream), "resumed": resumed, "from": int(seq) if seq.isdigit() else None})
        return {"event_stream": RESTART["stream"], "event_seq": RESTART["seq"], "resumed": resumed}


def restart_replay(send, path):
    if not RESTART_MODE: return
    with RESTART_LOCK:
        last = RESTART["connects"][-1] if RESTART["connects"] else {}
        missed = [e for e in RESTART["log"] if last.get("resumed") and e["event_seq"] > last["from"]]
    for e in missed: send(dict(e))


def restart_broadcast(kind):
    with RESTART_LOCK:
        RESTART["seq"] += 1
        event = {"type": kind, "event_seq": RESTART["seq"]}
        RESTART["log"].append(event)
    for send, _ in list(LIVE):
        try: send(dict(event))
        except Exception: pass


def restart_now(gap_ms, missed, drop_post):
    with FAULT_LOCK:
        clients = list(CLIENTS.values())
    for c in clients:
        try: c["send"]({"type": "hub_restarting", "back_in_ms": 3000})
        except Exception: pass
    time.sleep(0.05)
    with RESTART_LOCK:
        RESTART["gap_until"] = time.time() + gap_ms / 1000
        RESTART["restarts"] += 1
        RESTART["drop_post"] = drop_post
    for c in clients:
        try: c["close"]()
        except Exception: pass
    for kind in missed: restart_broadcast(kind)  # nobody is connected: only the log has them


if RESTART_MODE:
    _get_before_restart, _post_before_restart = H.do_GET, H.do_POST

    def _restart_get(handler):
        u = urlparse(handler.path)
        if u.path != "/mock/restart":
            return _get_before_restart(handler)
        q = parse_qs(u.query)
        if "gap_ms" in q:
            missed = [k for k in q.get("missed", [""])[0].split(",") if k]
            restart_now(int(q["gap_ms"][0]), missed, q.get("drop_post", [""])[0] == "1")
        elif "event" in q:
            restart_broadcast(q["event"][0])
        with RESTART_LOCK:
            state = {k: RESTART[k] for k in ("stream", "seq", "restarts", "connects", "op_posts")}
        return handler.send_json({**state, "hits": HITS})

    def _restart_post(handler):
        op = (handler.headers.get("X-Persona-Op-Id") or "").lower()
        if not op:
            return _post_before_restart(handler)
        path = urlparse(handler.path).path
        with RESTART_LOCK:
            RESTART["op_posts"].append({"op": op, "path": path})
            first = RESTART["ops"].get(op)
        if first is not None:  # done once already: its first answer, nothing done again
            handler.body()
            body = json.dumps(first["body"], ensure_ascii=False).encode()
            handler.send_response(first["status"]); handler.send_header("Content-Type", "application/json")
            handler.send_header("Content-Length", str(len(body))); handler.end_headers(); handler.wfile.write(body)
            return
        sent = {}
        original = handler.send_json

        def keep(obj, status=200):
            sent.update(body=obj, status=status)
            with RESTART_LOCK:
                RESTART["ops"][op] = {"body": obj, "status": status}
                drop = RESTART["drop_post"]
                RESTART["drop_post"] = False
            if drop:  # done, but the answer went with the old process
                handler.close_connection = True
                handler.connection.shutdown(socket.SHUT_RDWR)
                return
            original(obj, status)

        handler.send_json = keep
        try:
            return _post_before_restart(handler)
        finally:
            handler.send_json = original

    H.do_GET, H.do_POST = _restart_get, _restart_post
MOCK_HELP.append("MOCK_RESTART=1  hub 无感重启（#1634）：hello 带 event_stream / event_seq / resumed；GET /mock/restart?gap_ms=1500&missed=todos,inbox[&drop_post=1] 模拟一次计划内重启（hub_restarting + 1001，期间的连接排队，漏掉的广播在续传时补发），?event=todos 发一条带序号的广播，不带参数看连接 / 续传 / op id / GET 次数")

MOCK_HELP.append("MOCK_DOC_COMMENTS=1  飞书文档阅读页能写评论（#1290）：features 带 lark_doc_comments，每篇文档三条编造的评论，回复 / 新评论 / 解决 / 重新打开 / @人都改它们；GET /mock/doc-comments 看写了什么；「给天气 App 加主屏幕小组件」最后一条带这篇文档的链接（网页从这里打开阅读页）；=read 是不能写的插件（没有 lark_doc_comments，只读评论）")


# ---------- area: an inbox item's page drawn by a plugin (docs/extensions/extensions.md "Inbox items", #1681) ----------
# MOCK_INBOX_ITEM_UI=1 (with MOCK_EXTENSIONS=1): a plugin example-chat draws the page of Feishu's items (inbox_item for
# connector lark), from the item it is told of (context.item): the people, the time it spans, the thing it continues
# and its messages, a reply (files the item as replied) and "View in conversation" (persona://inbox/<item>/source: the apps open the
# item's own chat). "Handled" stays the app's own. Items of another source are refused (403), an unknown one is 404, like
# the hub; it fails (502) on groups' items. The hub's own detail stays for other sources.
INBOX_ITEM_UI = [{"plugin": "example-chat", "plugin_name": "Example 飞书事件", "id": "event", "title": "事件", "placement": "inbox_item",
                  "size": "full", "connector": "lark"}] if os.environ.get("MOCK_INBOX_ITEM_UI") == "1" else []
# The made-up meta of a few items (the plugin's own record: who said what, in order).
_EVENT_META = {
    "lark:f1:100": {"continues": "上周的发布排期", "messages": [
        ("韩梅梅", 40, "周五的发布能赶上吗？"), ("韩梅梅", 39, "下午我要和客户确认时间"),
        ("你", 30, "我先看下 release 分支还剩什么"), ("韩梅梅", 18, "好，三点前给我个准话就行")]},
    "lark:f2:200": {"messages": [("李雷", 90, "新版图标放在这里了"), ("王芳", 70, "圆角是不是大了一点"), ("李雷", 55, "@你 下午评审前看一眼？")]},
}


def inbox_item_ui(ui, req):
    """POST /api/v1/plugins/example-chat/-/ui/<ui>: (status, body) as the hub answers for an inbox_item."""
    iid = (req.get("context") or {}).get("item", "")
    it = next((x for x in INBOX if x["id"] == iid), None)
    if ui != "event" or not it:
        return 404, {"error": "收件箱里没有这一条", "code": "not_found"}
    if it.get("source") != "lark":
        return 403, {"error": "这一条不是这个扩展的连接器收进来的", "code": "forbidden"}
    if it.get("kind") == "group":  # the plugin fails on these: the apps draw the item's own body, and say so
        return 502, {"error": "插件画的界面这个 hub 画不了：section 0 item 0 (link): link needs title and an https url", "code": "plugin_failed"}
    action = req.get("action") or ""
    if action == "reply":
        if not ((req.get("values") or {}).get("reply") or "").strip():
            return 200, {"toast": "先写点什么"}
        it["done_at"], it["done_by"] = ago(), "replied"
        return 200, {"toast": "已回复"}
    if action == "open":
        return 200, {"open_url": "persona://inbox/%s/source" % iid}
    meta = _EVENT_META.get(iid) or {"messages": [(it.get("sender") or it["title"], 30, it.get("preview", ""))]}
    msgs = meta["messages"]
    people = list(dict.fromkeys(m[0] for m in msgs))
    first, last = ago(minutes=msgs[0][1]), ago(minutes=msgs[-1][1])
    clock = lambda iso: datetime.fromisoformat(iso.replace("Z", "+00:00")).astimezone().strftime("%H:%M")
    facts = [{"type": "row", "title": "涉及的人", "value": "、".join(people)},
             {"type": "row", "title": "时间", "value": "%s–%s · %d 分钟" % (clock(first), clock(last), msgs[0][1] - msgs[-1][1])}]
    if meta.get("continues"):
        facts.append({"type": "row", "title": "接着《%s》" % meta["continues"], "subtitle": "上一件已处理的事", "badge": {"text": "已处理"}})
    chain = [{"type": "row", "title": who, "subtitle": text, "value": clock(ago(minutes=m)),
              **({"badge": {"text": "最新", "tone": "caution"}} if i == len(msgs) - 1 else {})} for i, (who, m, text) in enumerate(msgs)]
    actions = [{"type": "field", "name": "reply", "label": "回复", "kind": "text", "placeholder": "回复 %s" % msgs[-1][0]},
               {"type": "button", "title": "回复", "action": {"id": "reply", "submit": True}},
               {"type": "button", "title": "在会话里看", "action": {"id": "open"}}]
    return 200, {"view": {"sections": [{"items": facts}, {"title": "消息 · %d 条" % len(msgs), "items": chain}, {"items": actions}]}}


