# ---------- area: adding a computer from a signed-in device (#287, docs/assistant/onboarding.md 4.2, 5.3) ----------
# MOCK_ADD_COMPUTER=1: the hub says machines_add and machine_trust. POST /api/v1/auth/pair-codes {"add": {name, os}} adds a
# pending kind-link computer (never connected), {"machine": id} gives one a new code; MOCK_ADD_COMPUTER_JOIN seconds later
# (default 8, 0 = never) its Persona Link "connects" (online, still pending). POST /api/v1/machines/{id}/confirm | reject
# confirm it / remove it. MOCK_ADD_COMPUTER=seed also lists one pending computer that never connected and makes Mac Studio
# a link computer that is offline (error_code link_offline). MOCK_ADD_COMPUTER_ERROR=<code> refuses every add with it
# (tls_required, mesh_member, too_many_pending); MOCK_ADD_COMPUTER_NO_SITE=1: the reply has no install line (a local build).
# {"add": {…, "manager": id}} adds it to that manager (404 no_manager, 409 installing) and the reply says `manager`;
# one added to an offline manager is not listed in /machines (the hub lists what a manager reports) and never connects
# (its Persona Link gets 503 assistant_offline). The same name again for a manager that is online lists it there.
# MOCK_ADD_COMPUTER_NO_MANAGER=1 is a hub from before add.manager (the field ignored, no `manager` in the reply).
# Not mocked: 503 assistant_offline (a reused computer in an offline manager's own list) and 503 owners_unknown.
# MOCK_READINESS (below) turns it on too: a scenario with no computer or a pending one is added / confirmed here.
ADD_COMPUTER = os.environ.get("MOCK_ADD_COMPUTER", "") or ("1" if os.environ.get("MOCK_READINESS") else "")
ADD_COMPUTER_PENDING_TEXT = "等你在新版 App 或网页里确认这是你的电脑"
ADD_COMPUTER_ERRORS = {
    "tls_required": (409, "hub 还没打开安全连接，电脑接不进来"),
    "mesh_member": (409, "这台 hub 是组里的成员，到中心 hub 上添加电脑"),
    "too_many_pending": (429, "已经有 3 台电脑在等确认"),
}
# add.manager's own refusals, as the hub words them (server/internal/hub/machines_add.go, locales hub-pairing: no_assistant,
# assistant_installing, assistant_away; owners_unknown is the hub's plain English), by the request's Accept-Language.
ADD_MANAGER_ERRORS = {
    "no_manager": (404, {"en": "There\u2019s no such assistant", "zh-Hans": "没有这个助手", "ja": "そのアシスタントはありません"}),
    "installing": (409, {"en": "This assistant isn\u2019t installed yet. Add the computer once it is",
                         "zh-Hans": "这个助手还没装好，装好后再添加电脑",
                         "ja": "このアシスタントはまだインストールされていません。インストールが終わってからコンピュータを追加してください"}),
    "assistant_offline": (503, {"en": "This computer is with an assistant that\u2019s offline right now, so it can\u2019t be moved. Try again when that assistant is back",
                                "zh-Hans": "这台电脑现在所在的助手不在线，挪不过来。等那个助手上线后再试",
                                "ja": "このコンピュータが今いるアシスタントがオフラインのため、移動できません。そのアシスタントがオンラインに戻ってからもう一度お試しください"}),
    "owners_unknown": (503, "the hub could not read which manager carries which machine; try again"),
}


def _add_computer_push():
    for send, _ in list(LIVE):
        try: send({"type": "machines", "machines": out_machines()})
        except Exception: pass


def _add_computer_listed(m):
    MACHINES.append(m)
    if MACHINES_KEEP is not None:
        MACHINES_KEEP.add(m["id"])


# Computers added to an offline manager, by id: the hub has them, /machines does not list them yet.
ADD_COMPUTER_UNLISTED = {}


def _add_computer_all():
    return MACHINES + list(ADD_COMPUTER_UNLISTED.values())


def _manager_online(mid):
    return next((x for x in MANAGERS["list"] if x["id"] == mid), {}).get("online", False)


if ADD_COMPUTER:
    _features_without_add_computer = features

    def features():
        f = _features_without_add_computer()
        return f + [x for x in ("machine_trust", "machines_add") if x not in f]

    if ADD_COMPUTER == "seed":
        _add_computer_listed({"id": "office", "name": "办公室的台式机", "kind": "link", "icon": "desktop", "online": False,
                              "trust": "pending", "error_code": "never_connected", "error": ADD_COMPUTER_PENDING_TEXT})
        for _m in MACHINES:
            if _m["id"] == "studio":
                _m.update(kind="link", online=False, error_code="link_offline",
                          error="link closed: failed to get reader: EOF")

    def _add_computer_join(mid, os_name):
        m = next((x for x in MACHINES if x["id"] == mid), None)
        if m is None or m.get("online") or m.get("trust") != "pending":
            return
        m.update(online=True, os={"mac": "darwin", "windows": "windows"}.get(os_name, "linux"),
                 hostname=m["name"], arch="arm64" if os_name == "mac" else "amd64", last_seen=ago(),
                 herdr_version="0.9.5", claude_version="2.1.320")
        m.pop("error_code", None)
        _add_computer_push()

    def _add_computer_route(handler, p, body):
        if p == "/api/v1/auth/pair-codes":
            req = json.loads(body or b"{}") or {}
            add, again = req.get("add"), req.get("machine")
            if not add and not again:
                return False  # an app's code: the handler's own
            code = os.environ.get("MOCK_ADD_COMPUTER_ERROR", "")
            if add and code:
                if code in ADD_MANAGER_ERRORS:
                    status, text = ADD_MANAGER_ERRORS[code]
                    if isinstance(text, dict): text = text[cron_lang(handler.headers.get("Accept-Language"))]
                else:
                    status, text = ADD_COMPUTER_ERRORS.get(code, (409, code))
                reply = {"error": text, "code": code}
                if code == "tls_required":
                    reply["action"] = "enable_tls"
                handler.send_json(reply, status)
                return True
            added = False
            # add.manager (docs/protocol/protocol.md "Computer pairing codes"): the computer is that manager's; a hub from
            # before it (MOCK_ADD_COMPUTER_NO_MANAGER=1, or one with no roster) ignores it and says no manager in the reply.
            owner = ""
            if add and _stamps() and os.environ.get("MOCK_ADD_COMPUTER_NO_MANAGER") != "1":
                owner = str(add.get("manager") or "").strip()
                target = next((x for x in MANAGERS["list"] if x["id"] == owner), None)
                if owner and target is None:
                    handler.send_json({"error": "没有这个助手", "code": "no_manager"}, 404)
                    return True
                if target is not None and target.get("installing"):
                    handler.send_json({"error": "这个助手还没装好，装好后再添加电脑", "code": "installing"}, 409)
                    return True
            if add:
                name = str(add.get("name") or "").strip()
                if not name or len(name) > 40:
                    handler.send_json({"error": "名字不能为空，最多 40 个字", "code": "invalid_name"}, 400)
                    return True
                m = next((x for x in _add_computer_all() if x.get("name") == name and x.get("trust") == "pending" and not x.get("online")), None)
                if m is None and sum(1 for x in _add_computer_all() if x.get("trust") == "pending") >= 3:
                    # the hub's own limit (maxPendingComputers, server/internal/hub/machines_add.go)
                    handler.send_json({"error": "已经加了 3 台电脑还没处理完（有的可能还没连上来过）。删掉用不上的，再添加新的",
                                       "code": "too_many_pending"}, 429)
                    return True
                if m is None:
                    base = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-") or add.get("os") or "computer"
                    mid, n = base, 2
                    while any(x["id"] == mid for x in _add_computer_all()):
                        mid, n = "%s-%d" % (base, n), n + 1
                    m = {"id": mid, "name": name, "kind": "link", "icon": add.get("icon") or "laptop", "online": False,
                         "trust": "pending", "error_code": "never_connected", "error": ADD_COMPUTER_PENDING_TEXT}
                    added = True
                if owner == "assistant":
                    MANAGED_MACHINES.pop(m["id"], None)
                elif owner:  # added to it, or the one used again moved to it
                    MANAGED_MACHINES[m["id"]] = owner
                if not any(x is m for x in MACHINES):  # listed once its manager is one that reports it (online)
                    if _manager_online(machine_manager(m["id"])):
                        ADD_COMPUTER_UNLISTED.pop(m["id"], None)
                        _add_computer_listed(m)
                    else:
                        ADD_COMPUTER_UNLISTED[m["id"]] = m
                os_name = add.get("os") or "mac"
            else:
                m = next((x for x in _add_computer_all() if x["id"] == again), None)
                if m is None:
                    handler.send_json({"error": "没有这台电脑", "code": "not_found"}, 404)
                    return True
                if m.get("trust") != "pending":
                    handler.send_json({"error": "这台电脑已经确认过了", "code": "not_pending"}, 409)
                    return True
                os_name = "mac"
            tok = "jp_mock%d" % (len(TOKENS) + 1)
            expires = datetime.now(timezone.utc) + timedelta(seconds=int(os.environ.get("MOCK_PAIR_SECONDS") or 600))
            pair = "persona://link?url=https%3A%2F%2Fhub.example.com&token=" + tok + "&machine=" + m["id"]
            reply = {"token": tok, "expires_at": expires.isoformat().replace("+00:00", "Z"), "url": "https://hub.example.com",
                     "machine": m["id"], "name": m["name"], "trust": "pending", "pair_url": pair,
                     "command": "persona-link pair '%s'" % pair}
            if added:
                reply["added"] = True
            if _stamps() and os.environ.get("MOCK_ADD_COMPUTER_NO_MANAGER") != "1":
                reply["manager"] = machine_manager(m["id"])
            if not os.environ.get("MOCK_ADD_COMPUTER_NO_SITE"):
                reply["install"] = {"linux": "curl -fsSL https://example.com/install.sh | sh -s -- --node --pair '%s'" % pair}
            _add_computer_push()
            join = float(os.environ.get("MOCK_ADD_COMPUTER_JOIN") or 8)
            if join > 0 and _manager_online(machine_manager(m["id"])):  # an offline manager's: 503 assistant_offline
                threading.Timer(join, _add_computer_join, (m["id"], os_name)).start()
            handler.send_json(reply)
            return True
        parts = p.split("/")
        if len(parts) == 6 and p.startswith("/api/v1/machines/") and parts[5] in ("confirm", "reject"):
            m = next((x for x in _add_computer_all() if x["id"] == parts[4]), None)
            if m is None:
                handler.send_json({"error": "没有这台电脑", "code": "not_found"}, 404)
                return True
            if parts[5] == "confirm":
                m.pop("trust", None)
                if m.get("error") == ADD_COMPUTER_PENDING_TEXT:
                    m.pop("error", None)
            elif m.get("trust") != "pending":
                handler.send_json({"error": "这台电脑已经确认过了", "code": "not_pending"}, 409)
                return True
            elif ADD_COMPUTER_UNLISTED.pop(m["id"], None) is None:
                MACHINES.remove(m)
            _add_computer_push()
            handler.send_json({"ok": True})
            return True
        return False

    _plugins_route_without_add_computer = plugins_route

    def plugins_route(handler, p, body):
        if _add_computer_route(handler, p, body): return True
        return _plugins_route_without_add_computer(handler, p, body)


MOCK_HELP.append("MOCK_ADD_COMPUTER=1|seed  机器 › 添加电脑（#287）：features 有 machines_add / machine_trust，pair-codes 的 add 加一台待确认的电脑，"
                 "MOCK_ADD_COMPUTER_JOIN 秒后（默认 8，0 = 不来）它连上来等确认；seed 另列一台没连过的待确认电脑、Mac Studio 离线（link_offline）；"
                 "MOCK_ADD_COMPUTER_ERROR=tls_required|mesh_member|too_many_pending|no_manager|installing|assistant_offline|owners_unknown 拒绝添加，MOCK_ADD_COMPUTER_NO_SITE=1 不给安装命令；"
                 "add.manager 把电脑加到那个助手名下（回包 manager；助手离线时 /machines 先不列它），MOCK_ADD_COMPUTER_NO_MANAGER=1 模拟不认它的旧 hub（回包没有 manager）")

# ---------- area: the main conversation's readiness (#287, docs/assistant/onboarding.md 4.4–4.6, 5.1–5.4) ----------
# MOCK_READINESS=<scenario> (docs/operations/testing.md "Readiness scenarios", scripts/mock/readiness_mock.py): a new user's hub in one of
# the states the setup card shows, in the hub's shapes and words (its own catalogs, by Accept-Language): the features
# assistant_readiness, machines_add, machine_trust, builtin_presets and launcher_auto_name; GET /api/v1/assistant/readiness[?probe=1],
# POST …/readiness/dismiss, POST /api/v1/assistant/warm with readiness; POST /api/v1/assistant/conversations refused
# with the scenario's code (409 no_machine / machine_pending / claude_missing / launcher_missing, 503 node_unreachable); POST
# /api/v1/sessions on a pending computer 409 machine_pending; GET /api/v1/launchers/presets with the built-in providers
# (presets_builtin.json) before the plugins'. The computer is the example user's MacBook (mbp) alone, with no agents, except in
# demo (full on the usual data, the assistant on server). Adding and confirming a computer works (MOCK_ADD_COMPUTER), and the
# readiness follows the machines: zero → add → it joins → confirm → the computer step is ok.
# MOCK_START_ERROR=<code> refuses every conversation start with that code whatever the scenario (no_machine,
# machine_pending, claude_missing, launcher_missing, node_unreachable, assistant_offline). MOCK_BUILTIN_PRESETS=1 serves
# the built-in providers and the features builtin_presets and launcher_auto_name without a scenario.
READINESS = os.environ.get("MOCK_READINESS", "")
BUILTIN_PRESETS = bool(READINESS) or os.environ.get("MOCK_BUILTIN_PRESETS") == "1"
if READINESS or BUILTIN_PRESETS:
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import readiness_mock
    if READINESS and READINESS not in readiness_mock.SCENARIOS:
        sys.exit("mock hub 配置错误：MOCK_READINESS 只能是 %s" % " / ".join(readiness_mock.SCENARIOS))
    _START_ERROR = os.environ.get("MOCK_START_ERROR", "")
    if _START_ERROR and _START_ERROR not in readiness_mock.START_CODES:
        sys.exit("mock hub 配置错误：MOCK_START_ERROR 只能是 %s" % " / ".join(readiness_mock.START_CODES))
    _features_without_readiness = features

    def features():
        f = _features_without_readiness()
        extra = ("assistant_readiness", "machines_add", "machine_trust") if READINESS else ()
        return f + [x for x in extra + ("builtin_presets", "launcher_auto_name") if x not in f]

READY = {"sc": readiness_mock.SCENARIOS.get(READINESS, {}) if READINESS else {}, "dismissed": False}
# Optional probe boundaries for #1892: exceed Apple's old 30 s timeout, or refuse the try with an HTTP error.
READINESS_PROBE_DELAY = float(os.environ.get("MOCK_READINESS_PROBE_DELAY", "0"))
READINESS_PROBE_ERROR = int(os.environ.get("MOCK_READINESS_PROBE_ERROR", "0"))
READY_MAIN = "b2e4d6f8-0000-4000-8000-0000000000aa"
if READINESS:
    _sc = READY["sc"]
    _launcher = _sc.get("launcher", "claude")
    ASSISTANT_CONFIG["launcher"] = _launcher
    if not _sc.get("demo"):
        _mbp = {"id": "mbp", "name": "小林的 MacBook", "kind": "link", "icon": "laptop", "online": True, "hostname": "MacBook",
                "os": "darwin", "arch": "arm64", "home": "/Users/me", "herdr_version": "0.9.5", "claude_version": "2.1.320",
                "last_seen": ago()}
        if _sc.get("claude") == "missing":
            _mbp.pop("claude_version")
        if _sc["machine"] == "offline":
            _mbp.update(online=False, error_code="link_offline", error="link closed: failed to get reader: EOF", last_seen=ago(hours=2))
        if _sc["machine"] == "pending":
            _mbp.update(trust="pending", error=ADD_COMPUTER_PENDING_TEXT)
        if _sc["machine"] == "outdated":
            _mbp["error_code"] = "node_outdated"  # a node from before Model configuration: it cannot run the main conversation
        MACHINES_KEEP = set()
        if _sc["machine"] != "none":
            MACHINES.append(_mbp)
            MACHINES_KEEP.add("mbp")
        ASSISTANT[:] = []
        ASSISTANT_CONFIG.update(machine_id="mbp" if _sc["machine"] not in ("none", "pending") else "", main=None)
        _code = _sc.get("model")
        if _code:  # the main conversation's only turn: answered (full), or failed so
            _text = readiness_mock.ANSWER if _code == "ok" else readiness_mock.TURN_ERRORS[_code]
            _main = assistant_sess(READY_MAIN, "", 2, _text)
            _main.update(machine_id="mbp", cwd="/Users/me/.persona/assistant", launcher=_launcher, main=True)
            if _code != "ok":
                _main.update(turn_error=_text, turn_error_code=_code,
                             **({"turn_error_kind": "user"} if _code in readiness_mock.USER_TURN_ERRORS else {}))
            ASSISTANT.append(_main)
            ASSISTANT_CONFIG["main"] = READY_MAIN
            ITEMS[READY_MAIN] = [it("user", "text", 3, text="你好"), it("assistant", "text", 2, text=_text)]


def ready_machine():
    """The main conversation's computer as readiness_mock wants it: the one set in Settings › Assistant when it is among the
    confirmed ones served, else the first of them (assistant/profile.go effective). With none confirmed, name the
    pending computer with the smallest id for confirmation; None when neither exists."""
    machines = out_machines()
    ok = [m for m in machines if m.get("trust") != "pending"]
    m = next((x for x in ok if x["id"] == ASSISTANT_CONFIG["machine_id"]), ok[0] if ok else None)
    if m is None:
        m = min((x for x in machines if x.get("trust") == "pending"), key=lambda x: x["id"], default=None)
    if m is None:
        return None
    return {"id": m["id"], "name": m["name"], "online": bool(m.get("online")), "claude_version": m.get("claude_version", ""),
            "pending": m.get("trust") == "pending", "node_outdated": m.get("error_code") == "node_outdated"}


def ready_lang(handler):
    return readiness_mock.lang_of(handler.headers.get("Accept-Language", ""))


def ready_state(handler, probe=False):
    sc, m = READY["sc"], ready_machine()
    launcher = ASSISTANT_CONFIG["launcher"] or "claude"
    result = None
    if probe and m and not m["pending"] and m["online"] and not m["node_outdated"]:
        result = readiness_mock.probe_result(sc, launcher)
        if result["ok"] and not sc.get("model"):
            READY["sc"] = sc = dict(sc, model="ok")  # what a probe that answered says of the model, from now on
    return readiness_mock.readiness(sc, m, ready_lang(handler), launcher, READY["dismissed"], result)


def _builtin_preset_route(handler, p, body):
    """A built-in preset's key test and add (docs/integrations/launchers.md"Built-in presets"): the test in the hub's words (a key with
    "bad" 401, "forbid" 403, "nopath" 404, "busy" 429, "slow" the timeout, "region" Anthropic's region block); the add
    with the name made up from the preset (-2, -3 when taken), its display name, and `assign` put only on the uses
    not in MOCK_ASSIGN_KEPT (purpose:reason,…, e.g. agent.new:customized). False for what is not a built-in preset."""
    try:
        b = json.loads(body or b"{}") or {}
    except ValueError:
        return False
    lang = ready_lang(handler)
    pr = next((x for x in readiness_mock.builtin_presets(lang) if x["id"] == b.get("preset")), None)
    if pr is None:
        return False
    if p == "/api/v1/launchers/test":
        PROVIDER_LOG["test"].append(_provider_redacted(b))
        key, model = b.get("api_key") or "", b.get("model") or pr.get("model", "")
        for word, status in (("bad", "status_401"), ("forbid", "status_403"), ("nopath", "status_404"), ("busy", "status_429")):
            if word in key:
                handler.send_json({"ok": False, "ms": 233, "model": model, "error": readiness_mock.t(lang, "assistant-models_probe." + status)})
                return True
        if "slow" in key:
            handler.send_json({"ok": False, "ms": 30000, "model": model, "error": readiness_mock.t(lang, "assistant-models_probe.timeout", seconds=30)})
            return True
        if "region" in key:
            msg, code = readiness_mock.region_blocked(lang)
            handler.send_json({"ok": False, "ms": 180, "model": model, "error": msg, "code": code})
            return True
        handler.send_json({"ok": True, "ms": 412, "model": model})
        return True
    PROVIDER_LOG["post"] = _provider_redacted(b)
    name, n = (b.get("name") or "").strip(), 1
    if not name:
        name, n = launcher_name_for(launcher_slug(pr["id"].split("/", 1)[1]) or "provider")
    if any(l["name"] == name for l in LAUNCHERS):
        handler.send_json({"error": "已经有叫 %s 的启动器了" % name}, 409)
        return True
    display = (b.get("display_name") or "").strip() or (pr.get("display_name", "") + ("" if n == 1 else " %d" % n))
    l = {"name": name, "display_name": display, "source": "persona", "kind": "launcher", "api": "messages", "base_url": pr["base_url"],
         "auth": pr.get("auth", "api_key"), "model": b.get("model") or pr.get("model", ""), "has_key": bool(b.get("api_key")),
         "origin": "preset:" + pr["id"]}
    LAUNCHERS.insert(0, l)
    out = {"launcher": l}
    if b.get("assign") is not None:
        kept = dict(x.split(":", 1) for x in os.environ.get("MOCK_ASSIGN_KEPT", "").split(",") if ":" in x)
        out["assigned"] = [x for x in b["assign"] if x not in kept]
        out["kept"] = [{"purpose": x, "reason": kept[x]} for x in b["assign"] if x in kept]
    handler.send_json(out)
    return True


if READINESS or BUILTIN_PRESETS:
    def _readiness_route(handler, p, body):
        method = handler.command
        if p == "/api/v1/launchers/presets" and method == "GET":
            handler.send_json({"presets": readiness_mock.merge_presets(readiness_mock.builtin_presets(ready_lang(handler)), LAUNCHER_PRESETS)})
            return True
        if p in ("/api/v1/launchers", "/api/v1/launchers/test") and method == "POST":
            if _builtin_preset_route(handler, p, body):
                return True
        if not READINESS:
            return False
        lang = ready_lang(handler)
        assistant = p in ("/api/v1/assistant/readiness", "/api/v1/assistant/readiness/dismiss", "/api/v1/assistant/warm",
                          "/api/v1/assistant/conversations")
        if assistant and READY["sc"].get("assistant_offline"):
            status, reply = readiness_mock.refusal("assistant_offline", lang)
            handler.send_json(reply, status)
            return True
        if p == "/api/v1/assistant/readiness" and method == "GET":
            q = parse_qs(urlparse(handler.path).query).get("probe", [""])[0]
            probing = q in ("1", "true")
            if probing and READINESS_PROBE_DELAY:
                time.sleep(READINESS_PROBE_DELAY)
            if probing and READINESS_PROBE_ERROR:
                words = {"zh-Hans": "mock 探针没有回答", "en": "The mock probe did not answer",
                         "ja": "モックプローブが応答しませんでした"}[lang]
                handler.send_json({"error": words, "code": "probe_failed", "retryable": True}, READINESS_PROBE_ERROR)
                return True
            handler.send_json(ready_state(handler, probing))
            return True
        if p == "/api/v1/assistant/readiness/dismiss" and method == "POST":
            try:
                req = json.loads(body) if body else {}
            except ValueError as e:
                handler.send_json({"error": str(e), "code": "bad_request", "retryable": False}, 400)
                return True
            READY["dismissed"] = req.get("dismissed") is not False  # an empty body dismisses
            handler.send_json({"ok": True})
            return True
        if p == "/api/v1/assistant/warm" and method == "POST":
            handler.send_json({"ok": True, "readiness": ready_state(handler)})
            return True
        if p == "/api/v1/assistant/conversations" and method == "POST":
            m = ready_machine()
            code = os.environ.get("MOCK_START_ERROR", "")
            if not code:
                if m is None:
                    code = "no_machine"
                elif m["pending"]:
                    code = "machine_pending"
                elif not m["online"]:
                    code = "node_unreachable"
                elif READY["sc"].get("claude") == "missing":
                    code = "claude_missing"
                elif READY["sc"].get("claude") == "launcher_missing":
                    code = "launcher_missing"
            if code:
                status, reply = readiness_mock.refusal(code, lang, m["name"] if m and code != "no_machine" else "",
                                                       ASSISTANT_CONFIG["launcher"] or "claude")
                handler.send_json(reply, status)
                return True
            return False
        if p == "/api/v1/sessions" and method == "POST":
            mid = (json.loads(body or b"{}") or {}).get("machine_id", "")
            if any(x["id"] == mid and x.get("trust") == "pending" for x in MACHINES):
                status, reply = readiness_mock.pending_agent_refusal(lang)
                handler.send_json(reply, status)
                return True
        return False

    _plugins_route_without_readiness = plugins_route

    def plugins_route(handler, p, body):
        if _readiness_route(handler, p, body): return True
        return _plugins_route_without_readiness(handler, p, body)


